insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (303, 33, 31, 35, 'سورة الأحزاب ٣١ – ٣٥', '«يا نساء النبي لستنّ كأحد من النساء»، و«إنما يريد الله ليذهب عنكم الرجس أهل البيت»، و«إن المسلمين والمسلمات… أعدّ الله لهم مغفرة وأجراً عظيماً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 303) = $j$[{"lbl": "الآيات ٣١ – ٣٤", "q": "۞وَمَن يَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَٰلِحٗا نُّؤۡتِهَآ أَجۡرَهَا مَرَّتَيۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقٗا كَرِيمٗا ﴿٣١﴾ يَٰنِسَآءَ ٱلنَّبِيِّ لَسۡتُنَّ كَأَحَدٖ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيۡتُنَّۚ فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَيَطۡمَعَ ٱلَّذِي فِي قَلۡبِهِۦ مَرَضٞ وَقُلۡنَ قَوۡلٗا مَّعۡرُوفٗا ﴿٣٢﴾ وَقَرۡنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجۡنَ تَبَرُّجَ ٱلۡجَٰهِلِيَّةِ ٱلۡأُولَىٰۖ وَأَقِمۡنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعۡنَ ٱللَّهَ وَرَسُولَهُۥٓۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ وَيُطَهِّرَكُمۡ تَطۡهِيرٗا ﴿٣٣﴾ وَٱذۡكُرۡنَ مَا يُتۡلَىٰ فِي بُيُوتِكُنَّ مِنۡ ءَايَٰتِ ٱللَّهِ وَٱلۡحِكۡمَةِۚ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا ﴿٣٤﴾", "w": [["ومن يقنت منكن", "ومن يطع منكن الله ورسوله."], ["نؤتها أجرها مرتين", "نضاعف لها أجر عملها الصالح."], ["وأعتدنا لها رزقاً كريماً", "في الجنة."], ["لستنّ كأحد من النساء", "لستنّ في الفضل كسائر النساء إن اتّقيتنّ."], ["فلا تخضعن بالقول", "لا ترقّقن العبارة."], ["فيطمع الذي في قلبه مرض", "مرض النفاق أو الشهوة."], ["وقلن قولاً معروفاً", "يؤدي المعنى المطلوب بلا زيادة ولا رقّة."], ["وقرن في بيوتكن", "اثبتن فيها ولا تخرجن إلا لحاجة."], ["ولا تبرّجن تبرّج الجاهلية الأولى", "لا تتزيّن وتخرجن متبخترات كنساء الجاهلية قبل الإسلام."], ["ليذهب عنكم الرجس", "ليطهّركنّ من الأدناس والرذائل."], ["واذكرن ما يُتلى في بيوتكنّ", "من الكتاب والسنّة."]], "m": "بعد أن اخترن الله ورسوله والدار الآخرة أصبح لأزواج النبي ﷺ رفعة وشأن، فقال تعالى: ومن تطع منكنّ الله ورسوله وتعمل صالحاً من النوافل نؤتها أجرها مرتين، وأعتدنا لها رزقاً كريماً في الجنة. يا نساء النبي لستنّ كسائر النساء في الفضل، وأنتنّ أمهات المؤمنين وزوجات خاتم النبيين، إن اتّقيتنّ الله، فبدون التقوى لا شيء يُذكر، فلا ترقّقن الكلام إذا كلّمتنّ الأجانب فيطمع الذي في قلبه نفاق أو شهوة، وقلن قولاً يؤدي المعنى بلا زيادة. واثبتن في بيوتكنّ ولا تخرجن إلا لحاجة، وإذا خرجتنّ فلا تتبرّجن تبرّج الجاهلية الأولى متبخترات متكسّرات تفتنّ الرجال، وأقمن الصلاة، وآتين الزكاة، وأطعن الله ورسوله، إنما أمركنّ بذلك ليذهب عنكم الدنس والإثم أهل البيت ويطهّركم تطهيراً تاماً، وأهل البيت هنا أزواجه ﷺ، وفاطمة والحسن والحسين وعليّ رضي الله عنهم أجمعين. واذكرن ما يُتلى في بيوتكنّ من آيات الله والسنّة، فاشكرن الله على ذلك، إن الله كان لطيفاً خبيراً.", "h": ["لا شرف إلا بالتقوى: «إن أكرمكم عند الله أتقاكم».", "بيان فضل نساء النبي ﷺ وشرفهن.", "حرمة ترقيق المرأة صوتها وتليين عباراتها إذا تكلّمت مع أجنبي.", "وجوب بقاء النساء في منازلهن، ولا يخرجن إلا لحاجة لا بد منها.", "حرمة التبرّج، وهو أن تتزيّن المرأة وتخرج بادية المحاسن متبخترة.", "على المسلم أن يذكر ما شرّفه الله به من الإيمان والإسلام ليشكره.", "بيان أن الحكمة هي السنّة النبوية الصحيحة.", "الإشارة إلى وجود جاهلية ثانية، وقد ظهرت منذ نصف قرن، وهي تبرّج النساء كاشفات الرؤوس والصدور والسيقان."], "k": "«واذكرن ما يُتلى في بيوتكنّ من آيات الله والحكمة»… ما الذي يُتلى في بيتي أكثر: آيات الله أم غيرها؟"}, {"lbl": "الآية ٣٥", "q": "إِنَّ ٱلۡمُسۡلِمِينَ وَٱلۡمُسۡلِمَٰتِ وَٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ وَٱلۡقَٰنِتِينَ وَٱلۡقَٰنِتَٰتِ وَٱلصَّـٰدِقِينَ وَٱلصَّـٰدِقَٰتِ وَٱلصَّـٰبِرِينَ وَٱلصَّـٰبِرَٰتِ وَٱلۡخَٰشِعِينَ وَٱلۡخَٰشِعَٰتِ وَٱلۡمُتَصَدِّقِينَ وَٱلۡمُتَصَدِّقَٰتِ وَٱلصَّـٰٓئِمِينَ وَٱلصَّـٰٓئِمَٰتِ وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ وَٱلذَّـٰكِرِينَ ٱللَّهَ كَثِيرٗا وَٱلذَّـٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمٗا ﴿٣٥﴾", "w": [["إن المسلمين والمسلمات", "الذين أسلموا لله وجوههم فانقادوا لأمره."], ["والمؤمنين والمؤمنات", "المصدّقين بالله رباً وإلهاً، وبمحمد نبياً، وبالإسلام ديناً."], ["والقانتين والقانتات", "المطيعين لله ورسوله."], ["والصادقين والصادقات", "في أقوالهم وأفعالهم."], ["والصابرين والصابرات", "الحابسين نفوسهم على الطاعات وعن المعاصي وعلى البلاء."], ["والخاشعين والخاشعات", "المتذلّلين لله المخبتين له."], ["والمتصدّقين والمتصدّقات", "المؤدّين الزكاة والفضل من أموالهم."], ["والحافظين فروجهم والحافظات", "عن الحرام."], ["والذاكرين الله كثيراً والذاكرات", "بالألسن والقلوب."], ["وأجراً عظيماً", "الجنة دار الأبرار."]], "m": "نزلت هذه الآية جواباً لبعض أزواج النبي ﷺ إذ قلن: ما لنا لا نُذكر في القرآن كما يُذكر الرجال؟ ومناسبتها لما قبلها أنه لما أثنى على آل البيت تشوّقت النفوس لخير مثله، فذكر تعالى أن المسلمين والمسلمات المنقادين لأمر الله، والمؤمنين والمؤمنات المصدّقين، والقانتين والقانتات المطيعين في السراء والضراء، والصادقين والصادقات، والصابرين والصابرات على الطاعات وعن المعاصي وعلى البلاء رضاً وتسليماً، والخاشعين والخاشعات في صلاتهم وطاعاتهم، والمتصدّقين والمتصدّقات بالزكاة وفضول الأموال، والصائمين والصائمات الفرض والنفل، والحافظين فروجهم والحافظات عما حرّم الله، والذاكرين الله كثيراً بالليل والنهار والذاكرات، أعدّ الله لهم جميعاً مغفرة لذنوبهم، وأجراً عظيماً هو الجنة.", "h": ["بشرى المسلمين والمسلمات بمغفرة ذنوبهم ودخول الجنة إن اتّصفوا بالصفات المذكورة في هذه الآية، وهي عشر صفات أولها الإسلام وآخرها ذكر الله كثيراً.", "فضل الصفات المذكورة، إذ كانت سبباً في دخول الجنة بعد مغفرة الذنوب.", "تقرير مبدأ التساوي بين الرجال والنساء في العمل والجزاء فيما يشتركون فيه، وأما ما خُصّ به أحدهما فهو على خصوصيّته."], "k": "«والذاكرين الله كثيراً والذاكرات»… عشر صفات خُتمت بالذكر؛ فأيّها أقوى عندي، وأيّها أضعف؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 303;
insert into public.tdb_cards(topic, i, body) select 303, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣١ – ٣٤", "q": "۞وَمَن يَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَٰلِحٗا نُّؤۡتِهَآ أَجۡرَهَا مَرَّتَيۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقٗا كَرِيمٗا ﴿٣١﴾ يَٰنِسَآءَ ٱلنَّبِيِّ لَسۡتُنَّ كَأَحَدٖ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيۡتُنَّۚ فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَيَطۡمَعَ ٱلَّذِي فِي قَلۡبِهِۦ مَرَضٞ وَقُلۡنَ قَوۡلٗا مَّعۡرُوفٗا ﴿٣٢﴾ وَقَرۡنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجۡنَ تَبَرُّجَ ٱلۡجَٰهِلِيَّةِ ٱلۡأُولَىٰۖ وَأَقِمۡنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعۡنَ ٱللَّهَ وَرَسُولَهُۥٓۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ وَيُطَهِّرَكُمۡ تَطۡهِيرٗا ﴿٣٣﴾ وَٱذۡكُرۡنَ مَا يُتۡلَىٰ فِي بُيُوتِكُنَّ مِنۡ ءَايَٰتِ ٱللَّهِ وَٱلۡحِكۡمَةِۚ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا ﴿٣٤﴾", "w": [["ومن يقنت منكن", "ومن يطع منكن الله ورسوله."], ["نؤتها أجرها مرتين", "نضاعف لها أجر عملها الصالح."], ["وأعتدنا لها رزقاً كريماً", "في الجنة."], ["لستنّ كأحد من النساء", "لستنّ في الفضل كسائر النساء إن اتّقيتنّ."], ["فلا تخضعن بالقول", "لا ترقّقن العبارة."], ["فيطمع الذي في قلبه مرض", "مرض النفاق أو الشهوة."], ["وقلن قولاً معروفاً", "يؤدي المعنى المطلوب بلا زيادة ولا رقّة."], ["وقرن في بيوتكن", "اثبتن فيها ولا تخرجن إلا لحاجة."], ["ولا تبرّجن تبرّج الجاهلية الأولى", "لا تتزيّن وتخرجن متبخترات كنساء الجاهلية قبل الإسلام."], ["ليذهب عنكم الرجس", "ليطهّركنّ من الأدناس والرذائل."], ["واذكرن ما يُتلى في بيوتكنّ", "من الكتاب والسنّة."]], "m": "بعد أن اخترن الله ورسوله والدار الآخرة أصبح لأزواج النبي ﷺ رفعة وشأن، فقال تعالى: ومن تطع منكنّ الله ورسوله وتعمل صالحاً من النوافل نؤتها أجرها مرتين، وأعتدنا لها رزقاً كريماً في الجنة. يا نساء النبي لستنّ كسائر النساء في الفضل، وأنتنّ أمهات المؤمنين وزوجات خاتم النبيين، إن اتّقيتنّ الله، فبدون التقوى لا شيء يُذكر، فلا ترقّقن الكلام إذا كلّمتنّ الأجانب فيطمع الذي في قلبه نفاق أو شهوة، وقلن قولاً يؤدي المعنى بلا زيادة. واثبتن في بيوتكنّ ولا تخرجن إلا لحاجة، وإذا خرجتنّ فلا تتبرّجن تبرّج الجاهلية الأولى متبخترات متكسّرات تفتنّ الرجال، وأقمن الصلاة، وآتين الزكاة، وأطعن الله ورسوله، إنما أمركنّ بذلك ليذهب عنكم الدنس والإثم أهل البيت ويطهّركم تطهيراً تاماً، وأهل البيت هنا أزواجه ﷺ، وفاطمة والحسن والحسين وعليّ رضي الله عنهم أجمعين. واذكرن ما يُتلى في بيوتكنّ من آيات الله والسنّة، فاشكرن الله على ذلك، إن الله كان لطيفاً خبيراً.", "h": ["لا شرف إلا بالتقوى: «إن أكرمكم عند الله أتقاكم».", "بيان فضل نساء النبي ﷺ وشرفهن.", "حرمة ترقيق المرأة صوتها وتليين عباراتها إذا تكلّمت مع أجنبي.", "وجوب بقاء النساء في منازلهن، ولا يخرجن إلا لحاجة لا بد منها.", "حرمة التبرّج، وهو أن تتزيّن المرأة وتخرج بادية المحاسن متبخترة.", "على المسلم أن يذكر ما شرّفه الله به من الإيمان والإسلام ليشكره.", "بيان أن الحكمة هي السنّة النبوية الصحيحة.", "الإشارة إلى وجود جاهلية ثانية، وقد ظهرت منذ نصف قرن، وهي تبرّج النساء كاشفات الرؤوس والصدور والسيقان."], "k": "«واذكرن ما يُتلى في بيوتكنّ من آيات الله والحكمة»… ما الذي يُتلى في بيتي أكثر: آيات الله أم غيرها؟"}, {"lbl": "الآية ٣٥", "q": "إِنَّ ٱلۡمُسۡلِمِينَ وَٱلۡمُسۡلِمَٰتِ وَٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ وَٱلۡقَٰنِتِينَ وَٱلۡقَٰنِتَٰتِ وَٱلصَّـٰدِقِينَ وَٱلصَّـٰدِقَٰتِ وَٱلصَّـٰبِرِينَ وَٱلصَّـٰبِرَٰتِ وَٱلۡخَٰشِعِينَ وَٱلۡخَٰشِعَٰتِ وَٱلۡمُتَصَدِّقِينَ وَٱلۡمُتَصَدِّقَٰتِ وَٱلصَّـٰٓئِمِينَ وَٱلصَّـٰٓئِمَٰتِ وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ وَٱلذَّـٰكِرِينَ ٱللَّهَ كَثِيرٗا وَٱلذَّـٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمٗا ﴿٣٥﴾", "w": [["إن المسلمين والمسلمات", "الذين أسلموا لله وجوههم فانقادوا لأمره."], ["والمؤمنين والمؤمنات", "المصدّقين بالله رباً وإلهاً، وبمحمد نبياً، وبالإسلام ديناً."], ["والقانتين والقانتات", "المطيعين لله ورسوله."], ["والصادقين والصادقات", "في أقوالهم وأفعالهم."], ["والصابرين والصابرات", "الحابسين نفوسهم على الطاعات وعن المعاصي وعلى البلاء."], ["والخاشعين والخاشعات", "المتذلّلين لله المخبتين له."], ["والمتصدّقين والمتصدّقات", "المؤدّين الزكاة والفضل من أموالهم."], ["والحافظين فروجهم والحافظات", "عن الحرام."], ["والذاكرين الله كثيراً والذاكرات", "بالألسن والقلوب."], ["وأجراً عظيماً", "الجنة دار الأبرار."]], "m": "نزلت هذه الآية جواباً لبعض أزواج النبي ﷺ إذ قلن: ما لنا لا نُذكر في القرآن كما يُذكر الرجال؟ ومناسبتها لما قبلها أنه لما أثنى على آل البيت تشوّقت النفوس لخير مثله، فذكر تعالى أن المسلمين والمسلمات المنقادين لأمر الله، والمؤمنين والمؤمنات المصدّقين، والقانتين والقانتات المطيعين في السراء والضراء، والصادقين والصادقات، والصابرين والصابرات على الطاعات وعن المعاصي وعلى البلاء رضاً وتسليماً، والخاشعين والخاشعات في صلاتهم وطاعاتهم، والمتصدّقين والمتصدّقات بالزكاة وفضول الأموال، والصائمين والصائمات الفرض والنفل، والحافظين فروجهم والحافظات عما حرّم الله، والذاكرين الله كثيراً بالليل والنهار والذاكرات، أعدّ الله لهم جميعاً مغفرة لذنوبهم، وأجراً عظيماً هو الجنة.", "h": ["بشرى المسلمين والمسلمات بمغفرة ذنوبهم ودخول الجنة إن اتّصفوا بالصفات المذكورة في هذه الآية، وهي عشر صفات أولها الإسلام وآخرها ذكر الله كثيراً.", "فضل الصفات المذكورة، إذ كانت سبباً في دخول الجنة بعد مغفرة الذنوب.", "تقرير مبدأ التساوي بين الرجال والنساء في العمل والجزاء فيما يشتركون فيه، وأما ما خُصّ به أحدهما فهو على خصوصيّته."], "k": "«والذاكرين الله كثيراً والذاكرات»… عشر صفات خُتمت بالذكر؛ فأيّها أقوى عندي، وأيّها أضعف؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (304, 33, 36, 44, 'سورة الأحزاب ٣٦ – ٤٤', '«وما كان لمؤمن ولا مؤمنة إذا قضى الله ورسوله أمراً أن يكون لهم الخيرة»، و«ما كان محمد أبا أحد من رجالكم ولكن رسول الله وخاتم النبيين»، و«اذكروا الله ذكراً كثيراً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 304) = $j$[{"lbl": "الآيات ٣٦ – ٤٠", "q": "وَمَا كَانَ لِمُؤۡمِنٖ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمۡرًا أَن يَكُونَ لَهُمُ ٱلۡخِيَرَةُ مِنۡ أَمۡرِهِمۡۗ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ ضَلَّ ضَلَٰلٗا مُّبِينٗا ﴿٣٦﴾ وَإِذۡ تَقُولُ لِلَّذِيٓ أَنۡعَمَ ٱللَّهُ عَلَيۡهِ وَأَنۡعَمۡتَ عَلَيۡهِ أَمۡسِكۡ عَلَيۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ وَتُخۡفِي فِي نَفۡسِكَ مَا ٱللَّهُ مُبۡدِيهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ فَلَمَّا قَضَىٰ زَيۡدٞ مِّنۡهَا وَطَرٗا زَوَّجۡنَٰكَهَا لِكَيۡ لَا يَكُونَ عَلَى ٱلۡمُؤۡمِنِينَ حَرَجٞ فِيٓ أَزۡوَٰجِ أَدۡعِيَآئِهِمۡ إِذَا قَضَوۡاْ مِنۡهُنَّ وَطَرٗاۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولٗا ﴿٣٧﴾ مَّا كَانَ عَلَى ٱلنَّبِيِّ مِنۡ حَرَجٖ فِيمَا فَرَضَ ٱللَّهُ لَهُۥۖ سُنَّةَ ٱللَّهِ فِي ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۚ وَكَانَ أَمۡرُ ٱللَّهِ قَدَرٗا مَّقۡدُورًا ﴿٣٨﴾ ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخۡشَوۡنَهُۥ وَلَا يَخۡشَوۡنَ أَحَدًا إِلَّا ٱللَّهَۗ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا ﴿٣٩﴾ مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٖ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا ﴿٤٠﴾", "w": [["ما كان لمؤمن ولا مؤمنة", "لا ينبغي ولا يصلح."], ["أن يكون لهم الخيرة من أمرهم", "حق الاختيار فيما حكم الله ورسوله فيه."], ["أنعم الله عليه وأنعمت عليه", "أنعم الله عليه بالإسلام، وأنعمت عليه بالعتق."], ["واتّق الله", "في أمر زوجتك فلا تحاول طلاقها."], ["وتخفي في نفسك", "علمك بأن زيداً إذا طلّق زينب زوّجكها الله إبطالاً لحرمة زوجة المتبنّى."], ["وتخشى الناس", "أن يقولوا: تزوّج محمد مطلّقة مولاه زيد."], ["فلما قضى زيد منها وطراً", "حاجته منها ولم يبق له فيها رغبة."], ["زوّجناكها", "تولّى الله عقد نكاحها."], ["كيلا يكون على المؤمنين حرج", "إثم في تزوّج مطلّقات أدعيائهم."], ["وخاتم النبيين", "لا نبي بعده."]], "m": "هذا شروع في قصة زواج زيد بن حارثة مولى رسول الله ﷺ بزينب بنت جحش ابنة عمته، فإن الله أبطل التبنّي وأحكامه، ومن تلك الأحكام حرمة مطلّقة الدعيّ على من تبنّاه، وليس من السهل على الناس أن يتقبّلوها، فشاء الله إخراجها إلى الوجود، فألهم رسوله أن يخطب زينب لمولاه زيد، فظنّت أنها مخطوبة لرسول الله، فلما تبيّن لها أنها لزيد أخذتها الحمية ونصرها أخوها، فنزل: وما كان لمؤمن ولا مؤمنة إذا قضى الله ورسوله أمراً أن يكون لهم الخيرة، ومن يعص الله ورسوله فقد ضلّ ضلالاً مبيناً، فقبلت عن رضى وتزوّجها زيد. ثم ترفّعت عليه بشرفها، فكان يستأذن رسول الله في طلاقها، والرسول يقول: أمسك عليك زوجك واتّق الله، ويخفي في نفسه ما الله مبديه من زواجه منها، ويخشى أن يقول الناس: تزوّج امرأة ابنه، والله أحق أن تخشاه. فلما قضى زيد منها حاجته وطلّقها وانقضت عدّتها زوّجناكها، تولّى الله عقد نكاحها، لكيلا يكون على المؤمنين إثم في أزواج أدعيائهم، وكان أمر الله مفعولاً. ما كان على النبي من حرج فيما فرض الله له، سنّة الله في الأنبياء الذين يبلّغون رسالات الله ويخشونه ولا يخشون أحداً إلا الله. ما كان محمد أبا أحد من رجالكم، لا زيد ولا غيره، ولكن رسول الله وخاتم النبيين، فلو كان له ولد ذكر بالغ لكان نبياً، ولذا توفّاهم الله صغاراً.", "h": ["بيان أن المؤمن الحق لا خيرة عنده في أمر قضى فيه الله ورسوله.", "بيان أن من يعص الله ورسوله يخرج عن طريق الهداية إلى طريق الضلال.", "جواز عتاب الله تعالى لرسوله ﷺ.", "بيان شدة حياء الرسول ﷺ.", "بيان إكرام الله لزيد، بأن جعل اسمه يُقرأ على ألسنة المؤمنين إلى يوم القيامة.", "بيان إفضال الله على زينب لما سلّمت أمرها لله، فجعلها زوجة لرسول الله، وتولّى عقد نكاحها.", "تقرير حديث: «ما ترك عبد شيئاً لله إلا عوّضه الله خيراً منه».", "إبطال أحكام التبنّي التي كانت في الجاهلية.", "تقرير أن محمداً ﷺ خاتم الأنبياء فلا نبي بعده."], "k": "«أن يكون لهم الخيرة من أمرهم»… حين يأتيني حكم لا يوافق هواي، هل أسلّم كما سلّمت زينب؟"}, {"lbl": "الآيات ٤١ – ٤٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ﴿٤١﴾ وَسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا ﴿٤٢﴾ هُوَ ٱلَّذِي يُصَلِّي عَلَيۡكُمۡ وَمَلَـٰٓئِكَتُهُۥ لِيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَكَانَ بِٱلۡمُؤۡمِنِينَ رَحِيمٗا ﴿٤٣﴾ تَحِيَّتُهُمۡ يَوۡمَ يَلۡقَوۡنَهُۥ سَلَٰمٞۚ وَأَعَدَّ لَهُمۡ أَجۡرٗا كَرِيمٗا ﴿٤٤﴾", "w": [["اذكروا الله ذكراً كثيراً", "بقلوبكم وألسنتكم."], ["وسبّحوه بكرة وأصيلاً", "نزّهوه بقول: سبحان الله وبحمده، صباحاً ومساءً."], ["هو الذي يصلّي عليكم", "يرحمكم."], ["وملائكته", "يستغفرون لكم."], ["ليخرجكم من الظلمات", "ليديم إخراجكم من ظلمات الكفر والمعاصي إلى نور الإيمان والطاعات."], ["تحيّتهم يوم يلقونه سلام", "تسلّم عليهم الملائكة."], ["وأعدّ لهم أجراً كريماً", "هيّأ لهم الجنة."]], "m": "هذا نداء كريم من رب رحيم للمؤمنين يعلّمهم ما به كمالهم ونورهم ويحفظون به من عدوهم: يا أيها الذين آمنوا اذكروا الله ذكراً كثيراً لا حد له، إذ هو الطاقة التي تعين على الحياة، وسبّحوه بكرة وأصيلاً، بصلاة الصبح والعصر وسائر الصلوات وقول: سبحان الله والحمد لله. هو الذي يرحمكم، وملائكته تستغفر لكم، ليُديم إخراجكم من ظلمات الكفر والمعاصي إلى نور الإيمان والطاعات، وكان بالمؤمنين رحيماً فلا يعذّبهم. تحيّتهم يوم يلقونه في دار السلام: سلام عليكم، أمان لكم فلا خوف ولا حزن، وأعدّ لهم أجراً كريماً هو الجنة. فسبحان الله ما أكرمه، طلب منهم أن يذكروه ويسبّحوه، وأعطاهم ما لا يُقدّر قدره.", "h": ["وجوب ذكر الله تعالى كثيراً ليل نهار، ووجوب تسبيحه صباح مساء.", "فضل الله على المؤمنين بصلاته عليهم وصلاة ملائكته ورحمته لهم.", "تقرير عقيدة البعث بذكر بعض ما يتم فيها من سلام الملائكة على أهل الجنة.", "بشرى المؤمنين الصادقين بالجنة."], "k": "«هو الذي يصلّي عليكم وملائكته»… أذكره قليلاً فيذكرني رحمة ومغفرة؛ فكم ذكرته اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 304;
insert into public.tdb_cards(topic, i, body) select 304, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٦ – ٤٠", "q": "وَمَا كَانَ لِمُؤۡمِنٖ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمۡرًا أَن يَكُونَ لَهُمُ ٱلۡخِيَرَةُ مِنۡ أَمۡرِهِمۡۗ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ ضَلَّ ضَلَٰلٗا مُّبِينٗا ﴿٣٦﴾ وَإِذۡ تَقُولُ لِلَّذِيٓ أَنۡعَمَ ٱللَّهُ عَلَيۡهِ وَأَنۡعَمۡتَ عَلَيۡهِ أَمۡسِكۡ عَلَيۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ وَتُخۡفِي فِي نَفۡسِكَ مَا ٱللَّهُ مُبۡدِيهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ فَلَمَّا قَضَىٰ زَيۡدٞ مِّنۡهَا وَطَرٗا زَوَّجۡنَٰكَهَا لِكَيۡ لَا يَكُونَ عَلَى ٱلۡمُؤۡمِنِينَ حَرَجٞ فِيٓ أَزۡوَٰجِ أَدۡعِيَآئِهِمۡ إِذَا قَضَوۡاْ مِنۡهُنَّ وَطَرٗاۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولٗا ﴿٣٧﴾ مَّا كَانَ عَلَى ٱلنَّبِيِّ مِنۡ حَرَجٖ فِيمَا فَرَضَ ٱللَّهُ لَهُۥۖ سُنَّةَ ٱللَّهِ فِي ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۚ وَكَانَ أَمۡرُ ٱللَّهِ قَدَرٗا مَّقۡدُورًا ﴿٣٨﴾ ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخۡشَوۡنَهُۥ وَلَا يَخۡشَوۡنَ أَحَدًا إِلَّا ٱللَّهَۗ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا ﴿٣٩﴾ مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٖ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا ﴿٤٠﴾", "w": [["ما كان لمؤمن ولا مؤمنة", "لا ينبغي ولا يصلح."], ["أن يكون لهم الخيرة من أمرهم", "حق الاختيار فيما حكم الله ورسوله فيه."], ["أنعم الله عليه وأنعمت عليه", "أنعم الله عليه بالإسلام، وأنعمت عليه بالعتق."], ["واتّق الله", "في أمر زوجتك فلا تحاول طلاقها."], ["وتخفي في نفسك", "علمك بأن زيداً إذا طلّق زينب زوّجكها الله إبطالاً لحرمة زوجة المتبنّى."], ["وتخشى الناس", "أن يقولوا: تزوّج محمد مطلّقة مولاه زيد."], ["فلما قضى زيد منها وطراً", "حاجته منها ولم يبق له فيها رغبة."], ["زوّجناكها", "تولّى الله عقد نكاحها."], ["كيلا يكون على المؤمنين حرج", "إثم في تزوّج مطلّقات أدعيائهم."], ["وخاتم النبيين", "لا نبي بعده."]], "m": "هذا شروع في قصة زواج زيد بن حارثة مولى رسول الله ﷺ بزينب بنت جحش ابنة عمته، فإن الله أبطل التبنّي وأحكامه، ومن تلك الأحكام حرمة مطلّقة الدعيّ على من تبنّاه، وليس من السهل على الناس أن يتقبّلوها، فشاء الله إخراجها إلى الوجود، فألهم رسوله أن يخطب زينب لمولاه زيد، فظنّت أنها مخطوبة لرسول الله، فلما تبيّن لها أنها لزيد أخذتها الحمية ونصرها أخوها، فنزل: وما كان لمؤمن ولا مؤمنة إذا قضى الله ورسوله أمراً أن يكون لهم الخيرة، ومن يعص الله ورسوله فقد ضلّ ضلالاً مبيناً، فقبلت عن رضى وتزوّجها زيد. ثم ترفّعت عليه بشرفها، فكان يستأذن رسول الله في طلاقها، والرسول يقول: أمسك عليك زوجك واتّق الله، ويخفي في نفسه ما الله مبديه من زواجه منها، ويخشى أن يقول الناس: تزوّج امرأة ابنه، والله أحق أن تخشاه. فلما قضى زيد منها حاجته وطلّقها وانقضت عدّتها زوّجناكها، تولّى الله عقد نكاحها، لكيلا يكون على المؤمنين إثم في أزواج أدعيائهم، وكان أمر الله مفعولاً. ما كان على النبي من حرج فيما فرض الله له، سنّة الله في الأنبياء الذين يبلّغون رسالات الله ويخشونه ولا يخشون أحداً إلا الله. ما كان محمد أبا أحد من رجالكم، لا زيد ولا غيره، ولكن رسول الله وخاتم النبيين، فلو كان له ولد ذكر بالغ لكان نبياً، ولذا توفّاهم الله صغاراً.", "h": ["بيان أن المؤمن الحق لا خيرة عنده في أمر قضى فيه الله ورسوله.", "بيان أن من يعص الله ورسوله يخرج عن طريق الهداية إلى طريق الضلال.", "جواز عتاب الله تعالى لرسوله ﷺ.", "بيان شدة حياء الرسول ﷺ.", "بيان إكرام الله لزيد، بأن جعل اسمه يُقرأ على ألسنة المؤمنين إلى يوم القيامة.", "بيان إفضال الله على زينب لما سلّمت أمرها لله، فجعلها زوجة لرسول الله، وتولّى عقد نكاحها.", "تقرير حديث: «ما ترك عبد شيئاً لله إلا عوّضه الله خيراً منه».", "إبطال أحكام التبنّي التي كانت في الجاهلية.", "تقرير أن محمداً ﷺ خاتم الأنبياء فلا نبي بعده."], "k": "«أن يكون لهم الخيرة من أمرهم»… حين يأتيني حكم لا يوافق هواي، هل أسلّم كما سلّمت زينب؟"}, {"lbl": "الآيات ٤١ – ٤٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ﴿٤١﴾ وَسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا ﴿٤٢﴾ هُوَ ٱلَّذِي يُصَلِّي عَلَيۡكُمۡ وَمَلَـٰٓئِكَتُهُۥ لِيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَكَانَ بِٱلۡمُؤۡمِنِينَ رَحِيمٗا ﴿٤٣﴾ تَحِيَّتُهُمۡ يَوۡمَ يَلۡقَوۡنَهُۥ سَلَٰمٞۚ وَأَعَدَّ لَهُمۡ أَجۡرٗا كَرِيمٗا ﴿٤٤﴾", "w": [["اذكروا الله ذكراً كثيراً", "بقلوبكم وألسنتكم."], ["وسبّحوه بكرة وأصيلاً", "نزّهوه بقول: سبحان الله وبحمده، صباحاً ومساءً."], ["هو الذي يصلّي عليكم", "يرحمكم."], ["وملائكته", "يستغفرون لكم."], ["ليخرجكم من الظلمات", "ليديم إخراجكم من ظلمات الكفر والمعاصي إلى نور الإيمان والطاعات."], ["تحيّتهم يوم يلقونه سلام", "تسلّم عليهم الملائكة."], ["وأعدّ لهم أجراً كريماً", "هيّأ لهم الجنة."]], "m": "هذا نداء كريم من رب رحيم للمؤمنين يعلّمهم ما به كمالهم ونورهم ويحفظون به من عدوهم: يا أيها الذين آمنوا اذكروا الله ذكراً كثيراً لا حد له، إذ هو الطاقة التي تعين على الحياة، وسبّحوه بكرة وأصيلاً، بصلاة الصبح والعصر وسائر الصلوات وقول: سبحان الله والحمد لله. هو الذي يرحمكم، وملائكته تستغفر لكم، ليُديم إخراجكم من ظلمات الكفر والمعاصي إلى نور الإيمان والطاعات، وكان بالمؤمنين رحيماً فلا يعذّبهم. تحيّتهم يوم يلقونه في دار السلام: سلام عليكم، أمان لكم فلا خوف ولا حزن، وأعدّ لهم أجراً كريماً هو الجنة. فسبحان الله ما أكرمه، طلب منهم أن يذكروه ويسبّحوه، وأعطاهم ما لا يُقدّر قدره.", "h": ["وجوب ذكر الله تعالى كثيراً ليل نهار، ووجوب تسبيحه صباح مساء.", "فضل الله على المؤمنين بصلاته عليهم وصلاة ملائكته ورحمته لهم.", "تقرير عقيدة البعث بذكر بعض ما يتم فيها من سلام الملائكة على أهل الجنة.", "بشرى المؤمنين الصادقين بالجنة."], "k": "«هو الذي يصلّي عليكم وملائكته»… أذكره قليلاً فيذكرني رحمة ومغفرة؛ فكم ذكرته اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (305, 33, 45, 52, 'سورة الأحزاب ٤٥ – ٥٢', '«إنا أرسلناك شاهداً ومبشراً ونذيراً وداعياً إلى الله بإذنه وسراجاً منيراً»، وأحكام الطلاق قبل الدخول، و«إنا أحللنا لك أزواجك»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 305) = $j$[{"lbl": "الآيات ٤٥ – ٤٨", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا ﴿٤٥﴾ وَدَاعِيًا إِلَى ٱللَّهِ بِإِذۡنِهِۦ وَسِرَاجٗا مُّنِيرٗا ﴿٤٦﴾ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضۡلٗا كَبِيرٗا ﴿٤٧﴾ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَ وَدَعۡ أَذَىٰهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا ﴿٤٨﴾", "w": [["شاهداً", "على من أرسلناك إليهم."], ["ومبشّراً", "من آمن وعمل صالحاً بالجنة."], ["ونذيراً", "من كفر وأشرك بالنار."], ["وداعياً إلى الله بإذنه", "إلى الإيمان به وتوحيده بأمره."], ["وسراجاً منيراً", "كالسراج المنير يهتدي به من أراد الهداية."], ["ولا تطع الكافرين والمنافقين", "فيما يخالف أمر ربك وما شرعه."], ["ودع أذاهم", "اتركه فلا تقابله بأذى حتى يأمرك ربك فيهم."], ["وتوكّل على الله", "فوّض أمرك إليه فإنه يكفيك."]], "m": "هذا نداء خاص بعد النداء العام لمزيد تكريم الرسول ﷺ: يا أيها النبي إنا أرسلناك شاهداً على من أرسلناك إليهم، من أجاب دعوتك ومن لم يجبها، ومبشّراً لمن آمن وعمل صالحاً بالجنة، ونذيراً لمن أعرض بعذاب النار، وداعياً إلى الله ليعبدوه ويوحّدوه بأمره لك بذلك، وسراجاً منيراً يهتدي بك من أراد الهداية. وبشّر المؤمنين الذين استجابوا بأن لهم من الله فضلاً كبيراً، الجنة. ولا تطع الكافرين والمنافقين فيما يقترحون عليك مما يتنافى مع رسالتك، ودع أذاهم فلا تقابله حتى يأمرك ربك، وتوكّل على الله في أمرك كله، وكفى بالله حافظاً يعصمك من الناس.", "h": ["بيان الكمال المحمدي الذي وهبه إياه ربه تبارك وتعالى.", "مشروعية الدعوة إلى الله إذا كان الداعي متأهّلاً بالعلم والحلم.", "حرمة طاعة الكافرين والمنافقين والفجرة والظالمين فيما يتنافى مع الشرع."], "k": "«وسراجاً منيراً»… النور الذي جاء به بين يديّ؛ فهل أمشي في ضوئه؟"}, {"lbl": "الآية ٤٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَيۡهِنَّ مِنۡ عِدَّةٖ تَعۡتَدُّونَهَاۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحٗا جَمِيلٗا ﴿٤٩﴾", "w": [["إذا نكحتم المؤمنات", "إذا عقدتم عليهن ولم تبنوا بهن."], ["من قبل أن تمسّوهن", "من قبل الخلوة بهن ووطئهن."], ["فما لكم عليهن من عدة", "ليس لكم مطالبتهن بالعدة."], ["فمتّعوهن", "أعطوهن شيئاً من المال يتمتّعن به جبراً لخاطرهن."], ["وسرّحوهن سراحاً جميلاً", "اتركوهن يذهبن إلى أهليهن من غير إضرار."]], "m": "ينادي الله عباده المؤمنين معلّماً: إذا عقدتم على المؤمنات ثم طلّقتموهن من قبل الدخول بهن، فما لكم عليهن من عدة تعتدّونها بالأقراء ولا بالشهور، إذ العدة لمعرفة ما في الرحم، وغير المدخول بها رحمها بريء، فإن كان سُمّي لهن مهر فلهن نصف المسمّى والمتعة استحباباً، وإن لم يُسمّ لهن مهر فليس لهن غير المتعة، وهي هنا واجبة بحسب يسار المطلّق وإعساره، وخلّوا سبيلهن يذهبن إلى ذويهن من غير إضرار.", "h": ["جواز الطلاق قبل البناء.", "ليس على المطلّقة قبل الدخول بها عدة، بل لها أن تتزوّج ساعة ما تُطلّق.", "المطلّقة قبل البناء إن سُمّي لها صداق فلها نصفه، وإن لم يُسمّ لها صداق فلها المتعة يقدّرها القاضي بحسب سعة المطلّق وضيقه.", "حرمة أذية المطلّقة بأي أذى، ووجوب تخلية سبيلها تذهب حيث شاءت.", "مشروعية المتعة لكل مطلّقة."], "k": "«وسرّحوهن سراحاً جميلاً»… حتى الفراق له أدب؛ فهل أفارق من أفارقه بالحسنى؟"}, {"lbl": "الآية ٥٠", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَحۡلَلۡنَا لَكَ أَزۡوَٰجَكَ ٱلَّـٰتِيٓ ءَاتَيۡتَ أُجُورَهُنَّ وَمَا مَلَكَتۡ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيۡكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّـٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّـٰتِي هَاجَرۡنَ مَعَكَ وَٱمۡرَأَةٗ مُّؤۡمِنَةً إِن وَهَبَتۡ نَفۡسَهَا لِلنَّبِيِّ إِنۡ أَرَادَ ٱلنَّبِيُّ أَن يَسۡتَنكِحَهَا خَالِصَةٗ لَّكَ مِن دُونِ ٱلۡمُؤۡمِنِينَۗ قَدۡ عَلِمۡنَا مَا فَرَضۡنَا عَلَيۡهِمۡ فِيٓ أَزۡوَٰجِهِمۡ وَمَا مَلَكَتۡ أَيۡمَٰنُهُمۡ لِكَيۡلَا يَكُونَ عَلَيۡكَ حَرَجٞۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿٥٠﴾", "w": [["آتيت أجورهن", "أعطيت مهورهن."], ["مما أفاء الله عليك", "مما يُسبى، كصفية وجويرية."], ["اللاتي هاجرن معك", "بخلاف من لم تهاجر وبقيت في دار الكفر."], ["وهبت نفسها للنبي", "بغير صداق، إن أراد النبي أن يتزوّجها."], ["خالصة لك من دون المؤمنين", "بدون صداق."], ["قد علمنا ما فرضنا عليهم في أزواجهم", "من الأحكام: ألا يزيدوا على أربع، وألا يتزوّجوا إلا بولي ومهر وشهود."], ["لكيلا يكون عليك حرج", "ضيق في النكاح."]], "m": "هذا النداء يحمل لرسول الله ﷺ إجازات تخفّف عنه ما يعانيه من أمور الرسالة: يا أيها النبي إنا أحللنا لك أزواجك اللاتي أعطيتهن مهورهن، وما ملكت يمينك مما أفاء الله عليك من سبايا الجهاد كصفية وجويرية، وبنات عمك وعماتك وخالك وخالاتك اللاتي هاجرن معك، أما اللاتي لم يهاجرن فلا يحللن لك، وامرأة مؤمنة إن وهبت نفسها للنبي بلا مهر إن أراد أن يستنكحها، خالصة لك دون المؤمنين، فالمؤمن لا تحل له الواهبة إلا بمهر. قد علمنا ما فرضنا على المؤمنين في أزواجهم: ألا يزيد الرجل على أربع، ولا يتزوّج إلا بولي ومهر وشهود، وفيما ملكت أيمانهم ألا يطأها قبل الاستبراء، وأحللنا لك ما أحللنا تخفيفاً عليك لكيلا يكون عليك ضيق، وكان الله غفوراً رحيماً.", "h": ["بيان إكرام الله تعالى لنبيّه بالتخفيف عليه رحمة به، فأباح له ما زاد على أربع، وأباح له الواهبة نفسها بغير مهر ولا ولي.", "تقرير أحكام النكاح للمؤمنين، وأنه لم يطرأ عليها نسخ بتخفيف.", "بيان سعة رحمة الله ومغفرته لعباده المؤمنين."], "k": "«لكيلا يكون عليك حرج»… رحمة الله بنبيّه في أعبائه؛ فكيف أرحم من يحمل الأعباء من حولي؟"}, {"lbl": "الآيتان ٥١ – ٥٢", "q": "۞تُرۡجِي مَن تَشَآءُ مِنۡهُنَّ وَتُـٔۡوِيٓ إِلَيۡكَ مَن تَشَآءُۖ وَمَنِ ٱبۡتَغَيۡتَ مِمَّنۡ عَزَلۡتَ فَلَا جُنَاحَ عَلَيۡكَۚ ذَٰلِكَ أَدۡنَىٰٓ أَن تَقَرَّ أَعۡيُنُهُنَّ وَلَا يَحۡزَنَّ وَيَرۡضَيۡنَ بِمَآ ءَاتَيۡتَهُنَّ كُلُّهُنَّۚ وَٱللَّهُ يَعۡلَمُ مَا فِي قُلُوبِكُمۡۚ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمٗا ﴿٥١﴾ لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعۡدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَٰجٖ وَلَوۡ أَعۡجَبَكَ حُسۡنُهُنَّ إِلَّا مَا مَلَكَتۡ يَمِينُكَۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ رَّقِيبٗا ﴿٥٢﴾", "w": [["تُرجي من تشاء منهن", "تؤخّر من تشاء من نسائك."], ["وتؤوي إليك من تشاء", "تضمّ إليك من تشاء."], ["ومن ابتغيت ممن عزلت", "من طلبت ممن عزلت من القسمة."], ["ذلك أدنى أن تقرّ أعينهن", "ذلك التخيير أقرب أن يفرحن ولا يحزنّ."], ["والله يعلم ما في قلوبكم", "من الميل إلى بعض النساء دون بعض."], ["لا يحلّ لك النساء من بعد", "لا يجوز لك أن تتزوّج بعد هؤلاء التسع."], ["ولا أن تبدّل بهن من أزواج", "بأن تطلّق إحداهن وتتزوّج بدلها."], ["إلا ما ملكت يمينك", "فلا حرج عليك في التسرّي، وقد تسرّى بمارية المهداة من ملك مصر."]], "m": "ما زال السياق في التيسير على رسول الله ﷺ: وسّع الله عليه بأن يؤخّر من يشاء من نسائه ويضمّ إليه من يشاء، ومن طلبها ممن عزلها فلا حرج عليه، فأسقط عنه واجب القسم، ومع هذا كان يقسم بينهن ويقول: «اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك ولا أملك»، ذلك التخيير أقرب أن تقرّ أعينهن ويرضين بما آتاهن، والله يعلم ما في قلوبكم من الميل، وإنما خيّره تيسيراً عليه لعظم مهامه، وكان الله عليماً حليماً. ولا يحلّ لك النساء من بعد هؤلاء التسع اللاتي اخترن الله ورسوله، فقصرك عليهن إكراماً لهن، ولا أن تطلّق إحداهن وتتزوّج بدلها ولو أعجبك حسنهن، إلا ما ملكت يمينك، وقد تسرّى بمارية القبطية التي أهداها المقوقس، وأنجبت إبراهيم، وكان الله على كل شيء رقيباً.", "h": ["بيان إكرام الله تعالى لرسوله بالتيسير عليه لكثرة مهامه.", "ما خيّر الله فيه رسوله لا يصحّ لأحد من المسلمين، إلا أن يخيّر زوجته الكبيرة أو المريضة بين الطلاق والتنازل عن ليلتها، فإن اختارت البقاء مع التنازل جاز.", "في تدبير الله لرسوله وزوجاته من الفوائد والمصالح ما لا يُقدّر قدره.", "تقرير مبدأ: ما ترك أحد شيئاً لله إلا عوّضه الله خيراً منه، تجلّى في اختيارهن الله ورسوله والدار الآخرة.", "وجوب مراقبة الله تعالى وعدم التفكير في الخروج عن طاعته بحال.", "إذن الله لرسوله بالزواج بأكثر من أربع كان لحِكَم عالية، منها: نقل الأحكام الخاصة بالنساء، وتقوية الدعوة بالمصاهرة، ومكافأة من أحسن إليه كأبي بكر وعمر، وإبطال أحكام التبنّي بزواجه من زينب."], "k": "«وكان الله على كل شيء رقيباً»… في أخصّ شؤوني، هل أستحضر أنه يرى؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 305;
insert into public.tdb_cards(topic, i, body) select 305, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٥ – ٤٨", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا ﴿٤٥﴾ وَدَاعِيًا إِلَى ٱللَّهِ بِإِذۡنِهِۦ وَسِرَاجٗا مُّنِيرٗا ﴿٤٦﴾ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضۡلٗا كَبِيرٗا ﴿٤٧﴾ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَ وَدَعۡ أَذَىٰهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا ﴿٤٨﴾", "w": [["شاهداً", "على من أرسلناك إليهم."], ["ومبشّراً", "من آمن وعمل صالحاً بالجنة."], ["ونذيراً", "من كفر وأشرك بالنار."], ["وداعياً إلى الله بإذنه", "إلى الإيمان به وتوحيده بأمره."], ["وسراجاً منيراً", "كالسراج المنير يهتدي به من أراد الهداية."], ["ولا تطع الكافرين والمنافقين", "فيما يخالف أمر ربك وما شرعه."], ["ودع أذاهم", "اتركه فلا تقابله بأذى حتى يأمرك ربك فيهم."], ["وتوكّل على الله", "فوّض أمرك إليه فإنه يكفيك."]], "m": "هذا نداء خاص بعد النداء العام لمزيد تكريم الرسول ﷺ: يا أيها النبي إنا أرسلناك شاهداً على من أرسلناك إليهم، من أجاب دعوتك ومن لم يجبها، ومبشّراً لمن آمن وعمل صالحاً بالجنة، ونذيراً لمن أعرض بعذاب النار، وداعياً إلى الله ليعبدوه ويوحّدوه بأمره لك بذلك، وسراجاً منيراً يهتدي بك من أراد الهداية. وبشّر المؤمنين الذين استجابوا بأن لهم من الله فضلاً كبيراً، الجنة. ولا تطع الكافرين والمنافقين فيما يقترحون عليك مما يتنافى مع رسالتك، ودع أذاهم فلا تقابله حتى يأمرك ربك، وتوكّل على الله في أمرك كله، وكفى بالله حافظاً يعصمك من الناس.", "h": ["بيان الكمال المحمدي الذي وهبه إياه ربه تبارك وتعالى.", "مشروعية الدعوة إلى الله إذا كان الداعي متأهّلاً بالعلم والحلم.", "حرمة طاعة الكافرين والمنافقين والفجرة والظالمين فيما يتنافى مع الشرع."], "k": "«وسراجاً منيراً»… النور الذي جاء به بين يديّ؛ فهل أمشي في ضوئه؟"}, {"lbl": "الآية ٤٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَيۡهِنَّ مِنۡ عِدَّةٖ تَعۡتَدُّونَهَاۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحٗا جَمِيلٗا ﴿٤٩﴾", "w": [["إذا نكحتم المؤمنات", "إذا عقدتم عليهن ولم تبنوا بهن."], ["من قبل أن تمسّوهن", "من قبل الخلوة بهن ووطئهن."], ["فما لكم عليهن من عدة", "ليس لكم مطالبتهن بالعدة."], ["فمتّعوهن", "أعطوهن شيئاً من المال يتمتّعن به جبراً لخاطرهن."], ["وسرّحوهن سراحاً جميلاً", "اتركوهن يذهبن إلى أهليهن من غير إضرار."]], "m": "ينادي الله عباده المؤمنين معلّماً: إذا عقدتم على المؤمنات ثم طلّقتموهن من قبل الدخول بهن، فما لكم عليهن من عدة تعتدّونها بالأقراء ولا بالشهور، إذ العدة لمعرفة ما في الرحم، وغير المدخول بها رحمها بريء، فإن كان سُمّي لهن مهر فلهن نصف المسمّى والمتعة استحباباً، وإن لم يُسمّ لهن مهر فليس لهن غير المتعة، وهي هنا واجبة بحسب يسار المطلّق وإعساره، وخلّوا سبيلهن يذهبن إلى ذويهن من غير إضرار.", "h": ["جواز الطلاق قبل البناء.", "ليس على المطلّقة قبل الدخول بها عدة، بل لها أن تتزوّج ساعة ما تُطلّق.", "المطلّقة قبل البناء إن سُمّي لها صداق فلها نصفه، وإن لم يُسمّ لها صداق فلها المتعة يقدّرها القاضي بحسب سعة المطلّق وضيقه.", "حرمة أذية المطلّقة بأي أذى، ووجوب تخلية سبيلها تذهب حيث شاءت.", "مشروعية المتعة لكل مطلّقة."], "k": "«وسرّحوهن سراحاً جميلاً»… حتى الفراق له أدب؛ فهل أفارق من أفارقه بالحسنى؟"}, {"lbl": "الآية ٥٠", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَحۡلَلۡنَا لَكَ أَزۡوَٰجَكَ ٱلَّـٰتِيٓ ءَاتَيۡتَ أُجُورَهُنَّ وَمَا مَلَكَتۡ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيۡكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّـٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّـٰتِي هَاجَرۡنَ مَعَكَ وَٱمۡرَأَةٗ مُّؤۡمِنَةً إِن وَهَبَتۡ نَفۡسَهَا لِلنَّبِيِّ إِنۡ أَرَادَ ٱلنَّبِيُّ أَن يَسۡتَنكِحَهَا خَالِصَةٗ لَّكَ مِن دُونِ ٱلۡمُؤۡمِنِينَۗ قَدۡ عَلِمۡنَا مَا فَرَضۡنَا عَلَيۡهِمۡ فِيٓ أَزۡوَٰجِهِمۡ وَمَا مَلَكَتۡ أَيۡمَٰنُهُمۡ لِكَيۡلَا يَكُونَ عَلَيۡكَ حَرَجٞۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿٥٠﴾", "w": [["آتيت أجورهن", "أعطيت مهورهن."], ["مما أفاء الله عليك", "مما يُسبى، كصفية وجويرية."], ["اللاتي هاجرن معك", "بخلاف من لم تهاجر وبقيت في دار الكفر."], ["وهبت نفسها للنبي", "بغير صداق، إن أراد النبي أن يتزوّجها."], ["خالصة لك من دون المؤمنين", "بدون صداق."], ["قد علمنا ما فرضنا عليهم في أزواجهم", "من الأحكام: ألا يزيدوا على أربع، وألا يتزوّجوا إلا بولي ومهر وشهود."], ["لكيلا يكون عليك حرج", "ضيق في النكاح."]], "m": "هذا النداء يحمل لرسول الله ﷺ إجازات تخفّف عنه ما يعانيه من أمور الرسالة: يا أيها النبي إنا أحللنا لك أزواجك اللاتي أعطيتهن مهورهن، وما ملكت يمينك مما أفاء الله عليك من سبايا الجهاد كصفية وجويرية، وبنات عمك وعماتك وخالك وخالاتك اللاتي هاجرن معك، أما اللاتي لم يهاجرن فلا يحللن لك، وامرأة مؤمنة إن وهبت نفسها للنبي بلا مهر إن أراد أن يستنكحها، خالصة لك دون المؤمنين، فالمؤمن لا تحل له الواهبة إلا بمهر. قد علمنا ما فرضنا على المؤمنين في أزواجهم: ألا يزيد الرجل على أربع، ولا يتزوّج إلا بولي ومهر وشهود، وفيما ملكت أيمانهم ألا يطأها قبل الاستبراء، وأحللنا لك ما أحللنا تخفيفاً عليك لكيلا يكون عليك ضيق، وكان الله غفوراً رحيماً.", "h": ["بيان إكرام الله تعالى لنبيّه بالتخفيف عليه رحمة به، فأباح له ما زاد على أربع، وأباح له الواهبة نفسها بغير مهر ولا ولي.", "تقرير أحكام النكاح للمؤمنين، وأنه لم يطرأ عليها نسخ بتخفيف.", "بيان سعة رحمة الله ومغفرته لعباده المؤمنين."], "k": "«لكيلا يكون عليك حرج»… رحمة الله بنبيّه في أعبائه؛ فكيف أرحم من يحمل الأعباء من حولي؟"}, {"lbl": "الآيتان ٥١ – ٥٢", "q": "۞تُرۡجِي مَن تَشَآءُ مِنۡهُنَّ وَتُـٔۡوِيٓ إِلَيۡكَ مَن تَشَآءُۖ وَمَنِ ٱبۡتَغَيۡتَ مِمَّنۡ عَزَلۡتَ فَلَا جُنَاحَ عَلَيۡكَۚ ذَٰلِكَ أَدۡنَىٰٓ أَن تَقَرَّ أَعۡيُنُهُنَّ وَلَا يَحۡزَنَّ وَيَرۡضَيۡنَ بِمَآ ءَاتَيۡتَهُنَّ كُلُّهُنَّۚ وَٱللَّهُ يَعۡلَمُ مَا فِي قُلُوبِكُمۡۚ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمٗا ﴿٥١﴾ لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعۡدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَٰجٖ وَلَوۡ أَعۡجَبَكَ حُسۡنُهُنَّ إِلَّا مَا مَلَكَتۡ يَمِينُكَۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ رَّقِيبٗا ﴿٥٢﴾", "w": [["تُرجي من تشاء منهن", "تؤخّر من تشاء من نسائك."], ["وتؤوي إليك من تشاء", "تضمّ إليك من تشاء."], ["ومن ابتغيت ممن عزلت", "من طلبت ممن عزلت من القسمة."], ["ذلك أدنى أن تقرّ أعينهن", "ذلك التخيير أقرب أن يفرحن ولا يحزنّ."], ["والله يعلم ما في قلوبكم", "من الميل إلى بعض النساء دون بعض."], ["لا يحلّ لك النساء من بعد", "لا يجوز لك أن تتزوّج بعد هؤلاء التسع."], ["ولا أن تبدّل بهن من أزواج", "بأن تطلّق إحداهن وتتزوّج بدلها."], ["إلا ما ملكت يمينك", "فلا حرج عليك في التسرّي، وقد تسرّى بمارية المهداة من ملك مصر."]], "m": "ما زال السياق في التيسير على رسول الله ﷺ: وسّع الله عليه بأن يؤخّر من يشاء من نسائه ويضمّ إليه من يشاء، ومن طلبها ممن عزلها فلا حرج عليه، فأسقط عنه واجب القسم، ومع هذا كان يقسم بينهن ويقول: «اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك ولا أملك»، ذلك التخيير أقرب أن تقرّ أعينهن ويرضين بما آتاهن، والله يعلم ما في قلوبكم من الميل، وإنما خيّره تيسيراً عليه لعظم مهامه، وكان الله عليماً حليماً. ولا يحلّ لك النساء من بعد هؤلاء التسع اللاتي اخترن الله ورسوله، فقصرك عليهن إكراماً لهن، ولا أن تطلّق إحداهن وتتزوّج بدلها ولو أعجبك حسنهن، إلا ما ملكت يمينك، وقد تسرّى بمارية القبطية التي أهداها المقوقس، وأنجبت إبراهيم، وكان الله على كل شيء رقيباً.", "h": ["بيان إكرام الله تعالى لرسوله بالتيسير عليه لكثرة مهامه.", "ما خيّر الله فيه رسوله لا يصحّ لأحد من المسلمين، إلا أن يخيّر زوجته الكبيرة أو المريضة بين الطلاق والتنازل عن ليلتها، فإن اختارت البقاء مع التنازل جاز.", "في تدبير الله لرسوله وزوجاته من الفوائد والمصالح ما لا يُقدّر قدره.", "تقرير مبدأ: ما ترك أحد شيئاً لله إلا عوّضه الله خيراً منه، تجلّى في اختيارهن الله ورسوله والدار الآخرة.", "وجوب مراقبة الله تعالى وعدم التفكير في الخروج عن طاعته بحال.", "إذن الله لرسوله بالزواج بأكثر من أربع كان لحِكَم عالية، منها: نقل الأحكام الخاصة بالنساء، وتقوية الدعوة بالمصاهرة، ومكافأة من أحسن إليه كأبي بكر وعمر، وإبطال أحكام التبنّي بزواجه من زينب."], "k": "«وكان الله على كل شيء رقيباً»… في أخصّ شؤوني، هل أستحضر أنه يرى؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (306, 33, 53, 62, 'سورة الأحزاب ٥٣ – ٦٢', 'آية الحجاب: «وإذا سألتموهن متاعاً فاسألوهن من وراء حجاب»، و«إن الله وملائكته يصلّون على النبي»، و«يدنين عليهن من جلابيبهن»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 306) = $j$[{"lbl": "الآيات ٥٣ – ٥٥", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُواْ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزۡوَٰجَهُۥ مِنۢ بَعۡدِهِۦٓ أَبَدًاۚ إِنَّ ذَٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِيمًا ﴿٥٣﴾ إِن تُبۡدُواْ شَيۡـًٔا أَوۡ تُخۡفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا ﴿٥٤﴾ لَّا جُنَاحَ عَلَيۡهِنَّ فِيٓ ءَابَآئِهِنَّ وَلَآ أَبۡنَآئِهِنَّ وَلَآ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتۡ أَيۡمَٰنُهُنَّۗ وَٱتَّقِينَ ٱللَّهَۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا ﴿٥٥﴾", "w": [["إلا أن يُؤذن لكم", "في الدخول بأن يدعوكم إلى طعام."], ["غير ناظرين إناه", "غير منتظرين وقت نضجه، فلا تدخلوا قبل وقته فتضايقوا رسول الله وأهله."], ["فإذا طعمتم فانتشروا", "إذا فرغتم من الطعام فتفرّقوا."], ["ولا مستأنسين لحديث", "لا تمكثوا يحدّث بعضكم بعضاً."], ["فيستحيي منكم", "أن يُخرجكم."], ["من وراء حجاب", "من وراء ستر كباب ونحوه."], ["أطهر لقلوبكم وقلوبهن", "من الخواطر الفاسدة."], ["إن ذلكم كان عند الله عظيماً", "أذاكم لرسول الله ونكاح أزواجه من بعده."], ["لا جناح عليهن في آبائهن", "لا حرج على نسائه في أن يراهن المذكورون في الآية."], ["ولا نسائهن", "المؤمنات."]], "m": "لما بيّن ما يراعيه الرسول في شأن أزواجه بيّن ما يجب على المؤمنين نحوهن: لا تدخلوا بيوت النبي إلا أن يُؤذن لكم إلى طعام غير منتظرين نضجه، ونزلت هذه الآية، آية الحجاب، في نفر أكلوا طعام وليمة زينب ثم جلسوا يتحدّثون، فخرج رسول الله لعلهم يخرجون فلم يخرجوا، واستحيى أن يقول لهم: قوموا. فإذا دُعيتم فادخلوا، فإذا أكلتم فانتشروا، ولا تمكثوا مستأنسين لحديث، إن ذلكم كان يؤذي النبي فيستحيي منكم، والله لا يستحيي من الحق. وإذا سألتم أزواجه حاجة من متاع البيت فاسألوهن من وراء ستر، ذلكم أطهر لقلوبكم وقلوبهن من خواطر السوء التي لا يخلو منها قلب إذا خاطب امرأة أو نظر إليها. وما كان لكم أن تؤذوا رسول الله، ولا أن تتزوّجوا أزواجه من بعده أبداً، إن ذلكم كان عند الله عظيماً. إن تُظهروا رغبة في ذلك أو تخفوها فإن الله كان بكل شيء عليماً. ولا حرج على أزواجه في أن يكلّمن وجهاً لوجه آباءهن وأبناءهن وإخوانهن وأبناء إخوانهن وأبناء أخواتهن ونساءهن المؤمنات وما ملكت أيمانهن، واتّقين الله إن الله كان على كل شيء شهيداً.", "h": ["بيان ما ينبغي للمؤمنين أن يلتزموه من الآداب في الاستئذان والطعام.", "بيان كمال الرسول ﷺ في خلقه، في أنه ليستحيي أن يقول لضيفه: اخرج.", "وصف الله تعالى نفسه بأنه لا يستحيي من الحق أن يقوله ويأمر به.", "مشروعية مخاطبة الأجنبية من وراء حجاب.", "حرمة أذية رسول الله ﷺ، وأنها جريمة كبرى.", "بيان أن الإنسان لا يخلو من خواطر السوء إذا كلّم المرأة ونظر إليها.", "حرمة نكاح أزواج الرسول بعد موته، وحرمة الخاطر يخطر بذلك.", "بيان المحارم الذين للمسلمة أن تكشف وجهها أمامهم وتخاطبهم."], "k": "«ذلكم أطهر لقلوبكم وقلوبهن»… الحواجز التي شرعها الله حماية؛ فأيّها أتساهل فيه؟"}, {"lbl": "الآيات ٥٦ – ٥٩", "q": "إِنَّ ٱللَّهَ وَمَلَـٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِيِّۚ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ صَلُّواْ عَلَيۡهِ وَسَلِّمُواْ تَسۡلِيمًا ﴿٥٦﴾ إِنَّ ٱلَّذِينَ يُؤۡذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَأَعَدَّ لَهُمۡ عَذَابٗا مُّهِينٗا ﴿٥٧﴾ وَٱلَّذِينَ يُؤۡذُونَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ بِغَيۡرِ مَا ٱكۡتَسَبُواْ فَقَدِ ٱحۡتَمَلُواْ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا ﴿٥٨﴾ يَـٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلۡمُؤۡمِنِينَ يُدۡنِينَ عَلَيۡهِنَّ مِن جَلَٰبِيبِهِنَّۚ ذَٰلِكَ أَدۡنَىٰٓ أَن يُعۡرَفۡنَ فَلَا يُؤۡذَيۡنَۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿٥٩﴾", "w": [["يصلّون على النبي", "صلاة الله ثناؤه ورضوانه، وصلاة الملائكة دعاء واستغفار، وصلاة العباد تشريف وتعظيم."], ["صلّوا عليه وسلّموا تسليماً", "قولوا: اللهم صلّ على محمد وسلّم تسليماً."], ["يؤذون الله ورسوله", "بسبّ أو شتم أو طعن أو نقد."], ["بغير ما اكتسبوا", "يرمونهم بتهم باطلة لم يكتسبوها."], ["فقد احتملوا بهتاناً", "تحمّلوا كذباً ظاهراً."], ["يُدنين عليهن من جلابيبهن", "يُرخين الجلباب على وجوههن إذا خرجن لحاجة."], ["ذلك أدنى أن يُعرفن", "أنهن حرائر فلا يتعرّض لهن المنافقون."]], "m": "لما ذكر ما يجب على المؤمنين من تعظيم نبيّهم أعلن عن شرفه الذي لا يدانيه شرف: إن الله يصلّي على النبي، وملائكته تصلّي عليه، يا أيها الذين آمنوا صلّوا عليه وسلّموا تسليماً، فوجب على كل مؤمن أن يصلّي عليه، وأعظمها أجراً الصلاة الإبراهيمية، وهي واجبة في التشهّد الأخير، وتُستحبّ استحباباً مؤكّداً عند ذكره. إن الذين يؤذون الله بوصفه بالعجز أو نسبة الولد والشريك إليه، ويؤذون رسوله بانتقاص أو تعرّض له أو لآل بيته أو أمته أو سنّته، لعنهم الله في الدنيا والآخرة وأعدّ لهم عذاباً مهيناً. والذين يؤذون المؤمنين والمؤمنات بتهم باطلة فقد احتملوا كذباً وإثماً مبيناً. وكانت النساء يخرجن ليلاً لقضاء الحاجة، فيتعرّض لهن المنافقون بالغمز وهم يقصدون الإماء، فشكون ذلك، فنزل: يا أيها النبي قل لأزواجك وبناتك ونساء المؤمنين يُدنين عليهن من جلابيبهن، فيُرخين طرف الملاءة على الوجه، ذلك أقرب أن يُعرفن حرائر فلا يؤذين، وكان الله غفوراً رحيماً.", "h": ["بيان شرف الرسول محمد ﷺ، ووجوب الصلاة والسلام عليه في العمر مرة، واستحبابها عند ذكره.", "بيان ما يتعرّض له من يؤذي الله ورسوله من غضب وعذاب.", "بيان مقدار ما يتحمّله من يؤذي المؤمنين والمؤمنات بالقول فيما لم يفعلوا، أو بالفعل بضرب أو أخذ مال أو انتهاك عرض.", "وجوب تغطية المؤمنة وجهها إذا خرجت لحاجتها."], "k": "«صلّوا عليه وسلّموا تسليماً»… أمر صلّى عليه الله قبل أن يأمرني؛ فكم صلّيت عليه اليوم؟"}, {"lbl": "الآيات ٦٠ – ٦٢", "q": "۞لَّئِن لَّمۡ يَنتَهِ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡمُرۡجِفُونَ فِي ٱلۡمَدِينَةِ لَنُغۡرِيَنَّكَ بِهِمۡ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلٗا ﴿٦٠﴾ مَّلۡعُونِينَۖ أَيۡنَمَا ثُقِفُوٓاْ أُخِذُواْ وَقُتِّلُواْ تَقۡتِيلٗا ﴿٦١﴾ سُنَّةَ ٱللَّهِ فِي ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِيلٗا ﴿٦٢﴾", "w": [["لئن لم ينتهِ المنافقون", "عن نفاقهم وإظهارهم الإيمان وإبطانهم الكفر."], ["والذين في قلوبهم مرض", "مرض حب الفجور وشهوة الزنا."], ["والمرجفون في المدينة", "الذين يأتون بالأخبار الكاذبة لتضطرب النفوس."], ["لنغرينّك بهم", "لنسلّطنّك عليهم."], ["ثم لا يجاورونك فيها إلا قليلاً", "في المدينة إلا قليلاً من الزمن."], ["ملعونين", "مبعدين عن الرحمة."], ["أينما ثُقفوا", "أينما وُجدوا."], ["سنّة الله في الذين خلوا من قبل", "سنّها في المنافقين والمرجفين."], ["ولن تجد لسنّة الله تبديلاً", "إذ هي ليست أحكاماً تُنسخ، بل هي سرّ التشريع وحكمته."]], "m": "لما أمر نساء المؤمنين بإدناء الجلابيب إجراءً وقائياً هدّد المتعرّضين: لئن لم ينته المنافقون عن أعمالهم الاستفزازية، والذين في قلوبهم شهوة الفجور، والمرجفون بالأخبار الكاذبة كقولهم: العدو زاحف على المدينة، أو السرية الفلانية قُتل أكثر أفرادها، لنسلّطنّك عليهم، ثم لا يجاورونك فيها إلا قليلاً، ثم يُخرجون منها أو يهلكون، مطرودين من الرحمة، أينما وُجدوا أُخذوا أسرى وقُتّلوا تقتيلاً. سنّ الله ذلك سنّة في المنافقين من قبل، ولن تجد لسنّة الله تبديلاً، كما أن الطعام يُشبع والماء يروي والنار تحرق لا يبدّل ذلك.", "h": ["التنديد بالمنافقين وتهديدهم بإمضاء سنّة الله تعالى فيهم.", "مشروعية إبعاد أهل الفساد من المدن الإسلامية أو يتوبوا، كما في المدينة النبوية الشريفة.", "بيان أن ما كان من قبيل السنن لا يتبدّل بتبدّل الأحوال، لا يبدّله الله تعالى ولا يغيّره."], "k": "«والمرجفون في المدينة»… الخبر الذي أنشره قبل أن أتثبّت، هل يُرجف القلوب؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 306;
insert into public.tdb_cards(topic, i, body) select 306, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٣ – ٥٥", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُواْ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزۡوَٰجَهُۥ مِنۢ بَعۡدِهِۦٓ أَبَدًاۚ إِنَّ ذَٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِيمًا ﴿٥٣﴾ إِن تُبۡدُواْ شَيۡـًٔا أَوۡ تُخۡفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا ﴿٥٤﴾ لَّا جُنَاحَ عَلَيۡهِنَّ فِيٓ ءَابَآئِهِنَّ وَلَآ أَبۡنَآئِهِنَّ وَلَآ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتۡ أَيۡمَٰنُهُنَّۗ وَٱتَّقِينَ ٱللَّهَۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا ﴿٥٥﴾", "w": [["إلا أن يُؤذن لكم", "في الدخول بأن يدعوكم إلى طعام."], ["غير ناظرين إناه", "غير منتظرين وقت نضجه، فلا تدخلوا قبل وقته فتضايقوا رسول الله وأهله."], ["فإذا طعمتم فانتشروا", "إذا فرغتم من الطعام فتفرّقوا."], ["ولا مستأنسين لحديث", "لا تمكثوا يحدّث بعضكم بعضاً."], ["فيستحيي منكم", "أن يُخرجكم."], ["من وراء حجاب", "من وراء ستر كباب ونحوه."], ["أطهر لقلوبكم وقلوبهن", "من الخواطر الفاسدة."], ["إن ذلكم كان عند الله عظيماً", "أذاكم لرسول الله ونكاح أزواجه من بعده."], ["لا جناح عليهن في آبائهن", "لا حرج على نسائه في أن يراهن المذكورون في الآية."], ["ولا نسائهن", "المؤمنات."]], "m": "لما بيّن ما يراعيه الرسول في شأن أزواجه بيّن ما يجب على المؤمنين نحوهن: لا تدخلوا بيوت النبي إلا أن يُؤذن لكم إلى طعام غير منتظرين نضجه، ونزلت هذه الآية، آية الحجاب، في نفر أكلوا طعام وليمة زينب ثم جلسوا يتحدّثون، فخرج رسول الله لعلهم يخرجون فلم يخرجوا، واستحيى أن يقول لهم: قوموا. فإذا دُعيتم فادخلوا، فإذا أكلتم فانتشروا، ولا تمكثوا مستأنسين لحديث، إن ذلكم كان يؤذي النبي فيستحيي منكم، والله لا يستحيي من الحق. وإذا سألتم أزواجه حاجة من متاع البيت فاسألوهن من وراء ستر، ذلكم أطهر لقلوبكم وقلوبهن من خواطر السوء التي لا يخلو منها قلب إذا خاطب امرأة أو نظر إليها. وما كان لكم أن تؤذوا رسول الله، ولا أن تتزوّجوا أزواجه من بعده أبداً، إن ذلكم كان عند الله عظيماً. إن تُظهروا رغبة في ذلك أو تخفوها فإن الله كان بكل شيء عليماً. ولا حرج على أزواجه في أن يكلّمن وجهاً لوجه آباءهن وأبناءهن وإخوانهن وأبناء إخوانهن وأبناء أخواتهن ونساءهن المؤمنات وما ملكت أيمانهن، واتّقين الله إن الله كان على كل شيء شهيداً.", "h": ["بيان ما ينبغي للمؤمنين أن يلتزموه من الآداب في الاستئذان والطعام.", "بيان كمال الرسول ﷺ في خلقه، في أنه ليستحيي أن يقول لضيفه: اخرج.", "وصف الله تعالى نفسه بأنه لا يستحيي من الحق أن يقوله ويأمر به.", "مشروعية مخاطبة الأجنبية من وراء حجاب.", "حرمة أذية رسول الله ﷺ، وأنها جريمة كبرى.", "بيان أن الإنسان لا يخلو من خواطر السوء إذا كلّم المرأة ونظر إليها.", "حرمة نكاح أزواج الرسول بعد موته، وحرمة الخاطر يخطر بذلك.", "بيان المحارم الذين للمسلمة أن تكشف وجهها أمامهم وتخاطبهم."], "k": "«ذلكم أطهر لقلوبكم وقلوبهن»… الحواجز التي شرعها الله حماية؛ فأيّها أتساهل فيه؟"}, {"lbl": "الآيات ٥٦ – ٥٩", "q": "إِنَّ ٱللَّهَ وَمَلَـٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِيِّۚ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ صَلُّواْ عَلَيۡهِ وَسَلِّمُواْ تَسۡلِيمًا ﴿٥٦﴾ إِنَّ ٱلَّذِينَ يُؤۡذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَأَعَدَّ لَهُمۡ عَذَابٗا مُّهِينٗا ﴿٥٧﴾ وَٱلَّذِينَ يُؤۡذُونَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ بِغَيۡرِ مَا ٱكۡتَسَبُواْ فَقَدِ ٱحۡتَمَلُواْ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا ﴿٥٨﴾ يَـٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلۡمُؤۡمِنِينَ يُدۡنِينَ عَلَيۡهِنَّ مِن جَلَٰبِيبِهِنَّۚ ذَٰلِكَ أَدۡنَىٰٓ أَن يُعۡرَفۡنَ فَلَا يُؤۡذَيۡنَۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿٥٩﴾", "w": [["يصلّون على النبي", "صلاة الله ثناؤه ورضوانه، وصلاة الملائكة دعاء واستغفار، وصلاة العباد تشريف وتعظيم."], ["صلّوا عليه وسلّموا تسليماً", "قولوا: اللهم صلّ على محمد وسلّم تسليماً."], ["يؤذون الله ورسوله", "بسبّ أو شتم أو طعن أو نقد."], ["بغير ما اكتسبوا", "يرمونهم بتهم باطلة لم يكتسبوها."], ["فقد احتملوا بهتاناً", "تحمّلوا كذباً ظاهراً."], ["يُدنين عليهن من جلابيبهن", "يُرخين الجلباب على وجوههن إذا خرجن لحاجة."], ["ذلك أدنى أن يُعرفن", "أنهن حرائر فلا يتعرّض لهن المنافقون."]], "m": "لما ذكر ما يجب على المؤمنين من تعظيم نبيّهم أعلن عن شرفه الذي لا يدانيه شرف: إن الله يصلّي على النبي، وملائكته تصلّي عليه، يا أيها الذين آمنوا صلّوا عليه وسلّموا تسليماً، فوجب على كل مؤمن أن يصلّي عليه، وأعظمها أجراً الصلاة الإبراهيمية، وهي واجبة في التشهّد الأخير، وتُستحبّ استحباباً مؤكّداً عند ذكره. إن الذين يؤذون الله بوصفه بالعجز أو نسبة الولد والشريك إليه، ويؤذون رسوله بانتقاص أو تعرّض له أو لآل بيته أو أمته أو سنّته، لعنهم الله في الدنيا والآخرة وأعدّ لهم عذاباً مهيناً. والذين يؤذون المؤمنين والمؤمنات بتهم باطلة فقد احتملوا كذباً وإثماً مبيناً. وكانت النساء يخرجن ليلاً لقضاء الحاجة، فيتعرّض لهن المنافقون بالغمز وهم يقصدون الإماء، فشكون ذلك، فنزل: يا أيها النبي قل لأزواجك وبناتك ونساء المؤمنين يُدنين عليهن من جلابيبهن، فيُرخين طرف الملاءة على الوجه، ذلك أقرب أن يُعرفن حرائر فلا يؤذين، وكان الله غفوراً رحيماً.", "h": ["بيان شرف الرسول محمد ﷺ، ووجوب الصلاة والسلام عليه في العمر مرة، واستحبابها عند ذكره.", "بيان ما يتعرّض له من يؤذي الله ورسوله من غضب وعذاب.", "بيان مقدار ما يتحمّله من يؤذي المؤمنين والمؤمنات بالقول فيما لم يفعلوا، أو بالفعل بضرب أو أخذ مال أو انتهاك عرض.", "وجوب تغطية المؤمنة وجهها إذا خرجت لحاجتها."], "k": "«صلّوا عليه وسلّموا تسليماً»… أمر صلّى عليه الله قبل أن يأمرني؛ فكم صلّيت عليه اليوم؟"}, {"lbl": "الآيات ٦٠ – ٦٢", "q": "۞لَّئِن لَّمۡ يَنتَهِ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡمُرۡجِفُونَ فِي ٱلۡمَدِينَةِ لَنُغۡرِيَنَّكَ بِهِمۡ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلٗا ﴿٦٠﴾ مَّلۡعُونِينَۖ أَيۡنَمَا ثُقِفُوٓاْ أُخِذُواْ وَقُتِّلُواْ تَقۡتِيلٗا ﴿٦١﴾ سُنَّةَ ٱللَّهِ فِي ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِيلٗا ﴿٦٢﴾", "w": [["لئن لم ينتهِ المنافقون", "عن نفاقهم وإظهارهم الإيمان وإبطانهم الكفر."], ["والذين في قلوبهم مرض", "مرض حب الفجور وشهوة الزنا."], ["والمرجفون في المدينة", "الذين يأتون بالأخبار الكاذبة لتضطرب النفوس."], ["لنغرينّك بهم", "لنسلّطنّك عليهم."], ["ثم لا يجاورونك فيها إلا قليلاً", "في المدينة إلا قليلاً من الزمن."], ["ملعونين", "مبعدين عن الرحمة."], ["أينما ثُقفوا", "أينما وُجدوا."], ["سنّة الله في الذين خلوا من قبل", "سنّها في المنافقين والمرجفين."], ["ولن تجد لسنّة الله تبديلاً", "إذ هي ليست أحكاماً تُنسخ، بل هي سرّ التشريع وحكمته."]], "m": "لما أمر نساء المؤمنين بإدناء الجلابيب إجراءً وقائياً هدّد المتعرّضين: لئن لم ينته المنافقون عن أعمالهم الاستفزازية، والذين في قلوبهم شهوة الفجور، والمرجفون بالأخبار الكاذبة كقولهم: العدو زاحف على المدينة، أو السرية الفلانية قُتل أكثر أفرادها، لنسلّطنّك عليهم، ثم لا يجاورونك فيها إلا قليلاً، ثم يُخرجون منها أو يهلكون، مطرودين من الرحمة، أينما وُجدوا أُخذوا أسرى وقُتّلوا تقتيلاً. سنّ الله ذلك سنّة في المنافقين من قبل، ولن تجد لسنّة الله تبديلاً، كما أن الطعام يُشبع والماء يروي والنار تحرق لا يبدّل ذلك.", "h": ["التنديد بالمنافقين وتهديدهم بإمضاء سنّة الله تعالى فيهم.", "مشروعية إبعاد أهل الفساد من المدن الإسلامية أو يتوبوا، كما في المدينة النبوية الشريفة.", "بيان أن ما كان من قبيل السنن لا يتبدّل بتبدّل الأحوال، لا يبدّله الله تعالى ولا يغيّره."], "k": "«والمرجفون في المدينة»… الخبر الذي أنشره قبل أن أتثبّت، هل يُرجف القلوب؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (307, 33, 63, 73, 'سورة الأحزاب ٦٣ – ٧٣', '«يسألك الناس عن الساعة»، و«يا ليتنا أطعنا الله وأطعنا الرسولا»، و«اتّقوا الله وقولوا قولاً سديداً»، و«إنا عرضنا الأمانة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 307) = $j$[{"lbl": "الآيات ٦٣ – ٦٨", "q": "يَسۡـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِۚ وَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا ﴿٦٣﴾ إِنَّ ٱللَّهَ لَعَنَ ٱلۡكَٰفِرِينَ وَأَعَدَّ لَهُمۡ سَعِيرًا ﴿٦٤﴾ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ لَّا يَجِدُونَ وَلِيّٗا وَلَا نَصِيرٗا ﴿٦٥﴾ يَوۡمَ تُقَلَّبُ وُجُوهُهُمۡ فِي ٱلنَّارِ يَقُولُونَ يَٰلَيۡتَنَآ أَطَعۡنَا ٱللَّهَ وَأَطَعۡنَا ٱلرَّسُولَا۠ ﴿٦٦﴾ وَقَالُواْ رَبَّنَآ إِنَّآ أَطَعۡنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠ ﴿٦٧﴾ رَبَّنَآ ءَاتِهِمۡ ضِعۡفَيۡنِ مِنَ ٱلۡعَذَابِ وَٱلۡعَنۡهُمۡ لَعۡنٗا كَبِيرٗا ﴿٦٨﴾", "w": [["يسألك الناس عن الساعة", "يهود المدينة، كما سأله أهل مكة تكذيباً واستعجالاً."], ["قل إنما علمها عند الله", "انحصر علمها فيه."], ["وما يدريك", "لا أحد يُعلمك بها."], ["لعل الساعة تكون قريباً", "قريبة القيام."], ["وأعدّ لهم سعيراً", "ناراً متسعّرة."], ["تُقلّب وجوههم في النار", "تُصرّف من جهة إلى جهة كاللحم عند شيّه."], ["يا ليتنا أطعنا الله", "يتمنّون لو أطاعوا الله ورسوله."], ["إنا أطعنا سادتنا وكبراءنا", "قول الأتباع يشكون إلى ربهم."], ["فأضلّونا السبيلا", "طريق الهدى."], ["آتهم ضعفين من العذاب", "ضاعف عذابهم لأنهم أضلّونا."], ["والعنهم لعناً كبيراً", "أخزهم خزياً متعدّداً في العذاب."]], "m": "يسألك الناس عن ميقات الساعة، المشركون استبعاداً واستهزاءً، فأجبهم: إنما علمها عند الله، أخفاه حتى عن الملائكة والمرسلين، وما يُعلمك يا رسولنا لعل الساعة تكون قريبة القيام، ولا منافاة بين قربها وعدم العلم بوقتها. إن الله لعن الكافرين فطردهم من رحمته وأعدّ لهم ناراً متسعّرة خالدين فيها أبداً، لا يجدون ولياً ولا نصيراً يرفع عنهم العذاب. يوم تُقلّب وجوههم في النار كاللحم عند شيّه يقولون: يا ليتنا أطعنا الله وأطعنا الرسولا. وقال الأتباع شاكين: ربنا إنا أطعنا سادتنا وكبراءنا فيما أمرونا به من الكفر فأضلّونا طريق الهدى، ربنا آتهم ضعفين من العذاب لأنهم أضلّونا، واخزهم خزياً كبيراً متوالياً.", "h": ["بيان أن علم الساعة استأثر الله به فلا يعلم وقت مجيئها غيره.", "بيان أن الساعة قريبة القيام، ولا منافاة بين قربها وعدم العلم بوقتها.", "تقرير عقيدة البعث والجزاء بذكر أحوال الكافرين فيه.", "بيان أن طاعة السادة والكبراء في معاصي الله ورسوله تعود بالخسران على المطيع والمطاع."], "k": "«إنا أطعنا سادتنا وكبراءنا»… من أتّبعه دون أن أزن قوله بكتاب الله؟"}, {"lbl": "الآيات ٦٩ – ٧٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ ءَاذَوۡاْ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُواْۚ وَكَانَ عِندَ ٱللَّهِ وَجِيهٗا ﴿٦٩﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَقُولُواْ قَوۡلٗا سَدِيدٗا ﴿٧٠﴾ يُصۡلِحۡ لَكُمۡ أَعۡمَٰلَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِيمًا ﴿٧١﴾ إِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومٗا جَهُولٗا ﴿٧٢﴾ لِّيُعَذِّبَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمَۢا ﴿٧٣﴾", "w": [["لا تكونوا كالذين آذوا موسى", "لا تكونوا مع نبيكم كبني إسرائيل إذ آذوا موسى بقولهم: إنه آدر."], ["فبرّأه الله مما قالوا", "أراهم أنه ليس به أدرة، وهي انتفاخ الخصية."], ["وكان عند الله وجيهاً", "ذا جاه عظيم عنده."], ["وقولوا قولاً سديداً", "مستقيماً لا انحراف فيه."], ["يُصلح لكم أعمالكم", "الدينية والدنيوية."], ["فقد فاز فوزاً عظيماً", "نال النجاة من النار ودخول الجنة."], ["إنا عرضنا الأمانة", "ما ائتُمن عليه الإنسان من سائر التكاليف، وما ائتمنه عليه أخوه."], ["فأبين أن يحملنها وأشفقن منها", "رفضن الالتزام بها وخفن عاقبتها."], ["وحملها الإنسان", "آدم وذريته."], ["ظلوماً جهولاً", "كثير الظلم لنفسه، جهولاً بعواقب الأمور."]], "m": "ينهى الله المؤمنين عن أذى نبيّهم بأدنى أذى، وألا يكونوا كبني إسرائيل الذين آذوا موسى، ففي صحيح مسلم أن بني إسرائيل كانوا يغتسلون عراة وكان موسى يغتسل وحده، فقالوا: ما منعه إلا أنه آدر، فوضع ثوبه على حجر يغتسل، فذهب الحجر بثوبه حتى وقف به على ملأ منهم فرأوا أنه ليس به أدرة، فبرّأه الله مما قالوا، وكان عند الله وجيهاً. وقد أوذي رسول الله ﷺ باتّهام زوجه، وبقول بعضهم في قسمته: ما أُريد بها وجه الله، فكان يقول: «يرحم الله موسى، لقد أوذي بأكثر من هذا فصبر». يا أيها الذين آمنوا اتّقوا الله وقولوا قولاً سديداً مستقيماً، يُصلح لكم أعمالكم ويغفر لكم ذنوبكم، ومن يطع الله ورسوله فقد فاز فوزاً عظيماً. إنا عرضنا الأمانة، وهي التكاليف الشرعية كلها وكل ما ائتُمن عليه الإنسان، على السماوات والأرض والجبال، فأبين أن يحملنها بثوابها وعقابها وخفن تبعتها، وحملها الإنسان، آدم، لأنه كان ظلوماً جهولاً بالعواقب، فانتهى الأمر إلى أن يُعذّب المنافقون والمشركون بخيانتهم، ويتوب الله على المؤمنين والمؤمنات فيغفر لهم، وكان الله غفوراً رحيماً.", "h": ["وجوب تقوى الله عز وجل بفعل الأوامر واجتناب المناهي.", "صلاح الأعمال لتثمر للعاملين زكاة النفس وطيب الحياة متوقّف على استقامة القول والعمل، وهو القول السديد.", "طاعة الله ورسوله سبيل الفوز والفلاح في الدارين.", "وجوب رعاية الأمانة وأدائها، ولم يخلُ أحد من أمانة.", "وصف الإنسان بالظلم والجهل، وعلاج ذلك مبيّن في سورة المعارج في قوله: «إلا المصلّين الذين هم على صلاتهم دائمون»."], "k": "«وقولوا قولاً سديداً يُصلح لكم أعمالكم»… إصلاح عملي يبدأ من لساني؛ فما الكلمة التي أحتاج أن أقوّمها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 307;
insert into public.tdb_cards(topic, i, body) select 307, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٣ – ٦٨", "q": "يَسۡـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِۚ وَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا ﴿٦٣﴾ إِنَّ ٱللَّهَ لَعَنَ ٱلۡكَٰفِرِينَ وَأَعَدَّ لَهُمۡ سَعِيرًا ﴿٦٤﴾ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ لَّا يَجِدُونَ وَلِيّٗا وَلَا نَصِيرٗا ﴿٦٥﴾ يَوۡمَ تُقَلَّبُ وُجُوهُهُمۡ فِي ٱلنَّارِ يَقُولُونَ يَٰلَيۡتَنَآ أَطَعۡنَا ٱللَّهَ وَأَطَعۡنَا ٱلرَّسُولَا۠ ﴿٦٦﴾ وَقَالُواْ رَبَّنَآ إِنَّآ أَطَعۡنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠ ﴿٦٧﴾ رَبَّنَآ ءَاتِهِمۡ ضِعۡفَيۡنِ مِنَ ٱلۡعَذَابِ وَٱلۡعَنۡهُمۡ لَعۡنٗا كَبِيرٗا ﴿٦٨﴾", "w": [["يسألك الناس عن الساعة", "يهود المدينة، كما سأله أهل مكة تكذيباً واستعجالاً."], ["قل إنما علمها عند الله", "انحصر علمها فيه."], ["وما يدريك", "لا أحد يُعلمك بها."], ["لعل الساعة تكون قريباً", "قريبة القيام."], ["وأعدّ لهم سعيراً", "ناراً متسعّرة."], ["تُقلّب وجوههم في النار", "تُصرّف من جهة إلى جهة كاللحم عند شيّه."], ["يا ليتنا أطعنا الله", "يتمنّون لو أطاعوا الله ورسوله."], ["إنا أطعنا سادتنا وكبراءنا", "قول الأتباع يشكون إلى ربهم."], ["فأضلّونا السبيلا", "طريق الهدى."], ["آتهم ضعفين من العذاب", "ضاعف عذابهم لأنهم أضلّونا."], ["والعنهم لعناً كبيراً", "أخزهم خزياً متعدّداً في العذاب."]], "m": "يسألك الناس عن ميقات الساعة، المشركون استبعاداً واستهزاءً، فأجبهم: إنما علمها عند الله، أخفاه حتى عن الملائكة والمرسلين، وما يُعلمك يا رسولنا لعل الساعة تكون قريبة القيام، ولا منافاة بين قربها وعدم العلم بوقتها. إن الله لعن الكافرين فطردهم من رحمته وأعدّ لهم ناراً متسعّرة خالدين فيها أبداً، لا يجدون ولياً ولا نصيراً يرفع عنهم العذاب. يوم تُقلّب وجوههم في النار كاللحم عند شيّه يقولون: يا ليتنا أطعنا الله وأطعنا الرسولا. وقال الأتباع شاكين: ربنا إنا أطعنا سادتنا وكبراءنا فيما أمرونا به من الكفر فأضلّونا طريق الهدى، ربنا آتهم ضعفين من العذاب لأنهم أضلّونا، واخزهم خزياً كبيراً متوالياً.", "h": ["بيان أن علم الساعة استأثر الله به فلا يعلم وقت مجيئها غيره.", "بيان أن الساعة قريبة القيام، ولا منافاة بين قربها وعدم العلم بوقتها.", "تقرير عقيدة البعث والجزاء بذكر أحوال الكافرين فيه.", "بيان أن طاعة السادة والكبراء في معاصي الله ورسوله تعود بالخسران على المطيع والمطاع."], "k": "«إنا أطعنا سادتنا وكبراءنا»… من أتّبعه دون أن أزن قوله بكتاب الله؟"}, {"lbl": "الآيات ٦٩ – ٧٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ ءَاذَوۡاْ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُواْۚ وَكَانَ عِندَ ٱللَّهِ وَجِيهٗا ﴿٦٩﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَقُولُواْ قَوۡلٗا سَدِيدٗا ﴿٧٠﴾ يُصۡلِحۡ لَكُمۡ أَعۡمَٰلَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِيمًا ﴿٧١﴾ إِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومٗا جَهُولٗا ﴿٧٢﴾ لِّيُعَذِّبَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمَۢا ﴿٧٣﴾", "w": [["لا تكونوا كالذين آذوا موسى", "لا تكونوا مع نبيكم كبني إسرائيل إذ آذوا موسى بقولهم: إنه آدر."], ["فبرّأه الله مما قالوا", "أراهم أنه ليس به أدرة، وهي انتفاخ الخصية."], ["وكان عند الله وجيهاً", "ذا جاه عظيم عنده."], ["وقولوا قولاً سديداً", "مستقيماً لا انحراف فيه."], ["يُصلح لكم أعمالكم", "الدينية والدنيوية."], ["فقد فاز فوزاً عظيماً", "نال النجاة من النار ودخول الجنة."], ["إنا عرضنا الأمانة", "ما ائتُمن عليه الإنسان من سائر التكاليف، وما ائتمنه عليه أخوه."], ["فأبين أن يحملنها وأشفقن منها", "رفضن الالتزام بها وخفن عاقبتها."], ["وحملها الإنسان", "آدم وذريته."], ["ظلوماً جهولاً", "كثير الظلم لنفسه، جهولاً بعواقب الأمور."]], "m": "ينهى الله المؤمنين عن أذى نبيّهم بأدنى أذى، وألا يكونوا كبني إسرائيل الذين آذوا موسى، ففي صحيح مسلم أن بني إسرائيل كانوا يغتسلون عراة وكان موسى يغتسل وحده، فقالوا: ما منعه إلا أنه آدر، فوضع ثوبه على حجر يغتسل، فذهب الحجر بثوبه حتى وقف به على ملأ منهم فرأوا أنه ليس به أدرة، فبرّأه الله مما قالوا، وكان عند الله وجيهاً. وقد أوذي رسول الله ﷺ باتّهام زوجه، وبقول بعضهم في قسمته: ما أُريد بها وجه الله، فكان يقول: «يرحم الله موسى، لقد أوذي بأكثر من هذا فصبر». يا أيها الذين آمنوا اتّقوا الله وقولوا قولاً سديداً مستقيماً، يُصلح لكم أعمالكم ويغفر لكم ذنوبكم، ومن يطع الله ورسوله فقد فاز فوزاً عظيماً. إنا عرضنا الأمانة، وهي التكاليف الشرعية كلها وكل ما ائتُمن عليه الإنسان، على السماوات والأرض والجبال، فأبين أن يحملنها بثوابها وعقابها وخفن تبعتها، وحملها الإنسان، آدم، لأنه كان ظلوماً جهولاً بالعواقب، فانتهى الأمر إلى أن يُعذّب المنافقون والمشركون بخيانتهم، ويتوب الله على المؤمنين والمؤمنات فيغفر لهم، وكان الله غفوراً رحيماً.", "h": ["وجوب تقوى الله عز وجل بفعل الأوامر واجتناب المناهي.", "صلاح الأعمال لتثمر للعاملين زكاة النفس وطيب الحياة متوقّف على استقامة القول والعمل، وهو القول السديد.", "طاعة الله ورسوله سبيل الفوز والفلاح في الدارين.", "وجوب رعاية الأمانة وأدائها، ولم يخلُ أحد من أمانة.", "وصف الإنسان بالظلم والجهل، وعلاج ذلك مبيّن في سورة المعارج في قوله: «إلا المصلّين الذين هم على صلاتهم دائمون»."], "k": "«وقولوا قولاً سديداً يُصلح لكم أعمالكم»… إصلاح عملي يبدأ من لساني؛ فما الكلمة التي أحتاج أن أقوّمها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (308, 34, 1, 9, 'سورة سبأ ١ – ٩', '«الحمد لله الذي له ما في السماوات وما في الأرض»، و«لا يعزب عنه مثقال ذرة»، و«أفترى على الله كذباً أم به جنّة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 308) = $j$[{"lbl": "الآيتان ١ – ٢", "q": "ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَلَهُ ٱلۡحَمۡدُ فِي ٱلۡأٓخِرَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ ﴿١﴾ يَعۡلَمُ مَا يَلِجُ فِي ٱلۡأَرۡضِ وَمَا يَخۡرُجُ مِنۡهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعۡرُجُ فِيهَاۚ وَهُوَ ٱلرَّحِيمُ ٱلۡغَفُورُ ﴿٢﴾", "w": [["الحمد لله", "الوصف بالجميل واجب لله مستحق له."], ["الذي له ما في السماوات وما في الأرض", "خلقاً وملكاً وتصريفاً."], ["وله الحمد في الآخرة", "يحمده فيها أولياؤه في الجنة كما له الحمد في الدنيا."], ["وهو الحكيم الخبير", "الحكيم في أفعاله، الخبير بأحوال عباده."], ["يعلم ما يلج في الأرض", "ما يدخل فيها من مطر وأموات وكنوز."], ["وما يخرج منها", "من نبات وعيون ومعادن."], ["وما ينزل من السماء", "من ملائكة وأمطار وأرزاق."], ["وما يعرج فيها", "من ملائكة وأعمال العباد."], ["وهو الرحيم الغفور", "الرحيم بالمؤمنين، الغفور للتائبين."]], "m": "يخبر تعالى أن له الحمد الكامل التام، ولا يستحقه على الحقيقة غيره، إذ كل ما يُحمد عليه المخلوق هو من عطاء الله، فله ما في السماوات وما في الأرض خلقاً وملكاً وتدبيراً، وله الحمد في الآخرة إذ يُكرم أولياءه فينزلهم الجنة فيقولون: الحمد لله الذي صدقنا وعده، وهو الحكيم في تصريف أمور عباده الخبير بأحوالهم. يعلم ما يدخل في الأرض من مطر وكنوز وأموات، وما يخرج منها من نبات ومعادن ومياه، وما ينزل من السماء من أمطار وملائكة، وما يصعد فيها من ملائكة وأعمال العباد، وهو مع هذه القدرة الرحيم بعباده المؤمنين الغفور للتائبين، فاستحقّ العبادة دون سواه.", "h": ["وجوب حمد الله تعالى وشكره بالقلب واللسان والجوارح.", "الحمد الكامل والثناء الشامل كله لله، إذ النعم كلها منه.", "بيان أن الحمد لا يصح إلا مع مقتضيه من الجلال والجمال، ولا يُحمد في الآخرة إلا الله.", "بيان علم الله تعالى بالظواهر والبواطن في كل خلقه.", "تقرير توحيد الله تعالى في ربوبيته وألوهيته."], "k": "«وما يعرج فيها»… عملي اليوم يصعد إليه؛ فبأي حال يصعد؟"}, {"lbl": "الآيات ٣ – ٦", "q": "وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَأۡتِينَا ٱلسَّاعَةُۖ قُلۡ بَلَىٰ وَرَبِّي لَتَأۡتِيَنَّكُمۡ عَٰلِمِ ٱلۡغَيۡبِۖ لَا يَعۡزُبُ عَنۡهُ مِثۡقَالُ ذَرَّةٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِ وَلَآ أَصۡغَرُ مِن ذَٰلِكَ وَلَآ أَكۡبَرُ إِلَّا فِي كِتَٰبٖ مُّبِينٖ ﴿٣﴾ لِّيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِۚ أُوْلَـٰٓئِكَ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ﴿٤﴾ وَٱلَّذِينَ سَعَوۡ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٞ مِّن رِّجۡزٍ أَلِيمٞ ﴿٥﴾ وَيَرَى ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ ٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ هُوَ ٱلۡحَقَّ وَيَهۡدِيٓ إِلَىٰ صِرَٰطِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ ﴿٦﴾", "w": [["لا تأتينا الساعة", "القيامة."], ["لا يعزب عنه", "لا يغيب عنه."], ["مثقال ذرة", "وزن ذرة، أصغر نملة."], ["إلا في كتاب مبين", "موجود في اللوح المحفوظ مكتوب فيه."], ["ليجزي الذين آمنوا", "أثبته في اللوح المحفوظ ليحاسب به ويجزي."], ["والذين سعوا في آياتنا", "عملوا على إبطالها جاهدين."], ["معاجزين", "مغالبين لنا ظانّين أنهم يفوتوننا."], ["عذاب من رجز أليم", "من أقبح العذاب وأسوئه."], ["ويرى الذين أوتوا العلم", "يعلم علماء أهل الكتاب كعبد الله بن سلام وأصحابه."], ["صراط العزيز الحميد", "صراط الله الموصل إلى رضاه، وهو الإسلام."]], "m": "بعد تقرير التوحيد قرّر عقيدة البعث: وقال منكرو البعث: لا تأتينا الساعة، قل: بلى وربي لتأتينّكم، أحببتم أم كرهتم، ثم أثنى على نفسه بصفة العلم، إذ البعث يتوقف على العلم والقدرة: عالم الغيب لا يغيب عنه وزن ذرة في السماوات ولا في الأرض ولا أصغر من ذلك ولا أكبر إلا في اللوح المحفوظ، الذي كتب الله فيه كل أحداث العالم. والحكمة من كتابة الأحداث ومن البعث ليجزي الذين آمنوا وعملوا الصالحات بالمغفرة والرزق الكريم في الجنة، والذين عملوا جهدهم في إبطال آيات الله ظانّين أنهم يفوتوننا أولئك لهم عذاب من أسوأ العذاب وأشده ألماً. ويعلم علماء أهل الكتاب كابن سلام وأصحابه أن الذي أُنزل إليك من ربك هو الحق، ويهدي إلى صراط العزيز الحميد، لموافقته ما في التوراة من عقيدة القدر وكتابة الأعمال.", "h": ["تقرير عقيدة البعث والجزاء بعد تقرير توحيد الألوهية.", "تقرير عقيدة القضاء والقدر، وكتابة الأعمال والأحداث في اللوح المحفوظ.", "طلب شهادة أهل الكتاب على صحة الإسلام والحصول عليها لموافقة ما عندهم."], "k": "«لا يعزب عنه مثقال ذرة»… أصغر نيّة في قلبي مكتوبة؛ فهل أنقّي نياتي الصغيرة؟"}, {"lbl": "الآيات ٧ – ٩", "q": "وَقَالَ ٱلَّذِينَ كَفَرُواْ هَلۡ نَدُلُّكُمۡ عَلَىٰ رَجُلٖ يُنَبِّئُكُمۡ إِذَا مُزِّقۡتُمۡ كُلَّ مُمَزَّقٍ إِنَّكُمۡ لَفِي خَلۡقٖ جَدِيدٍ ﴿٧﴾ أَفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةُۢۗ بَلِ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ فِي ٱلۡعَذَابِ وَٱلضَّلَٰلِ ٱلۡبَعِيدِ ﴿٨﴾ أَفَلَمۡ يَرَوۡاْ إِلَىٰ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِن نَّشَأۡ نَخۡسِفۡ بِهِمُ ٱلۡأَرۡضَ أَوۡ نُسۡقِطۡ عَلَيۡهِمۡ كِسَفٗا مِّنَ ٱلسَّمَآءِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّكُلِّ عَبۡدٖ مُّنِيبٖ ﴿٩﴾", "w": [["وقال الذين كفروا", "قال بعضهم لبعض على جهة التعجّب."], ["هل ندلّكم على رجل", "يعنون محمداً ﷺ."], ["إذا مُزّقتم كل ممزّق", "قُطّعتم كل التقطيع."], ["إنكم لفي خلق جديد", "تُبعثون خلقاً جديداً."], ["أم به جنّة", "جنون يخيّل له ذلك."], ["بل الذين لا يؤمنون بالآخرة في العذاب والضلال البعيد", "ليس الأمر كما يقولون، بل الذين لا يؤمنون بالآخرة في العذاب في الآخرة، وفي الضلال البعيد في الدنيا."], ["إلى ما بين أيديهم وما خلفهم", "من كل جهة من السماء والأرض."], ["كسفاً", "قطعاً."], ["لكل عبد منيب", "لكل مؤمن رجّاع إلى ربه في أمره كله."]], "m": "ما زال السياق في تقرير البعث: وقال مشركو مكة بعضهم لبعض متعجّبين مستهزئين: هل ندلّكم على رجل، يعنون محمداً، يخبركم أنكم إذا متّم وتمزّقت أجسامكم وصرتم تراباً تُبعثون في خلق جديد؟ أختلق على الله كذباً أم به مسّ من جنون يخيّل له صور البعث؟ فردّ الله: ليس الأمر كما يقولون، بل الذين لا يؤمنون بالآخرة في العذاب يوم القيامة، وفي الضلال البعيد اليوم، وشؤمهم من تكذيبهم بالبعث. ثم هدّدهم: أفلم ينظروا إلى ما يحيط بهم من السماء والأرض؟ إن نشأ نخسف بهم الأرض أو نُسقط عليهم قطعاً من السماء، فلا يجدون مهرباً مهما هربوا، إن في ذلك لعلامة على قدرة الله لكل عبد رجّاع إلى ربه، إذ هو الذي يجد الآية واضحة أمامه.", "h": ["بيان ما كان المشركون عليه من استهزاء وتكذيب وسخرية بالنبي ﷺ.", "تقرير البعث، وأن المكذّبين به محكوم عليهم بالعذاب فيه.", "لفت الأنظار إلى قدرة الله تعالى المحيطة بالإنسان ليخشى الله ويتّقيه.", "فضل الإنابة إلى الله وشرف المنيب، والإنابة الرجوع إلى الله في كل شيء."], "k": "«لكل عبد منيب»… الآيات تراها القلوب الرجّاعة؛ فكم مرة رجعت إليه اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 308;
insert into public.tdb_cards(topic, i, body) select 308, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١ – ٢", "q": "ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَلَهُ ٱلۡحَمۡدُ فِي ٱلۡأٓخِرَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ ﴿١﴾ يَعۡلَمُ مَا يَلِجُ فِي ٱلۡأَرۡضِ وَمَا يَخۡرُجُ مِنۡهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعۡرُجُ فِيهَاۚ وَهُوَ ٱلرَّحِيمُ ٱلۡغَفُورُ ﴿٢﴾", "w": [["الحمد لله", "الوصف بالجميل واجب لله مستحق له."], ["الذي له ما في السماوات وما في الأرض", "خلقاً وملكاً وتصريفاً."], ["وله الحمد في الآخرة", "يحمده فيها أولياؤه في الجنة كما له الحمد في الدنيا."], ["وهو الحكيم الخبير", "الحكيم في أفعاله، الخبير بأحوال عباده."], ["يعلم ما يلج في الأرض", "ما يدخل فيها من مطر وأموات وكنوز."], ["وما يخرج منها", "من نبات وعيون ومعادن."], ["وما ينزل من السماء", "من ملائكة وأمطار وأرزاق."], ["وما يعرج فيها", "من ملائكة وأعمال العباد."], ["وهو الرحيم الغفور", "الرحيم بالمؤمنين، الغفور للتائبين."]], "m": "يخبر تعالى أن له الحمد الكامل التام، ولا يستحقه على الحقيقة غيره، إذ كل ما يُحمد عليه المخلوق هو من عطاء الله، فله ما في السماوات وما في الأرض خلقاً وملكاً وتدبيراً، وله الحمد في الآخرة إذ يُكرم أولياءه فينزلهم الجنة فيقولون: الحمد لله الذي صدقنا وعده، وهو الحكيم في تصريف أمور عباده الخبير بأحوالهم. يعلم ما يدخل في الأرض من مطر وكنوز وأموات، وما يخرج منها من نبات ومعادن ومياه، وما ينزل من السماء من أمطار وملائكة، وما يصعد فيها من ملائكة وأعمال العباد، وهو مع هذه القدرة الرحيم بعباده المؤمنين الغفور للتائبين، فاستحقّ العبادة دون سواه.", "h": ["وجوب حمد الله تعالى وشكره بالقلب واللسان والجوارح.", "الحمد الكامل والثناء الشامل كله لله، إذ النعم كلها منه.", "بيان أن الحمد لا يصح إلا مع مقتضيه من الجلال والجمال، ولا يُحمد في الآخرة إلا الله.", "بيان علم الله تعالى بالظواهر والبواطن في كل خلقه.", "تقرير توحيد الله تعالى في ربوبيته وألوهيته."], "k": "«وما يعرج فيها»… عملي اليوم يصعد إليه؛ فبأي حال يصعد؟"}, {"lbl": "الآيات ٣ – ٦", "q": "وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَأۡتِينَا ٱلسَّاعَةُۖ قُلۡ بَلَىٰ وَرَبِّي لَتَأۡتِيَنَّكُمۡ عَٰلِمِ ٱلۡغَيۡبِۖ لَا يَعۡزُبُ عَنۡهُ مِثۡقَالُ ذَرَّةٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِ وَلَآ أَصۡغَرُ مِن ذَٰلِكَ وَلَآ أَكۡبَرُ إِلَّا فِي كِتَٰبٖ مُّبِينٖ ﴿٣﴾ لِّيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِۚ أُوْلَـٰٓئِكَ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ﴿٤﴾ وَٱلَّذِينَ سَعَوۡ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٞ مِّن رِّجۡزٍ أَلِيمٞ ﴿٥﴾ وَيَرَى ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ ٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ هُوَ ٱلۡحَقَّ وَيَهۡدِيٓ إِلَىٰ صِرَٰطِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ ﴿٦﴾", "w": [["لا تأتينا الساعة", "القيامة."], ["لا يعزب عنه", "لا يغيب عنه."], ["مثقال ذرة", "وزن ذرة، أصغر نملة."], ["إلا في كتاب مبين", "موجود في اللوح المحفوظ مكتوب فيه."], ["ليجزي الذين آمنوا", "أثبته في اللوح المحفوظ ليحاسب به ويجزي."], ["والذين سعوا في آياتنا", "عملوا على إبطالها جاهدين."], ["معاجزين", "مغالبين لنا ظانّين أنهم يفوتوننا."], ["عذاب من رجز أليم", "من أقبح العذاب وأسوئه."], ["ويرى الذين أوتوا العلم", "يعلم علماء أهل الكتاب كعبد الله بن سلام وأصحابه."], ["صراط العزيز الحميد", "صراط الله الموصل إلى رضاه، وهو الإسلام."]], "m": "بعد تقرير التوحيد قرّر عقيدة البعث: وقال منكرو البعث: لا تأتينا الساعة، قل: بلى وربي لتأتينّكم، أحببتم أم كرهتم، ثم أثنى على نفسه بصفة العلم، إذ البعث يتوقف على العلم والقدرة: عالم الغيب لا يغيب عنه وزن ذرة في السماوات ولا في الأرض ولا أصغر من ذلك ولا أكبر إلا في اللوح المحفوظ، الذي كتب الله فيه كل أحداث العالم. والحكمة من كتابة الأحداث ومن البعث ليجزي الذين آمنوا وعملوا الصالحات بالمغفرة والرزق الكريم في الجنة، والذين عملوا جهدهم في إبطال آيات الله ظانّين أنهم يفوتوننا أولئك لهم عذاب من أسوأ العذاب وأشده ألماً. ويعلم علماء أهل الكتاب كابن سلام وأصحابه أن الذي أُنزل إليك من ربك هو الحق، ويهدي إلى صراط العزيز الحميد، لموافقته ما في التوراة من عقيدة القدر وكتابة الأعمال.", "h": ["تقرير عقيدة البعث والجزاء بعد تقرير توحيد الألوهية.", "تقرير عقيدة القضاء والقدر، وكتابة الأعمال والأحداث في اللوح المحفوظ.", "طلب شهادة أهل الكتاب على صحة الإسلام والحصول عليها لموافقة ما عندهم."], "k": "«لا يعزب عنه مثقال ذرة»… أصغر نيّة في قلبي مكتوبة؛ فهل أنقّي نياتي الصغيرة؟"}, {"lbl": "الآيات ٧ – ٩", "q": "وَقَالَ ٱلَّذِينَ كَفَرُواْ هَلۡ نَدُلُّكُمۡ عَلَىٰ رَجُلٖ يُنَبِّئُكُمۡ إِذَا مُزِّقۡتُمۡ كُلَّ مُمَزَّقٍ إِنَّكُمۡ لَفِي خَلۡقٖ جَدِيدٍ ﴿٧﴾ أَفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةُۢۗ بَلِ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ فِي ٱلۡعَذَابِ وَٱلضَّلَٰلِ ٱلۡبَعِيدِ ﴿٨﴾ أَفَلَمۡ يَرَوۡاْ إِلَىٰ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِن نَّشَأۡ نَخۡسِفۡ بِهِمُ ٱلۡأَرۡضَ أَوۡ نُسۡقِطۡ عَلَيۡهِمۡ كِسَفٗا مِّنَ ٱلسَّمَآءِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّكُلِّ عَبۡدٖ مُّنِيبٖ ﴿٩﴾", "w": [["وقال الذين كفروا", "قال بعضهم لبعض على جهة التعجّب."], ["هل ندلّكم على رجل", "يعنون محمداً ﷺ."], ["إذا مُزّقتم كل ممزّق", "قُطّعتم كل التقطيع."], ["إنكم لفي خلق جديد", "تُبعثون خلقاً جديداً."], ["أم به جنّة", "جنون يخيّل له ذلك."], ["بل الذين لا يؤمنون بالآخرة في العذاب والضلال البعيد", "ليس الأمر كما يقولون، بل الذين لا يؤمنون بالآخرة في العذاب في الآخرة، وفي الضلال البعيد في الدنيا."], ["إلى ما بين أيديهم وما خلفهم", "من كل جهة من السماء والأرض."], ["كسفاً", "قطعاً."], ["لكل عبد منيب", "لكل مؤمن رجّاع إلى ربه في أمره كله."]], "m": "ما زال السياق في تقرير البعث: وقال مشركو مكة بعضهم لبعض متعجّبين مستهزئين: هل ندلّكم على رجل، يعنون محمداً، يخبركم أنكم إذا متّم وتمزّقت أجسامكم وصرتم تراباً تُبعثون في خلق جديد؟ أختلق على الله كذباً أم به مسّ من جنون يخيّل له صور البعث؟ فردّ الله: ليس الأمر كما يقولون، بل الذين لا يؤمنون بالآخرة في العذاب يوم القيامة، وفي الضلال البعيد اليوم، وشؤمهم من تكذيبهم بالبعث. ثم هدّدهم: أفلم ينظروا إلى ما يحيط بهم من السماء والأرض؟ إن نشأ نخسف بهم الأرض أو نُسقط عليهم قطعاً من السماء، فلا يجدون مهرباً مهما هربوا، إن في ذلك لعلامة على قدرة الله لكل عبد رجّاع إلى ربه، إذ هو الذي يجد الآية واضحة أمامه.", "h": ["بيان ما كان المشركون عليه من استهزاء وتكذيب وسخرية بالنبي ﷺ.", "تقرير البعث، وأن المكذّبين به محكوم عليهم بالعذاب فيه.", "لفت الأنظار إلى قدرة الله تعالى المحيطة بالإنسان ليخشى الله ويتّقيه.", "فضل الإنابة إلى الله وشرف المنيب، والإنابة الرجوع إلى الله في كل شيء."], "k": "«لكل عبد منيب»… الآيات تراها القلوب الرجّاعة؛ فكم مرة رجعت إليه اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (309, 34, 10, 19, 'سورة سبأ ١٠ – ١٩', '«ولقد آتينا داود منا فضلاً»، و«اعملوا آل داود شكراً وقليل من عبادي الشكور»، و«لقد كان لسبأ في مسكنهم آية»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 309) = $j$[{"lbl": "الآيات ١٠ – ١٤", "q": "۞وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلٗاۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ ﴿١٠﴾ أَنِ ٱعۡمَلۡ سَٰبِغَٰتٖ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿١١﴾ وَلِسُلَيۡمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهۡرٞ وَرَوَاحُهَا شَهۡرٞۖ وَأَسَلۡنَا لَهُۥ عَيۡنَ ٱلۡقِطۡرِۖ وَمِنَ ٱلۡجِنِّ مَن يَعۡمَلُ بَيۡنَ يَدَيۡهِ بِإِذۡنِ رَبِّهِۦۖ وَمَن يَزِغۡ مِنۡهُمۡ عَنۡ أَمۡرِنَا نُذِقۡهُ مِنۡ عَذَابِ ٱلسَّعِيرِ ﴿١٢﴾ يَعۡمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانٖ كَٱلۡجَوَابِ وَقُدُورٖ رَّاسِيَٰتٍۚ ٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرٗاۚ وَقَلِيلٞ مِّنۡ عِبَادِيَ ٱلشَّكُورُ ﴿١٣﴾ فَلَمَّا قَضَيۡنَا عَلَيۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦٓ إِلَّا دَآبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلۡجِنُّ أَن لَّوۡ كَانُواْ يَعۡلَمُونَ ٱلۡغَيۡبَ مَا لَبِثُواْ فِي ٱلۡعَذَابِ ٱلۡمُهِينِ ﴿١٤﴾", "w": [["ولقد آتينا داود منا فضلاً", "نبوة وملكاً."], ["يا جبال أوّبي معه", "رجّعي معه التسبيح."], ["والطير", "والطير تسبّح أيضاً معه."], ["وألنّا له الحديد", "جعلناه له في اللين كالعجين."], ["أن اعمل سابغات", "دروعاً طويلة تستر المقاتل."], ["وقدّر في السرد", "اجعل المسمار مناسباً للحلقة فلا يفسد الدرع."], ["غدوّها شهر ورواحها شهر", "تسير من الغداة إلى منتصف النهار مسيرة شهر، ومن منتصف النهار إلى الليل مسيرة شهر."], ["وأسلنا له عين القطر", "عين النحاس."], ["من محاريب", "قصور ومقاصير."], ["وجفان كالجواب", "قصاع في الكبر كالحياض."], ["وقدور راسيات", "كبيرة ثابتة على الأثافي لكبرها."], ["دابة الأرض", "الأرضة."], ["تأكل منسأته", "عصاه."]], "m": "يذكر تعالى مظاهر قدرته وإنعامه على عباده ترغيباً في شكره: ولقد آتينا داود منا فضلاً: يا جبال رجّعي معه التسبيح والطير، وألنّا له الحديد حتى كأنه عجين: أن اعمل دروعاً سابغات وقدّر المسامير على قدر الحلق، واعملوا صالحاً إني بما تعملون بصير. وسخّرنا لسليمان الريح تقطع مسيرة شهر في الصباح وشهر في المساء، وكان له مركب من خشب يرفعه الجن ثم تحمله العاصفة كسفينة الفضاء تماماً، وأسلنا له عين النحاس يصنع منه ما شاء، ومن الجن من يعمل بين يديه بإذن ربه، ومن يزغ منهم عن أمرنا نذقه من عذاب السعير، يعملون له ما يشاء من قصور، وتماثيل من نحاس أو خشب إذ لم تكن محرّمة في شريعتهم، وقصاع كالحياض، وقدور ثابتة لكبرها. اعملوا آل داود شكراً بالصلاة والطاعة، وقليل من عبادي الشكور في كل زمان. فلما قضينا عليه الموت وهو متكئ على عصاه في محرابه ما دلّ الجن على موته إلا الأرضة تأكل عصاه، فلما خرّ تبيّنت الجن أنهم لو كانوا يعلمون الغيب ما لبثوا في العذاب المهين من الأعمال الشاقة.", "h": ["بيان إكرام الله تعالى لآل داود، وما وهب داود وسليمان من النعم.", "فضيلة صنع السلاح وآلات الحرب لغرض الجهاد في سبيل الله.", "مركبة سليمان سبقت صنع الطائرات الحالية بآلاف السنين.", "شرع من قبلنا شرع لنا إلا ما خصّه الدليل، كتحريم الصور والتماثيل.", "وجوب الشكر على النعم، وأهم ما يكون به الشكر الصلاة والذكر."], "k": "«اعملوا آل داود شكراً»… الشكر عمل لا كلمة؛ فما العمل الذي أشكر به نعمة اليوم؟"}, {"lbl": "الآيات ١٥ – ١٩", "q": "لَقَدۡ كَانَ لِسَبَإٖ فِي مَسۡكَنِهِمۡ ءَايَةٞۖ جَنَّتَانِ عَن يَمِينٖ وَشِمَالٖۖ كُلُواْ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُواْ لَهُۥۚ بَلۡدَةٞ طَيِّبَةٞ وَرَبٌّ غَفُورٞ ﴿١٥﴾ فَأَعۡرَضُواْ فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطٖ وَأَثۡلٖ وَشَيۡءٖ مِّن سِدۡرٖ قَلِيلٖ ﴿١٦﴾ ذَٰلِكَ جَزَيۡنَٰهُم بِمَا كَفَرُواْۖ وَهَلۡ نُجَٰزِيٓ إِلَّا ٱلۡكَفُورَ ﴿١٧﴾ وَجَعَلۡنَا بَيۡنَهُمۡ وَبَيۡنَ ٱلۡقُرَى ٱلَّتِي بَٰرَكۡنَا فِيهَا قُرٗى ظَٰهِرَةٗ وَقَدَّرۡنَا فِيهَا ٱلسَّيۡرَۖ سِيرُواْ فِيهَا لَيَالِيَ وَأَيَّامًا ءَامِنِينَ ﴿١٨﴾ فَقَالُواْ رَبَّنَا بَٰعِدۡ بَيۡنَ أَسۡفَارِنَا وَظَلَمُوٓاْ أَنفُسَهُمۡ فَجَعَلۡنَٰهُمۡ أَحَادِيثَ وَمَزَّقۡنَٰهُمۡ كُلَّ مُمَزَّقٍۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ﴿١٩﴾", "w": [["لقد كان لسبأ في مسكنهم آية", "لقبيلة سبأ اليمانية علامة على قدرة الله."], ["جنّتان عن يمين وشمال", "بستانان عن يمين الوادي وشماله."], ["بلدة طيبة ورب غفور", "طيبة المناخ بعيدة عن الأوباء، والرب غفور لمن تاب."], ["فأعرضوا", "عن شكر الله وعبادته."], ["سيل العرم", "سيل السدّ العرم."], ["ذواتَي أُكُل خمط وأثل", "صاحبتي ثمر مرّ بشع وشجر الأثل."], ["القرى التي باركنا فيها", "قرى الشام."], ["قرى ظاهرة", "متواصلة من اليمن إلى الشام."], ["وقدّرنا فيها السير", "المسافات بينها مقدّرة يقيلون في واحدة ويبيتون في أخرى."], ["فجعلناهم أحاديث", "أهلكناهم فلم يبق إلا خبرهم."], ["ومزّقناهم كل ممزّق", "فرّقناهم في البلاد كل التفريق."]], "m": "لما ذكر شكر آل داود ذكر أولاد سبأ الذين أنعم عليهم فما شكروا: لقد كان لسبأ، الأزد والأشعريين وحمير وكندة وغيرهم، في مسكنهم آية: جنّتان عن يمين الوادي وشماله تُسقيان بماء سد مأرب، كلوا من رزق ربكم واشكروا له، بلدة طيبة لا وباء فيها ولا هوامّ، ورب غفور إن شكرتم. فأبطرتهم النعم فكذّبوا الرسل وعصوا، فأرسلنا عليهم سيل السدّ فخرّب الجنتين، وبدّلناهم بجنّتيهم جنّتين ذواتَي ثمر مرّ وأثل وشيء من سدر قليل، ذلك جزيناهم بكفرهم، وهل نجازي بمثل هذا إلا الكفور؟ وجعلنا بينهم وبين قرى الشام المباركة قرى متواصلة ظاهرة، وقدّرنا فيها السير، يخرج المسافر بلا زاد فيقيل في مدينة ويبيت في أخرى، سيروا فيها ليالي وأياماً آمنين. فبطروا النعمة وقالوا: ربنا باعد بين أسفارنا، حسداً للفقراء على السفر بلا زاد ولا رواحل، وظلموا أنفسهم، فجعلناهم أحاديث يتحدّث الناس بهم، وفرّقناهم في البلاد كل التفريق، فذهب الأوس والخزرج إلى المدينة، وغسّان إلى الشام، حتى ضُرب بهم المثل: تفرّقوا أيادي سبأ، إن في ذلك لعبراً لكل صبّار شكور.", "h": ["التحذير من الإعراض عن دين الله، فإنه متى حصل لأمة نزل بها البلاء، وكم هذه الحال مشاهدة هنا وهناك.", "التحذير من كفر النعم بالإسراف فيها وصرفها في غير مرضاة الله.", "خطر الحسد، وأنه داء لا دواء له، والعياذ بالله.", "فضيلة الصبر والشكر، وعلوّ شأن الصبور الشكور."], "k": "«ربنا باعد بين أسفارنا»… قد أتمنّى زوال نعمة لا أراها نعمة؛ فما النعمة التي أستثقلها اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 309;
insert into public.tdb_cards(topic, i, body) select 309, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠ – ١٤", "q": "۞وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلٗاۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ ﴿١٠﴾ أَنِ ٱعۡمَلۡ سَٰبِغَٰتٖ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿١١﴾ وَلِسُلَيۡمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهۡرٞ وَرَوَاحُهَا شَهۡرٞۖ وَأَسَلۡنَا لَهُۥ عَيۡنَ ٱلۡقِطۡرِۖ وَمِنَ ٱلۡجِنِّ مَن يَعۡمَلُ بَيۡنَ يَدَيۡهِ بِإِذۡنِ رَبِّهِۦۖ وَمَن يَزِغۡ مِنۡهُمۡ عَنۡ أَمۡرِنَا نُذِقۡهُ مِنۡ عَذَابِ ٱلسَّعِيرِ ﴿١٢﴾ يَعۡمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانٖ كَٱلۡجَوَابِ وَقُدُورٖ رَّاسِيَٰتٍۚ ٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرٗاۚ وَقَلِيلٞ مِّنۡ عِبَادِيَ ٱلشَّكُورُ ﴿١٣﴾ فَلَمَّا قَضَيۡنَا عَلَيۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦٓ إِلَّا دَآبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلۡجِنُّ أَن لَّوۡ كَانُواْ يَعۡلَمُونَ ٱلۡغَيۡبَ مَا لَبِثُواْ فِي ٱلۡعَذَابِ ٱلۡمُهِينِ ﴿١٤﴾", "w": [["ولقد آتينا داود منا فضلاً", "نبوة وملكاً."], ["يا جبال أوّبي معه", "رجّعي معه التسبيح."], ["والطير", "والطير تسبّح أيضاً معه."], ["وألنّا له الحديد", "جعلناه له في اللين كالعجين."], ["أن اعمل سابغات", "دروعاً طويلة تستر المقاتل."], ["وقدّر في السرد", "اجعل المسمار مناسباً للحلقة فلا يفسد الدرع."], ["غدوّها شهر ورواحها شهر", "تسير من الغداة إلى منتصف النهار مسيرة شهر، ومن منتصف النهار إلى الليل مسيرة شهر."], ["وأسلنا له عين القطر", "عين النحاس."], ["من محاريب", "قصور ومقاصير."], ["وجفان كالجواب", "قصاع في الكبر كالحياض."], ["وقدور راسيات", "كبيرة ثابتة على الأثافي لكبرها."], ["دابة الأرض", "الأرضة."], ["تأكل منسأته", "عصاه."]], "m": "يذكر تعالى مظاهر قدرته وإنعامه على عباده ترغيباً في شكره: ولقد آتينا داود منا فضلاً: يا جبال رجّعي معه التسبيح والطير، وألنّا له الحديد حتى كأنه عجين: أن اعمل دروعاً سابغات وقدّر المسامير على قدر الحلق، واعملوا صالحاً إني بما تعملون بصير. وسخّرنا لسليمان الريح تقطع مسيرة شهر في الصباح وشهر في المساء، وكان له مركب من خشب يرفعه الجن ثم تحمله العاصفة كسفينة الفضاء تماماً، وأسلنا له عين النحاس يصنع منه ما شاء، ومن الجن من يعمل بين يديه بإذن ربه، ومن يزغ منهم عن أمرنا نذقه من عذاب السعير، يعملون له ما يشاء من قصور، وتماثيل من نحاس أو خشب إذ لم تكن محرّمة في شريعتهم، وقصاع كالحياض، وقدور ثابتة لكبرها. اعملوا آل داود شكراً بالصلاة والطاعة، وقليل من عبادي الشكور في كل زمان. فلما قضينا عليه الموت وهو متكئ على عصاه في محرابه ما دلّ الجن على موته إلا الأرضة تأكل عصاه، فلما خرّ تبيّنت الجن أنهم لو كانوا يعلمون الغيب ما لبثوا في العذاب المهين من الأعمال الشاقة.", "h": ["بيان إكرام الله تعالى لآل داود، وما وهب داود وسليمان من النعم.", "فضيلة صنع السلاح وآلات الحرب لغرض الجهاد في سبيل الله.", "مركبة سليمان سبقت صنع الطائرات الحالية بآلاف السنين.", "شرع من قبلنا شرع لنا إلا ما خصّه الدليل، كتحريم الصور والتماثيل.", "وجوب الشكر على النعم، وأهم ما يكون به الشكر الصلاة والذكر."], "k": "«اعملوا آل داود شكراً»… الشكر عمل لا كلمة؛ فما العمل الذي أشكر به نعمة اليوم؟"}, {"lbl": "الآيات ١٥ – ١٩", "q": "لَقَدۡ كَانَ لِسَبَإٖ فِي مَسۡكَنِهِمۡ ءَايَةٞۖ جَنَّتَانِ عَن يَمِينٖ وَشِمَالٖۖ كُلُواْ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُواْ لَهُۥۚ بَلۡدَةٞ طَيِّبَةٞ وَرَبٌّ غَفُورٞ ﴿١٥﴾ فَأَعۡرَضُواْ فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطٖ وَأَثۡلٖ وَشَيۡءٖ مِّن سِدۡرٖ قَلِيلٖ ﴿١٦﴾ ذَٰلِكَ جَزَيۡنَٰهُم بِمَا كَفَرُواْۖ وَهَلۡ نُجَٰزِيٓ إِلَّا ٱلۡكَفُورَ ﴿١٧﴾ وَجَعَلۡنَا بَيۡنَهُمۡ وَبَيۡنَ ٱلۡقُرَى ٱلَّتِي بَٰرَكۡنَا فِيهَا قُرٗى ظَٰهِرَةٗ وَقَدَّرۡنَا فِيهَا ٱلسَّيۡرَۖ سِيرُواْ فِيهَا لَيَالِيَ وَأَيَّامًا ءَامِنِينَ ﴿١٨﴾ فَقَالُواْ رَبَّنَا بَٰعِدۡ بَيۡنَ أَسۡفَارِنَا وَظَلَمُوٓاْ أَنفُسَهُمۡ فَجَعَلۡنَٰهُمۡ أَحَادِيثَ وَمَزَّقۡنَٰهُمۡ كُلَّ مُمَزَّقٍۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ﴿١٩﴾", "w": [["لقد كان لسبأ في مسكنهم آية", "لقبيلة سبأ اليمانية علامة على قدرة الله."], ["جنّتان عن يمين وشمال", "بستانان عن يمين الوادي وشماله."], ["بلدة طيبة ورب غفور", "طيبة المناخ بعيدة عن الأوباء، والرب غفور لمن تاب."], ["فأعرضوا", "عن شكر الله وعبادته."], ["سيل العرم", "سيل السدّ العرم."], ["ذواتَي أُكُل خمط وأثل", "صاحبتي ثمر مرّ بشع وشجر الأثل."], ["القرى التي باركنا فيها", "قرى الشام."], ["قرى ظاهرة", "متواصلة من اليمن إلى الشام."], ["وقدّرنا فيها السير", "المسافات بينها مقدّرة يقيلون في واحدة ويبيتون في أخرى."], ["فجعلناهم أحاديث", "أهلكناهم فلم يبق إلا خبرهم."], ["ومزّقناهم كل ممزّق", "فرّقناهم في البلاد كل التفريق."]], "m": "لما ذكر شكر آل داود ذكر أولاد سبأ الذين أنعم عليهم فما شكروا: لقد كان لسبأ، الأزد والأشعريين وحمير وكندة وغيرهم، في مسكنهم آية: جنّتان عن يمين الوادي وشماله تُسقيان بماء سد مأرب، كلوا من رزق ربكم واشكروا له، بلدة طيبة لا وباء فيها ولا هوامّ، ورب غفور إن شكرتم. فأبطرتهم النعم فكذّبوا الرسل وعصوا، فأرسلنا عليهم سيل السدّ فخرّب الجنتين، وبدّلناهم بجنّتيهم جنّتين ذواتَي ثمر مرّ وأثل وشيء من سدر قليل، ذلك جزيناهم بكفرهم، وهل نجازي بمثل هذا إلا الكفور؟ وجعلنا بينهم وبين قرى الشام المباركة قرى متواصلة ظاهرة، وقدّرنا فيها السير، يخرج المسافر بلا زاد فيقيل في مدينة ويبيت في أخرى، سيروا فيها ليالي وأياماً آمنين. فبطروا النعمة وقالوا: ربنا باعد بين أسفارنا، حسداً للفقراء على السفر بلا زاد ولا رواحل، وظلموا أنفسهم، فجعلناهم أحاديث يتحدّث الناس بهم، وفرّقناهم في البلاد كل التفريق، فذهب الأوس والخزرج إلى المدينة، وغسّان إلى الشام، حتى ضُرب بهم المثل: تفرّقوا أيادي سبأ، إن في ذلك لعبراً لكل صبّار شكور.", "h": ["التحذير من الإعراض عن دين الله، فإنه متى حصل لأمة نزل بها البلاء، وكم هذه الحال مشاهدة هنا وهناك.", "التحذير من كفر النعم بالإسراف فيها وصرفها في غير مرضاة الله.", "خطر الحسد، وأنه داء لا دواء له، والعياذ بالله.", "فضيلة الصبر والشكر، وعلوّ شأن الصبور الشكور."], "k": "«ربنا باعد بين أسفارنا»… قد أتمنّى زوال نعمة لا أراها نعمة؛ فما النعمة التي أستثقلها اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (310, 34, 20, 33, 'سورة سبأ ٢٠ – ٣٣', '«ولقد صدّق عليهم إبليس ظنّه»، و«وإنا أو إياكم لعلى هدى أو في ضلال مبين»، و«وما أرسلناك إلا كافّة للناس»، و«بل مكر الليل والنهار»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 310) = $j$[{"lbl": "الآيات ٢٠ – ٢٣", "q": "وَلَقَدۡ صَدَّقَ عَلَيۡهِمۡ إِبۡلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ ﴿٢٠﴾ وَمَا كَانَ لَهُۥ عَلَيۡهِم مِّن سُلۡطَٰنٍ إِلَّا لِنَعۡلَمَ مَن يُؤۡمِنُ بِٱلۡأٓخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِي شَكّٖۗ وَرَبُّكَ عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ ﴿٢١﴾ قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِ ٱللَّهِ لَا يَمۡلِكُونَ مِثۡقَالَ ذَرَّةٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِ وَمَا لَهُمۡ فِيهِمَا مِن شِرۡكٖ وَمَا لَهُۥ مِنۡهُم مِّن ظَهِيرٖ ﴿٢٢﴾ وَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنۡ أَذِنَ لَهُۥۚ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمۡ قَالُواْ مَاذَا قَالَ رَبُّكُمۡۖ قَالُواْ ٱلۡحَقَّۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ ﴿٢٣﴾", "w": [["ولقد صدّق عليهم إبليس ظنّه", "صدق ظنّه فيهم أنه يغويهم."], ["إلا فريقاً من المؤمنين", "المؤمنون المسلمون فإنه خاب ظنّه فيهم."], ["وما كان له عليهم من سلطان", "لم يكن له تسلّط بقوة، وإنما هو التزيين والإغراء."], ["إلا لنعلم من يؤمن بالآخرة", "أذنّا له في إغوائهم لنعلم علم ظهور من يؤمن ممن يشك."], ["قل ادعوا الذين زعمتم", "أنهم شركاء لله."], ["وما لهم فيهما من شرك", "ليس لهم شركة في السماوات ولا في الأرض."], ["وما له منهم من ظهير", "ليس لله منهم معين."], ["إلا لمن أذن له", "لا تنفع الشفاعة إلا لمن أذن الله له."], ["حتى إذا فُزّع عن قلوبهم", "ذهب عنهم الفزع بسماع كلام الله."], ["وهو العلي الكبير", "العلي فوق كل شيء، الكبير الذي ليس أكبر منه."]], "m": "لما ذكر ما حدث لسبأ، وكان عامله الشيطان، أخبر عن حال الناس معه: ولقد صدّق عليهم إبليس ظنّه لما توعّد بإغوائهم فاتّبعوه في الشرك والمعاصي، إلا فريقاً من المؤمنين الصادقين. وما كان له عليهم من تسلّط بقوة مادية ولا معنوية، وإنما أُذن له في التزيين والوسوسة لنعلم علم ظهور من يؤمن بالآخرة فيتحمّل مشاق التكاليف، ممن هو منها في شك فلا ينهض بواجب ولا يجتنب حراماً، وربك على كل شيء حفيظ. قل للمشركين: ادعوا الذين زعمتم أنهم شركاء من دون الله، لا يملكون وزن ذرة في السماوات ولا في الأرض استقلالاً، وما لهم فيهما من شركة، وما لله منهم من معين، ولا تنفع الشفاعة عنده إلا لمن أذن له أن يشفع ولمن رضي أن يُشفع له، فكيف تطمعون في شفاعة آلهتكم؟ حتى إذا زال الفزع عن قلوب الشفعاء بسماع الإذن قال بعضهم لبعض مستبشرين: ماذا قال ربكم؟ قالوا: الحق، أي أذن في الشفاعة، وهو العلي الكبير.", "h": ["بيان أن إبليس صدق ظنه في بني آدم أنهم سيتّبعونه إلا المؤمنين الصادقين.", "تقرير التوحيد، وأنه لا إله إلا الله ولا يستحق العبادة سواه.", "بيان بطلان دعاء غير الله، إذ المدعوّ كائناً من كان لا يملك شيئاً استقلالاً ولا شركة، والشفاعة لا تتم إلا بإذنه، فمن دعا غيره من نبي أو ولي أو غيرهما فقد ضلّ الطريق وأشرك بالله في أعظم عبادة، وهي الدعاء."], "k": "«وما كان له عليهم من سلطان»… الشيطان لا يجرّني بالقوة؛ فأيّ تزيين أطاوعه أنا باختياري؟"}, {"lbl": "الآيات ٢٤ – ٣٠", "q": "۞قُلۡ مَن يَرۡزُقُكُم مِّنَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُلِ ٱللَّهُۖ وَإِنَّآ أَوۡ إِيَّاكُمۡ لَعَلَىٰ هُدًى أَوۡ فِي ضَلَٰلٖ مُّبِينٖ ﴿٢٤﴾ قُل لَّا تُسۡـَٔلُونَ عَمَّآ أَجۡرَمۡنَا وَلَا نُسۡـَٔلُ عَمَّا تَعۡمَلُونَ ﴿٢٥﴾ قُلۡ يَجۡمَعُ بَيۡنَنَا رَبُّنَا ثُمَّ يَفۡتَحُ بَيۡنَنَا بِٱلۡحَقِّ وَهُوَ ٱلۡفَتَّاحُ ٱلۡعَلِيمُ ﴿٢٦﴾ قُلۡ أَرُونِيَ ٱلَّذِينَ أَلۡحَقۡتُم بِهِۦ شُرَكَآءَۖ كَلَّاۚ بَلۡ هُوَ ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٢٧﴾ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا كَآفَّةٗ لِّلنَّاسِ بَشِيرٗا وَنَذِيرٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٢٨﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٢٩﴾ قُل لَّكُم مِّيعَادُ يَوۡمٖ لَّا تَسۡتَـٔۡخِرُونَ عَنۡهُ سَاعَةٗ وَلَا تَسۡتَقۡدِمُونَ ﴿٣٠﴾", "w": [["من يرزقكم من السماوات والأرض", "من السماوات بإنزال المطر، ومن الأرض بإنبات النبات."], ["قل الله", "إن لم يجيبوا فأجب أنت، إذ لا جواب عندهم سواه."], ["وإنا أو إياكم لعلى هدى أو في ضلال مبين", "وقطعاً الموحّدون على هدى والمشركون في ضلال، وإنما شكّكهم تلطّفاً بهم."], ["لا تُسألون عما أجرمنا", "لا تُسألون عن ذنوبنا، تلطّفاً بهم."], ["ثم يفتح بيننا بالحق", "يحكم بيننا بالعدل."], ["أروني الذين ألحقتم به شركاء", "فإن أروه أصناماً لا تسمع ولا تبصر قامت الحجة عليهم."], ["كافّة للناس", "لجميع الناس عربهم وعجمهم."], ["بشيراً ونذيراً", "بشيراً للمؤمنين بالجنة، ونذيراً للكافرين بالنار."], ["لكم ميعاد يوم", "هو يوم القيامة."]], "m": "ما زال السياق في تبكيت المشركين: قل من يرزقكم من السماوات بالمطر ومن الأرض بالنبات؟ قل الله، إذ لا جواب عندهم سواه. وإنا أو إياكم لعلى هدى أو في ضلال مبين، أسلوب تلطّف بالخصم المعاند حتى لا يلجّ في العناد ويفكّر، وقطعاً المؤمنون على الهدى والمشركون في الضلال. قل لا تُسألون عما أجرمنا ولا نُسأل عما تعملون، تلطّف آخر لتهدأ عاصفة العناد. قل يجمع بيننا ربنا يوم القيامة ثم يحكم بيننا بالحق، وهو الفتّاح العليم. قل أروني الذين ألحقتموهم به شركاء، وقد كانوا يقولون في تلبيتهم: لبيك لا شريك لك إلا شريكاً هو لك، كلا لن تكون الأصنام أهلاً للعبادة، بل هو الله العزيز الحكيم. وما أرسلناك إلا للناس كافّة بشيراً ونذيراً، فلا يحزنك إعراضهم، ولكن أكثر الناس لا يعلمون. ويقولون مستهزئين: متى هذا الوعد إن كنتم صادقين؟ قل لكم ميعاد يوم محدّد لا تستأخرون عنه ساعة ولا تستقدمون.", "h": ["مشروعية التلطّف مع الخصم، فسحاً له في مجال التفكير لعله يهتدي.", "تقرير التوحيد والبعث والجزاء، وتنويع الأسلوب الدعوي في ذلك.", "تقرير عقيدة النبوة المحمدية، وعموم رسالة النبي ﷺ إلى الناس كافة.", "يوم القيامة مقرّر بالساعة واليوم، فلا يصح تقديمه ولا تأخيره."], "k": "«وإنا أو إياكم لعلى هدى أو في ضلال مبين»… هل أترك لمحاوري مساحة ليفكّر، أم أحاصره فيعاند؟"}, {"lbl": "الآيات ٣١ – ٣٣", "q": "وَقَالَ ٱلَّذِينَ كَفَرُواْ لَن نُّؤۡمِنَ بِهَٰذَا ٱلۡقُرۡءَانِ وَلَا بِٱلَّذِي بَيۡنَ يَدَيۡهِۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّـٰلِمُونَ مَوۡقُوفُونَ عِندَ رَبِّهِمۡ يَرۡجِعُ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ ٱلۡقَوۡلَ يَقُولُ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ لَوۡلَآ أَنتُمۡ لَكُنَّا مُؤۡمِنِينَ ﴿٣١﴾ قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ لِلَّذِينَ ٱسۡتُضۡعِفُوٓاْ أَنَحۡنُ صَدَدۡنَٰكُمۡ عَنِ ٱلۡهُدَىٰ بَعۡدَ إِذۡ جَآءَكُمۖ بَلۡ كُنتُم مُّجۡرِمِينَ ﴿٣٢﴾ وَقَالَ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ بَلۡ مَكۡرُ ٱلَّيۡلِ وَٱلنَّهَارِ إِذۡ تَأۡمُرُونَنَآ أَن نَّكۡفُرَ بِٱللَّهِ وَنَجۡعَلَ لَهُۥٓ أَندَادٗاۚ وَأَسَرُّواْ ٱلنَّدَامَةَ لَمَّا رَأَوُاْ ٱلۡعَذَابَۚ وَجَعَلۡنَا ٱلۡأَغۡلَٰلَ فِيٓ أَعۡنَاقِ ٱلَّذِينَ كَفَرُواْۖ هَلۡ يُجۡزَوۡنَ إِلَّا مَا كَانُواْ يَعۡمَلُونَ ﴿٣٣﴾", "w": [["ولا بالذي بين يديه", "من الكتب السابقة، التوراة والإنجيل."], ["يرجع بعضهم إلى بعض القول", "يقول الأتباع كذا ويردّ عليهم المتبوعون."], ["أنحن صددناكم عن الهدى", "ينكر المتبوعون أنهم صدّوا أتباعهم."], ["بل كنتم مجرمين", "ظلمة فاسدين."], ["بل مكر الليل والنهار", "بل مكركم بنا في الليل والنهار."], ["ونجعل له أنداداً", "شركاء نعبدهم معه."], ["وأسرّوا الندامة", "أخفوها إذ لا فائدة منها، أو أظهروها."], ["الأغلال في أعناق", "قيود الحديد تُشدّ بها أيديهم إلى أعناقهم."]], "m": "وقال الذين كفروا من مشركي مكة: لن نؤمن بهذا القرآن ولا بالكتب التي قبله، لما وجدوا التوراة والإنجيل يقرّران التوحيد والبعث. ولو ترى إذ الظالمون موقوفون عند ربهم يتحاورون متلاومين، يقول الأتباع المستضعفون للمستكبرين: لولا أنتم لكنا مؤمنين. قال المستكبرون: أنحن صددناكم عن الهدى بعد إذ جاءكم؟ بل كنتم مجرمين. وقال المستضعفون: بل مكركم بنا في الليل والنهار إذ تأمروننا أن نكفر بالله ونجعل له شركاء، وأسرّوا الندامة لما رأوا العذاب، وجعلنا الأغلال في أعناق الذين كفروا تُشدّ بها أيديهم إلى أعناقهم ثم يُدخلون الجحيم، هل يُجزون إلا ما كانوا يعملون؟ والجزاء بحسب العمل، وكانت أعمالهم كلها شراً.", "h": ["تشابه حال الظلمة والمجرمين، فالمشركون لما وجدوا التوراة والإنجيل يقرّران ما في القرآن تبرّؤوا منها جميعاً.", "تقرير عقيدة البعث والجزاء بعرض موقف من مواقف يوم القيامة.", "بطلان احتجاج الناس بعمل العلماء أو الحكماء وأشراف الناس فيما خالف ما جاء به رسل الله من الحق."], "k": "«بل مكر الليل والنهار»… من يزيّن لي المعصية ليلاً ونهاراً، وهل أنا ممن يزيّنها لغيري؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 310;
insert into public.tdb_cards(topic, i, body) select 310, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٠ – ٢٣", "q": "وَلَقَدۡ صَدَّقَ عَلَيۡهِمۡ إِبۡلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ ﴿٢٠﴾ وَمَا كَانَ لَهُۥ عَلَيۡهِم مِّن سُلۡطَٰنٍ إِلَّا لِنَعۡلَمَ مَن يُؤۡمِنُ بِٱلۡأٓخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِي شَكّٖۗ وَرَبُّكَ عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ ﴿٢١﴾ قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِ ٱللَّهِ لَا يَمۡلِكُونَ مِثۡقَالَ ذَرَّةٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِ وَمَا لَهُمۡ فِيهِمَا مِن شِرۡكٖ وَمَا لَهُۥ مِنۡهُم مِّن ظَهِيرٖ ﴿٢٢﴾ وَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنۡ أَذِنَ لَهُۥۚ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمۡ قَالُواْ مَاذَا قَالَ رَبُّكُمۡۖ قَالُواْ ٱلۡحَقَّۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ ﴿٢٣﴾", "w": [["ولقد صدّق عليهم إبليس ظنّه", "صدق ظنّه فيهم أنه يغويهم."], ["إلا فريقاً من المؤمنين", "المؤمنون المسلمون فإنه خاب ظنّه فيهم."], ["وما كان له عليهم من سلطان", "لم يكن له تسلّط بقوة، وإنما هو التزيين والإغراء."], ["إلا لنعلم من يؤمن بالآخرة", "أذنّا له في إغوائهم لنعلم علم ظهور من يؤمن ممن يشك."], ["قل ادعوا الذين زعمتم", "أنهم شركاء لله."], ["وما لهم فيهما من شرك", "ليس لهم شركة في السماوات ولا في الأرض."], ["وما له منهم من ظهير", "ليس لله منهم معين."], ["إلا لمن أذن له", "لا تنفع الشفاعة إلا لمن أذن الله له."], ["حتى إذا فُزّع عن قلوبهم", "ذهب عنهم الفزع بسماع كلام الله."], ["وهو العلي الكبير", "العلي فوق كل شيء، الكبير الذي ليس أكبر منه."]], "m": "لما ذكر ما حدث لسبأ، وكان عامله الشيطان، أخبر عن حال الناس معه: ولقد صدّق عليهم إبليس ظنّه لما توعّد بإغوائهم فاتّبعوه في الشرك والمعاصي، إلا فريقاً من المؤمنين الصادقين. وما كان له عليهم من تسلّط بقوة مادية ولا معنوية، وإنما أُذن له في التزيين والوسوسة لنعلم علم ظهور من يؤمن بالآخرة فيتحمّل مشاق التكاليف، ممن هو منها في شك فلا ينهض بواجب ولا يجتنب حراماً، وربك على كل شيء حفيظ. قل للمشركين: ادعوا الذين زعمتم أنهم شركاء من دون الله، لا يملكون وزن ذرة في السماوات ولا في الأرض استقلالاً، وما لهم فيهما من شركة، وما لله منهم من معين، ولا تنفع الشفاعة عنده إلا لمن أذن له أن يشفع ولمن رضي أن يُشفع له، فكيف تطمعون في شفاعة آلهتكم؟ حتى إذا زال الفزع عن قلوب الشفعاء بسماع الإذن قال بعضهم لبعض مستبشرين: ماذا قال ربكم؟ قالوا: الحق، أي أذن في الشفاعة، وهو العلي الكبير.", "h": ["بيان أن إبليس صدق ظنه في بني آدم أنهم سيتّبعونه إلا المؤمنين الصادقين.", "تقرير التوحيد، وأنه لا إله إلا الله ولا يستحق العبادة سواه.", "بيان بطلان دعاء غير الله، إذ المدعوّ كائناً من كان لا يملك شيئاً استقلالاً ولا شركة، والشفاعة لا تتم إلا بإذنه، فمن دعا غيره من نبي أو ولي أو غيرهما فقد ضلّ الطريق وأشرك بالله في أعظم عبادة، وهي الدعاء."], "k": "«وما كان له عليهم من سلطان»… الشيطان لا يجرّني بالقوة؛ فأيّ تزيين أطاوعه أنا باختياري؟"}, {"lbl": "الآيات ٢٤ – ٣٠", "q": "۞قُلۡ مَن يَرۡزُقُكُم مِّنَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُلِ ٱللَّهُۖ وَإِنَّآ أَوۡ إِيَّاكُمۡ لَعَلَىٰ هُدًى أَوۡ فِي ضَلَٰلٖ مُّبِينٖ ﴿٢٤﴾ قُل لَّا تُسۡـَٔلُونَ عَمَّآ أَجۡرَمۡنَا وَلَا نُسۡـَٔلُ عَمَّا تَعۡمَلُونَ ﴿٢٥﴾ قُلۡ يَجۡمَعُ بَيۡنَنَا رَبُّنَا ثُمَّ يَفۡتَحُ بَيۡنَنَا بِٱلۡحَقِّ وَهُوَ ٱلۡفَتَّاحُ ٱلۡعَلِيمُ ﴿٢٦﴾ قُلۡ أَرُونِيَ ٱلَّذِينَ أَلۡحَقۡتُم بِهِۦ شُرَكَآءَۖ كَلَّاۚ بَلۡ هُوَ ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٢٧﴾ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا كَآفَّةٗ لِّلنَّاسِ بَشِيرٗا وَنَذِيرٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٢٨﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٢٩﴾ قُل لَّكُم مِّيعَادُ يَوۡمٖ لَّا تَسۡتَـٔۡخِرُونَ عَنۡهُ سَاعَةٗ وَلَا تَسۡتَقۡدِمُونَ ﴿٣٠﴾", "w": [["من يرزقكم من السماوات والأرض", "من السماوات بإنزال المطر، ومن الأرض بإنبات النبات."], ["قل الله", "إن لم يجيبوا فأجب أنت، إذ لا جواب عندهم سواه."], ["وإنا أو إياكم لعلى هدى أو في ضلال مبين", "وقطعاً الموحّدون على هدى والمشركون في ضلال، وإنما شكّكهم تلطّفاً بهم."], ["لا تُسألون عما أجرمنا", "لا تُسألون عن ذنوبنا، تلطّفاً بهم."], ["ثم يفتح بيننا بالحق", "يحكم بيننا بالعدل."], ["أروني الذين ألحقتم به شركاء", "فإن أروه أصناماً لا تسمع ولا تبصر قامت الحجة عليهم."], ["كافّة للناس", "لجميع الناس عربهم وعجمهم."], ["بشيراً ونذيراً", "بشيراً للمؤمنين بالجنة، ونذيراً للكافرين بالنار."], ["لكم ميعاد يوم", "هو يوم القيامة."]], "m": "ما زال السياق في تبكيت المشركين: قل من يرزقكم من السماوات بالمطر ومن الأرض بالنبات؟ قل الله، إذ لا جواب عندهم سواه. وإنا أو إياكم لعلى هدى أو في ضلال مبين، أسلوب تلطّف بالخصم المعاند حتى لا يلجّ في العناد ويفكّر، وقطعاً المؤمنون على الهدى والمشركون في الضلال. قل لا تُسألون عما أجرمنا ولا نُسأل عما تعملون، تلطّف آخر لتهدأ عاصفة العناد. قل يجمع بيننا ربنا يوم القيامة ثم يحكم بيننا بالحق، وهو الفتّاح العليم. قل أروني الذين ألحقتموهم به شركاء، وقد كانوا يقولون في تلبيتهم: لبيك لا شريك لك إلا شريكاً هو لك، كلا لن تكون الأصنام أهلاً للعبادة، بل هو الله العزيز الحكيم. وما أرسلناك إلا للناس كافّة بشيراً ونذيراً، فلا يحزنك إعراضهم، ولكن أكثر الناس لا يعلمون. ويقولون مستهزئين: متى هذا الوعد إن كنتم صادقين؟ قل لكم ميعاد يوم محدّد لا تستأخرون عنه ساعة ولا تستقدمون.", "h": ["مشروعية التلطّف مع الخصم، فسحاً له في مجال التفكير لعله يهتدي.", "تقرير التوحيد والبعث والجزاء، وتنويع الأسلوب الدعوي في ذلك.", "تقرير عقيدة النبوة المحمدية، وعموم رسالة النبي ﷺ إلى الناس كافة.", "يوم القيامة مقرّر بالساعة واليوم، فلا يصح تقديمه ولا تأخيره."], "k": "«وإنا أو إياكم لعلى هدى أو في ضلال مبين»… هل أترك لمحاوري مساحة ليفكّر، أم أحاصره فيعاند؟"}, {"lbl": "الآيات ٣١ – ٣٣", "q": "وَقَالَ ٱلَّذِينَ كَفَرُواْ لَن نُّؤۡمِنَ بِهَٰذَا ٱلۡقُرۡءَانِ وَلَا بِٱلَّذِي بَيۡنَ يَدَيۡهِۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّـٰلِمُونَ مَوۡقُوفُونَ عِندَ رَبِّهِمۡ يَرۡجِعُ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ ٱلۡقَوۡلَ يَقُولُ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ لَوۡلَآ أَنتُمۡ لَكُنَّا مُؤۡمِنِينَ ﴿٣١﴾ قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ لِلَّذِينَ ٱسۡتُضۡعِفُوٓاْ أَنَحۡنُ صَدَدۡنَٰكُمۡ عَنِ ٱلۡهُدَىٰ بَعۡدَ إِذۡ جَآءَكُمۖ بَلۡ كُنتُم مُّجۡرِمِينَ ﴿٣٢﴾ وَقَالَ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ بَلۡ مَكۡرُ ٱلَّيۡلِ وَٱلنَّهَارِ إِذۡ تَأۡمُرُونَنَآ أَن نَّكۡفُرَ بِٱللَّهِ وَنَجۡعَلَ لَهُۥٓ أَندَادٗاۚ وَأَسَرُّواْ ٱلنَّدَامَةَ لَمَّا رَأَوُاْ ٱلۡعَذَابَۚ وَجَعَلۡنَا ٱلۡأَغۡلَٰلَ فِيٓ أَعۡنَاقِ ٱلَّذِينَ كَفَرُواْۖ هَلۡ يُجۡزَوۡنَ إِلَّا مَا كَانُواْ يَعۡمَلُونَ ﴿٣٣﴾", "w": [["ولا بالذي بين يديه", "من الكتب السابقة، التوراة والإنجيل."], ["يرجع بعضهم إلى بعض القول", "يقول الأتباع كذا ويردّ عليهم المتبوعون."], ["أنحن صددناكم عن الهدى", "ينكر المتبوعون أنهم صدّوا أتباعهم."], ["بل كنتم مجرمين", "ظلمة فاسدين."], ["بل مكر الليل والنهار", "بل مكركم بنا في الليل والنهار."], ["ونجعل له أنداداً", "شركاء نعبدهم معه."], ["وأسرّوا الندامة", "أخفوها إذ لا فائدة منها، أو أظهروها."], ["الأغلال في أعناق", "قيود الحديد تُشدّ بها أيديهم إلى أعناقهم."]], "m": "وقال الذين كفروا من مشركي مكة: لن نؤمن بهذا القرآن ولا بالكتب التي قبله، لما وجدوا التوراة والإنجيل يقرّران التوحيد والبعث. ولو ترى إذ الظالمون موقوفون عند ربهم يتحاورون متلاومين، يقول الأتباع المستضعفون للمستكبرين: لولا أنتم لكنا مؤمنين. قال المستكبرون: أنحن صددناكم عن الهدى بعد إذ جاءكم؟ بل كنتم مجرمين. وقال المستضعفون: بل مكركم بنا في الليل والنهار إذ تأمروننا أن نكفر بالله ونجعل له شركاء، وأسرّوا الندامة لما رأوا العذاب، وجعلنا الأغلال في أعناق الذين كفروا تُشدّ بها أيديهم إلى أعناقهم ثم يُدخلون الجحيم، هل يُجزون إلا ما كانوا يعملون؟ والجزاء بحسب العمل، وكانت أعمالهم كلها شراً.", "h": ["تشابه حال الظلمة والمجرمين، فالمشركون لما وجدوا التوراة والإنجيل يقرّران ما في القرآن تبرّؤوا منها جميعاً.", "تقرير عقيدة البعث والجزاء بعرض موقف من مواقف يوم القيامة.", "بطلان احتجاج الناس بعمل العلماء أو الحكماء وأشراف الناس فيما خالف ما جاء به رسل الله من الحق."], "k": "«بل مكر الليل والنهار»… من يزيّن لي المعصية ليلاً ونهاراً، وهل أنا ممن يزيّنها لغيري؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (311, 34, 34, 46, 'سورة سبأ ٣٤ – ٤٦', '«نحن أكثر أموالاً وأولاداً»، و«وما أموالكم ولا أولادكم بالتي تقرّبكم عندنا زلفى»، و«قل إنما أعظكم بواحدة أن تقوموا لله مثنى وفرادى»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 311) = $j$[{"lbl": "الآيات ٣٤ – ٣٩", "q": "وَمَآ أَرۡسَلۡنَا فِي قَرۡيَةٖ مِّن نَّذِيرٍ إِلَّا قَالَ مُتۡرَفُوهَآ إِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ ﴿٣٤﴾ وَقَالُواْ نَحۡنُ أَكۡثَرُ أَمۡوَٰلٗا وَأَوۡلَٰدٗا وَمَا نَحۡنُ بِمُعَذَّبِينَ ﴿٣٥﴾ قُلۡ إِنَّ رَبِّي يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٣٦﴾ وَمَآ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُم بِٱلَّتِي تُقَرِّبُكُمۡ عِندَنَا زُلۡفَىٰٓ إِلَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَأُوْلَـٰٓئِكَ لَهُمۡ جَزَآءُ ٱلضِّعۡفِ بِمَا عَمِلُواْ وَهُمۡ فِي ٱلۡغُرُفَٰتِ ءَامِنُونَ ﴿٣٧﴾ وَٱلَّذِينَ يَسۡعَوۡنَ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَـٰٓئِكَ فِي ٱلۡعَذَابِ مُحۡضَرُونَ ﴿٣٨﴾ قُلۡ إِنَّ رَبِّي يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُ لَهُۥۚ وَمَآ أَنفَقۡتُم مِّن شَيۡءٖ فَهُوَ يُخۡلِفُهُۥۖ وَهُوَ خَيۡرُ ٱلرَّـٰزِقِينَ ﴿٣٩﴾", "w": [["إلا قال مترفوها", "رؤساؤها المنعّمون من أهل المال."], ["نحن أكثر أموالاً وأولاداً", "من المؤمنين."], ["يبسط الرزق لمن يشاء", "امتحاناً: أيشكر أم يكفر."], ["ويقدر", "يضيّق ابتلاءً: أيصبر أم يسخط."], ["تقرّبكم عندنا زلفى", "قربى."], ["إلا من آمن وعمل صالحاً", "هو الذي يقرّبه إيمانه وعمله."], ["جزاء الضعف", "الحسنة بعشر أمثالها إلى سبعمئة ضعف."], ["وهم في الغرفات آمنون", "من المرض والموت وكل مكروه."], ["معاجزين", "ظانّين أنهم يفوتوننا."], ["فهو يُخلفه", "يعوّضه."], ["وهو خير الرازقين", "خير المعطين."]], "m": "هذا شروع في تسلية الرسول ﷺ بذكر ما واجهت به الأمم رسلها: وما أرسلنا في قرية من نذير إلا قال المتنعّمون فيها: إنا بما أُرسلتم به كافرون، نحن أكثر أموالاً وأولاداً، وما نحن بمعذّبين، مغترّين بأن ما أعطاهم الله لرضاه عنهم. قل إن ربي يبسط الرزق لمن يشاء امتحاناً لا رضاً، ويضيّقه ابتلاءً لا بغضاً، ولكن أكثر الناس لا يعلمون. وما أموالكم ولا أولادكم بالتي تقرّبكم عندنا قربى، إلا من آمن وعمل صالحاً فأولئك لهم جزاء الضعف بما عملوا، تُضاعف لهم حسناتهم، وهم في غرفات الجنة آمنون من كل مكروه. والذين يسعون في إبطال آياتنا ظانّين أنهم يفوتوننا أولئك في العذاب محضرون. قل إن ربي يبسط الرزق لمن يشاء ويضيّقه، وما أنفقتم من شيء في سبيل الله فهو يُخلفه عليكم، فالإنفاق لا ينقص المال، والبخل لا يزيده، وهو خير الرازقين.", "h": ["بيان سنّة الله في الأمم والشعوب، وأنهم ما أتاهم من رسول إلا كذّبه المترفون.", "بيان اغترار المترفين بما آتاهم الله من مال وولد ظانّين أنه لرضاه عنهم.", "بيان الحكمة في التوسعة على بعض والتضييق على بعض، وأنها لا تدل على حب الله ولا على بغضه للعبد.", "بيان ما يقرّب إلى الله، وهو الإيمان والعمل الصالح، لا كثرة المال والولد كما يظن المغرورون.", "بيان حكم الله فيمن يحارب الإسلام ويريد إبطاله.", "بيان وعد الله تعالى بالخلف لكل من أنفق في سبيله."], "k": "«وما أنفقتم من شيء فهو يُخلفه»… ما الذي أمسكه خوف النقص وقد وعدني بالخلف؟"}, {"lbl": "الآيات ٤٠ – ٤٢", "q": "وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ يَقُولُ لِلۡمَلَـٰٓئِكَةِ أَهَـٰٓؤُلَآءِ إِيَّاكُمۡ كَانُواْ يَعۡبُدُونَ ﴿٤٠﴾ قَالُواْ سُبۡحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِمۖ بَلۡ كَانُواْ يَعۡبُدُونَ ٱلۡجِنَّۖ أَكۡثَرُهُم بِهِم مُّؤۡمِنُونَ ﴿٤١﴾ فَٱلۡيَوۡمَ لَا يَمۡلِكُ بَعۡضُكُمۡ لِبَعۡضٖ نَّفۡعٗا وَلَا ضَرّٗا وَنَقُولُ لِلَّذِينَ ظَلَمُواْ ذُوقُواْ عَذَابَ ٱلنَّارِ ٱلَّتِي كُنتُم بِهَا تُكَذِّبُونَ ﴿٤٢﴾", "w": [["ويوم نحشرهم جميعاً", "واذكر يوم نجمعهم."], ["أهؤلاء إياكم كانوا يعبدون", "يقول تعالى ذلك للملائكة تقريعاً للمشركين."], ["قالوا سبحانك", "تقديساً لك عن الشريك."], ["أنت وليّنا من دونهم", "لا موالاة بيننا وبينهم."], ["بل كانوا يعبدون الجن", "الشياطين التي تمثّلت لهم فأطاعوها."], ["لا يملك بعضكم لبعض نفعاً ولا ضراً", "لا يملك المعبودون للعابدين نفعاً ولا ضراً."], ["التي كنتم بها تكذّبون", "كنتم في الدنيا تكذّبون بالبعث."]], "m": "ما زال السياق في تقرير البعث والتوحيد: واذكر يوم نحشر المشركين جميعاً ثم نقول للملائكة تقريعاً للمشركين: أهؤلاء إياكم كانوا يعبدون؟ قالوا: سبحانك تنزيهاً لك عن الشرك، أنت وليّنا من دونهم، لا ولاية بيننا وبينهم، بل كانوا يعبدون الجن، الشياطين التي زيّنت لهم عبادة الأصنام فأطاعوها، أكثرهم بهم مؤمنون. فاليوم لا يملك المعبودون للعابدين نفعاً ولا ضراً، قطعاً لرجائهم في شفاعتهم، ونقول للذين أشركوا: ذوقوا عذاب النار التي كنتم بها تكذّبون.", "h": ["تقرير عقيدة البعث والجزاء بذكر بعض أحوالها.", "أن من كانوا يعبدون الملائكة والأنبياء والصالحين إنما عبدوا الشياطين التي زيّنت لهم الشرك، أما الملائكة والأنبياء والأولياء فلم يرضوا بذلك.", "بيان توبيخ أهل النار بتكذيبهم في الدنيا بالآخرة."], "k": "«بل كانوا يعبدون الجن»… كل طاعة لمعصية هي طاعة لمن زيّنها؛ فمن أطيع حين أعصي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 311;
