insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (312, 34, 43, 54, 'سورة سبأ ٤٣ – ٥٤', '«إن هو إلا نذير لكم بين يدي عذاب شديد»، و«قل جاء الحق وما يبدئ الباطل وما يعيد»، و«وحيل بينهم وبين ما يشتهون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 312) = $j$[{"lbl": "الآيات ٤٣ – ٤٦", "q": "وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالُواْ مَا هَٰذَآ إِلَّا رَجُلٞ يُرِيدُ أَن يَصُدَّكُمۡ عَمَّا كَانَ يَعۡبُدُ ءَابَآؤُكُمۡ وَقَالُواْ مَا هَٰذَآ إِلَّآ إِفۡكٞ مُّفۡتَرٗىۚ وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلۡحَقِّ لَمَّا جَآءَهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ ﴿٤٣﴾ وَمَآ ءَاتَيۡنَٰهُم مِّن كُتُبٖ يَدۡرُسُونَهَاۖ وَمَآ أَرۡسَلۡنَآ إِلَيۡهِمۡ قَبۡلَكَ مِن نَّذِيرٖ ﴿٤٤﴾ وَكَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَمَا بَلَغُواْ مِعۡشَارَ مَآ ءَاتَيۡنَٰهُمۡ فَكَذَّبُواْ رُسُلِيۖ فَكَيۡفَ كَانَ نَكِيرِ ﴿٤٥﴾ ۞قُلۡ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍۖ أَن تَقُومُواْ لِلَّهِ مَثۡنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُواْۚ مَا بِصَاحِبِكُم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِيرٞ لَّكُم بَيۡنَ يَدَيۡ عَذَابٖ شَدِيدٖ ﴿٤٦﴾", "w": [["آياتنا بيّنات", "آيات القرآن واضحات المعاني."], ["ما هذا إلا رجل", "ما محمد إلا رجل من الرجال."], ["يريد أن يصدّكم عما كان يعبد آباؤكم", "يصرفكم عن عبادة آلهتكم."], ["إلا إفك مفترى", "كذب مختلق."], ["إن هذا إلا سحر مبين", "ما القرآن إلا سحر بيّن."], ["من كتب يدرسونها", "فتبيح لهم الشرك."], ["وما أرسلنا إليهم قبلك من نذير", "لم نرسل إليهم رسولاً قبلك يأذن لهم بالشرك."], ["وما بلغوا معشار ما آتيناهم", "لم يبلغ هؤلاء عشر ما أعطينا الأمم السابقة من القوة."], ["فكيف كان نكير", "إنكاري عليهم بالعقوبة."], ["أن تقوموا لله مثنى وفرادى", "متجرّدين لله، اثنين اثنين وواحداً واحداً."]], "m": "ما زال السياق في عرض مواقف المشركين: وإذا تُتلى عليهم آياتنا واضحات قالوا: ما هذا إلا رجل يريد أن يصرفكم عما كان يعبد آباؤكم، ولا يخجلون، فهو يصرفهم عن الأوثان إلى عبادة الرحمن، وقالوا عن القرآن: ما هذا إلا كذب مختلق، وقالوا لما رأوا أثره في النفوس: إن هذا إلا سحر مبين. وما أعطيناهم من كتب يقرؤونها تبيح لهم الشرك، وما أرسلنا إليهم قبلك من رسول أذن لهم فيه، فمن أين هذا الإصرار؟ وكذّب الذين من قبلهم، وما بلغ هؤلاء عشر ما آتينا أولئك من القوة، فكذّبوا رسلي فكيف كان إنكاري عليهم بإبادتهم؟ قل: إنما أعظكم بخصلة واحدة: أن تقوموا لله متجرّدين من الهوى والتعصّب، اثنين اثنين وواحداً واحداً، ثم تتفكّروا في حياة صاحبكم وأخلاقه ومواقفه، فإنكم تعلمون ما به من جنون، إن هو إلا نذير لكم بين يدي عذاب شديد، مشفق عليكم.", "h": ["بيان عناد المشركين وسخف عقولهم وهبوطهم الفكري.", "ضعف كفار قريش إذا قيسوا بالأمم السابقة، إذ لم يبلغوا عشر ما كانوا عليه.", "تقرير النبوة المحمدية وإثباتها، ونفي الجنون عنه ﷺ."], "k": "«أن تقوموا لله مثنى وفرادى ثم تتفكّروا»… متى جلست وحدي أو مع صاحب صادق أتفكّر بلا تعصّب؟"}, {"lbl": "الآيات ٤٧ – ٥٤", "q": "قُلۡ مَا سَأَلۡتُكُم مِّنۡ أَجۡرٖ فَهُوَ لَكُمۡۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٞ ﴿٤٧﴾ قُلۡ إِنَّ رَبِّي يَقۡذِفُ بِٱلۡحَقِّ عَلَّـٰمُ ٱلۡغُيُوبِ ﴿٤٨﴾ قُلۡ جَآءَ ٱلۡحَقُّ وَمَا يُبۡدِئُ ٱلۡبَٰطِلُ وَمَا يُعِيدُ ﴿٤٩﴾ قُلۡ إِن ضَلَلۡتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفۡسِيۖ وَإِنِ ٱهۡتَدَيۡتُ فَبِمَا يُوحِيٓ إِلَيَّ رَبِّيٓۚ إِنَّهُۥ سَمِيعٞ قَرِيبٞ ﴿٥٠﴾ وَلَوۡ تَرَىٰٓ إِذۡ فَزِعُواْ فَلَا فَوۡتَ وَأُخِذُواْ مِن مَّكَانٖ قَرِيبٖ ﴿٥١﴾ وَقَالُوٓاْ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانِۭ بَعِيدٖ ﴿٥٢﴾ وَقَدۡ كَفَرُواْ بِهِۦ مِن قَبۡلُۖ وَيَقۡذِفُونَ بِٱلۡغَيۡبِ مِن مَّكَانِۭ بَعِيدٖ ﴿٥٣﴾ وَحِيلَ بَيۡنَهُمۡ وَبَيۡنَ مَا يَشۡتَهُونَ كَمَا فُعِلَ بِأَشۡيَاعِهِم مِّن قَبۡلُۚ إِنَّهُمۡ كَانُواْ فِي شَكّٖ مُّرِيبِۭ ﴿٥٤﴾", "w": [["ما سألتكم من أجر", "على إنذاري."], ["يقذف بالحق", "يلقي بالوحي الحق إلى أنبيائه."], ["وما يُبدئ الباطل وما يعيد", "لم يبق للباطل مكان ولا أثر."], ["فإنما أضلّ على نفسي", "إثم ضلالي على نفسي."], ["إنه سميع قريب", "سميع لما أقول، قريب غير بعيد."], ["إذ فزعوا فلا فوت", "فزعوا للبعث فلا مهرب لهم."], ["وأنّى لهم التناوش من مكان بعيد", "كيف يتناولون الإيمان وهم في الآخرة والإيمان في الدنيا؟"], ["ويقذفون بالغيب", "يرمون الرسول بالظنون بلا دليل."], ["وحيل بينهم وبين ما يشتهون", "وهو الإيمان الموجب للنجاة."], ["كما فُعل بأشياعهم من قبل", "بأمثالهم من الأمم."], ["في شك مريب", "موقع في الريب والاضطراب."]], "m": "لما دعاهم إلى التفكّر أمره أن يقول: ما سألتكم من أجر على إنذاري فهو لكم، إن أجري إلا على الله، وهو على كل شيء شهيد. قل إن ربي يلقي بالوحي الحق إلى من يشاء، علام الغيوب يعلم من هو أهل للوحي. قل جاء الحق، الإسلام، وما يبدئ الباطل وما يعيد، فلم يبق له مكان، وصدق الله، فما هي إلا سنوات والإسلام ضارب بجرانه في الجزيرة. قل إن ضللت فإنما إثم ضلالي على نفسي، وإن اهتديت فبما يوحي إليّ ربي، إنه سميع قريب. ولو ترى إذ فزع المشركون يوم القيامة فلا مهرب لهم، وأُخذوا من مكان قريب فأُلقوا في جهنم، لرأيت أمراً فظيعاً. وقالوا: آمنا به، وكيف لهم تناول الإيمان من مكان بعيد، وهم في الآخرة والإيمان في الدنيا؟ وقد كفروا به من قبل وهو معروض عليهم، ويرمون الرسول بالظنون: مرة كاذب، ومرة ساحر، وحيل بينهم وبين الإيمان الذي يشتهونه، كما فُعل بأمثالهم من قبل، إنهم كانوا في شك مريب.", "h": ["دعوة الله ينبغي ألا يأخذ الداعي عليها أجراً.", "بيان صدق الله تعالى في قوله: «جاء الحق وما يبدئ الباطل وما يعيد».", "الإيمان الاضطراري لا ينفع صاحبه، كإيمان من رأى العذاب.", "الشك كفر، ولا إيمان مع رؤية العذاب."], "k": "«وأنّى لهم التناوش من مكان بعيد»… الإيمان الآن قريب المتناول؛ فلا أؤجّله حتى يبعد."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 312;
insert into public.tdb_cards(topic, i, body) select 312, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٣ – ٤٦", "q": "وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالُواْ مَا هَٰذَآ إِلَّا رَجُلٞ يُرِيدُ أَن يَصُدَّكُمۡ عَمَّا كَانَ يَعۡبُدُ ءَابَآؤُكُمۡ وَقَالُواْ مَا هَٰذَآ إِلَّآ إِفۡكٞ مُّفۡتَرٗىۚ وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلۡحَقِّ لَمَّا جَآءَهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ ﴿٤٣﴾ وَمَآ ءَاتَيۡنَٰهُم مِّن كُتُبٖ يَدۡرُسُونَهَاۖ وَمَآ أَرۡسَلۡنَآ إِلَيۡهِمۡ قَبۡلَكَ مِن نَّذِيرٖ ﴿٤٤﴾ وَكَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَمَا بَلَغُواْ مِعۡشَارَ مَآ ءَاتَيۡنَٰهُمۡ فَكَذَّبُواْ رُسُلِيۖ فَكَيۡفَ كَانَ نَكِيرِ ﴿٤٥﴾ ۞قُلۡ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍۖ أَن تَقُومُواْ لِلَّهِ مَثۡنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُواْۚ مَا بِصَاحِبِكُم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِيرٞ لَّكُم بَيۡنَ يَدَيۡ عَذَابٖ شَدِيدٖ ﴿٤٦﴾", "w": [["آياتنا بيّنات", "آيات القرآن واضحات المعاني."], ["ما هذا إلا رجل", "ما محمد إلا رجل من الرجال."], ["يريد أن يصدّكم عما كان يعبد آباؤكم", "يصرفكم عن عبادة آلهتكم."], ["إلا إفك مفترى", "كذب مختلق."], ["إن هذا إلا سحر مبين", "ما القرآن إلا سحر بيّن."], ["من كتب يدرسونها", "فتبيح لهم الشرك."], ["وما أرسلنا إليهم قبلك من نذير", "لم نرسل إليهم رسولاً قبلك يأذن لهم بالشرك."], ["وما بلغوا معشار ما آتيناهم", "لم يبلغ هؤلاء عشر ما أعطينا الأمم السابقة من القوة."], ["فكيف كان نكير", "إنكاري عليهم بالعقوبة."], ["أن تقوموا لله مثنى وفرادى", "متجرّدين لله، اثنين اثنين وواحداً واحداً."]], "m": "ما زال السياق في عرض مواقف المشركين: وإذا تُتلى عليهم آياتنا واضحات قالوا: ما هذا إلا رجل يريد أن يصرفكم عما كان يعبد آباؤكم، ولا يخجلون، فهو يصرفهم عن الأوثان إلى عبادة الرحمن، وقالوا عن القرآن: ما هذا إلا كذب مختلق، وقالوا لما رأوا أثره في النفوس: إن هذا إلا سحر مبين. وما أعطيناهم من كتب يقرؤونها تبيح لهم الشرك، وما أرسلنا إليهم قبلك من رسول أذن لهم فيه، فمن أين هذا الإصرار؟ وكذّب الذين من قبلهم، وما بلغ هؤلاء عشر ما آتينا أولئك من القوة، فكذّبوا رسلي فكيف كان إنكاري عليهم بإبادتهم؟ قل: إنما أعظكم بخصلة واحدة: أن تقوموا لله متجرّدين من الهوى والتعصّب، اثنين اثنين وواحداً واحداً، ثم تتفكّروا في حياة صاحبكم وأخلاقه ومواقفه، فإنكم تعلمون ما به من جنون، إن هو إلا نذير لكم بين يدي عذاب شديد، مشفق عليكم.", "h": ["بيان عناد المشركين وسخف عقولهم وهبوطهم الفكري.", "ضعف كفار قريش إذا قيسوا بالأمم السابقة، إذ لم يبلغوا عشر ما كانوا عليه.", "تقرير النبوة المحمدية وإثباتها، ونفي الجنون عنه ﷺ."], "k": "«أن تقوموا لله مثنى وفرادى ثم تتفكّروا»… متى جلست وحدي أو مع صاحب صادق أتفكّر بلا تعصّب؟"}, {"lbl": "الآيات ٤٧ – ٥٤", "q": "قُلۡ مَا سَأَلۡتُكُم مِّنۡ أَجۡرٖ فَهُوَ لَكُمۡۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٞ ﴿٤٧﴾ قُلۡ إِنَّ رَبِّي يَقۡذِفُ بِٱلۡحَقِّ عَلَّـٰمُ ٱلۡغُيُوبِ ﴿٤٨﴾ قُلۡ جَآءَ ٱلۡحَقُّ وَمَا يُبۡدِئُ ٱلۡبَٰطِلُ وَمَا يُعِيدُ ﴿٤٩﴾ قُلۡ إِن ضَلَلۡتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفۡسِيۖ وَإِنِ ٱهۡتَدَيۡتُ فَبِمَا يُوحِيٓ إِلَيَّ رَبِّيٓۚ إِنَّهُۥ سَمِيعٞ قَرِيبٞ ﴿٥٠﴾ وَلَوۡ تَرَىٰٓ إِذۡ فَزِعُواْ فَلَا فَوۡتَ وَأُخِذُواْ مِن مَّكَانٖ قَرِيبٖ ﴿٥١﴾ وَقَالُوٓاْ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانِۭ بَعِيدٖ ﴿٥٢﴾ وَقَدۡ كَفَرُواْ بِهِۦ مِن قَبۡلُۖ وَيَقۡذِفُونَ بِٱلۡغَيۡبِ مِن مَّكَانِۭ بَعِيدٖ ﴿٥٣﴾ وَحِيلَ بَيۡنَهُمۡ وَبَيۡنَ مَا يَشۡتَهُونَ كَمَا فُعِلَ بِأَشۡيَاعِهِم مِّن قَبۡلُۚ إِنَّهُمۡ كَانُواْ فِي شَكّٖ مُّرِيبِۭ ﴿٥٤﴾", "w": [["ما سألتكم من أجر", "على إنذاري."], ["يقذف بالحق", "يلقي بالوحي الحق إلى أنبيائه."], ["وما يُبدئ الباطل وما يعيد", "لم يبق للباطل مكان ولا أثر."], ["فإنما أضلّ على نفسي", "إثم ضلالي على نفسي."], ["إنه سميع قريب", "سميع لما أقول، قريب غير بعيد."], ["إذ فزعوا فلا فوت", "فزعوا للبعث فلا مهرب لهم."], ["وأنّى لهم التناوش من مكان بعيد", "كيف يتناولون الإيمان وهم في الآخرة والإيمان في الدنيا؟"], ["ويقذفون بالغيب", "يرمون الرسول بالظنون بلا دليل."], ["وحيل بينهم وبين ما يشتهون", "وهو الإيمان الموجب للنجاة."], ["كما فُعل بأشياعهم من قبل", "بأمثالهم من الأمم."], ["في شك مريب", "موقع في الريب والاضطراب."]], "m": "لما دعاهم إلى التفكّر أمره أن يقول: ما سألتكم من أجر على إنذاري فهو لكم، إن أجري إلا على الله، وهو على كل شيء شهيد. قل إن ربي يلقي بالوحي الحق إلى من يشاء، علام الغيوب يعلم من هو أهل للوحي. قل جاء الحق، الإسلام، وما يبدئ الباطل وما يعيد، فلم يبق له مكان، وصدق الله، فما هي إلا سنوات والإسلام ضارب بجرانه في الجزيرة. قل إن ضللت فإنما إثم ضلالي على نفسي، وإن اهتديت فبما يوحي إليّ ربي، إنه سميع قريب. ولو ترى إذ فزع المشركون يوم القيامة فلا مهرب لهم، وأُخذوا من مكان قريب فأُلقوا في جهنم، لرأيت أمراً فظيعاً. وقالوا: آمنا به، وكيف لهم تناول الإيمان من مكان بعيد، وهم في الآخرة والإيمان في الدنيا؟ وقد كفروا به من قبل وهو معروض عليهم، ويرمون الرسول بالظنون: مرة كاذب، ومرة ساحر، وحيل بينهم وبين الإيمان الذي يشتهونه، كما فُعل بأمثالهم من قبل، إنهم كانوا في شك مريب.", "h": ["دعوة الله ينبغي ألا يأخذ الداعي عليها أجراً.", "بيان صدق الله تعالى في قوله: «جاء الحق وما يبدئ الباطل وما يعيد».", "الإيمان الاضطراري لا ينفع صاحبه، كإيمان من رأى العذاب.", "الشك كفر، ولا إيمان مع رؤية العذاب."], "k": "«وأنّى لهم التناوش من مكان بعيد»… الإيمان الآن قريب المتناول؛ فلا أؤجّله حتى يبعد."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (313, 35, 1, 11, 'سورة فاطر ١ – ١١', '«ما يفتح الله للناس من رحمة فلا ممسك لها»، و«إن الشيطان لكم عدوّ فاتّخذوه عدوّاً»، و«إليه يصعد الكلم الطيب والعمل الصالح يرفعه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 313) = $j$[{"lbl": "الآيات ١ – ٣", "q": "ٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَـٰٓئِكَةِ رُسُلًا أُوْلِيٓ أَجۡنِحَةٖ مَّثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۚ يَزِيدُ فِي ٱلۡخَلۡقِ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿١﴾ مَّا يَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةٖ فَلَا مُمۡسِكَ لَهَاۖ وَمَا يُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٢﴾ يَـٰٓأَيُّهَا ٱلنَّاسُ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡۚ هَلۡ مِنۡ خَٰلِقٍ غَيۡرُ ٱللَّهِ يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ ﴿٣﴾", "w": [["الحمد لله", "قولوا الحمد لله، فإنه واجب الحمد."], ["فاطر السماوات والأرض", "خالقهما على غير مثال سابق."], ["جاعل الملائكة رسلاً", "جعل منهم رسلاً إلى الأنبياء كجبريل."], ["أولي أجنحة", "ذوي أجنحة كجناح الطائر."], ["يزيد في الخلق ما يشاء", "يزيد على الثلاثة ما يشاء، فلجبريل ستمئة جناح."], ["ما يفتح الله للناس من رحمة", "من أرزاق وخيرات وبركات."], ["وما يُمسك", "من الرحمة فلا أحد يرسلها غيره."], ["اذكروا نعمة الله عليكم", "في خلقكم ورزقكم وأمنكم."], ["هل من خالق غير الله", "لا خالق لكم غيره."], ["فأنّى تؤفكون", "كيف تُصرفون عن توحيده مع اعترافكم بأنه الخالق؟"]], "m": "الحمد لله، أي قولوا: الحمد لله، فلا مستحق للحمد غيره، فاطر السماوات والأرض على غير مثال سابق، جاعل الملائكة رسلاً إلى الأنبياء بالوحي والرؤيا الصالحة، ذوي أجنحة: اثنين اثنين، وثلاثة ثلاثة، وأربعة أربعة، يزيد في الخلق ما يشاء، فقد خلق لجبريل ستمئة جناح، إن الله على كل شيء قدير. ما يفتح الله للناس من رزق وخير وبركة فلا أحد يقدر على إمساكه، وما يمسك من ذلك فلا أحد يرسله من بعده، وهو العزيز الحكيم، فلا مانع لما أعطى ولا رادّ لما قضى. يا أهل مكة اذكروا نعمة الله عليكم، خلقكم ووسّع أرزاقكم وجعل لكم حرماً آمناً والناس من حولكم خائفون، فإنكم إذا ذكرتموها شكرتموها: هل من خالق غير الله يرزقكم من السماء بالمطر ومن الأرض بالنبات؟ لا إله إلا هو، فكيف تُصرفون عن توحيده؟", "h": ["وجوب حمد الله تعالى وشكره على إنعامه.", "تقرير الرسالة والنبوة لمحمد ﷺ بإخباره أنه جاعل الملائكة رسلاً.", "وجوب اللجوء إلى الله تعالى في طلب الخير ودفع الضر، فإنه لا يملك ذلك غيره.", "وجوب ذكر النعم ليكون ذلك حافزاً على شكرها بطاعة الله.", "تقرير التوحيد بالأدلة العقلية التي لا تُرد.", "العجب من حال المشركين يُقرّون بانفراد الله تعالى بخلقهم ورزقهم ثم يعبدون غيره."], "k": "«ما يفتح الله للناس من رحمة فلا ممسك لها»… الباب الذي يفتحه لا يغلقه أحد؛ فلمَ أطرق أبواب غيره؟"}, {"lbl": "الآيات ٤ – ٧", "q": "وَإِن يُكَذِّبُوكَ فَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ﴿٤﴾ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ ﴿٥﴾ إِنَّ ٱلشَّيۡطَٰنَ لَكُمۡ عَدُوّٞ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا يَدۡعُواْ حِزۡبَهُۥ لِيَكُونُواْ مِنۡ أَصۡحَٰبِ ٱلسَّعِيرِ ﴿٦﴾ ٱلَّذِينَ كَفَرُواْ لَهُمۡ عَذَابٞ شَدِيدٞۖ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٌ ﴿٧﴾", "w": [["وإن يكذّبوك", "فيما جئت به من التوحيد وعقيدة البعث."], ["فقد كُذّبت رسل من قبلك", "فلست وحدك المكذَّب، فلا تأسَ."], ["وإلى الله تُرجع الأمور", "فيجزي المكذّبين بتكذيبهم."], ["ولا يغرّنّكم بالله الغرور", "لا يغرّنّكم بحلم الله وإمهاله الشيطان."], ["فاتّخذوه عدوّاً", "فلا تطيعوه ولا تقبلوا ما يغرّكم به."], ["إنما يدعو حزبه", "أتباعه في الكفر والشر."], ["ليكونوا من أصحاب السعير", "ليؤول أمرهم إلى النار."], ["لهم مغفرة وأجر كبير", "بإيمانهم وعملهم الصالحات."]], "m": "لما أقام الحجة على المشركين قال لرسوله: وإن يكذّبوك بعدما أقمت عليهم الحجة فقد كُذّبت رسل من قبلك جاؤوا بالبيّنات وصبروا، فاصبر كما صبروا، وإلى الله تُرجع الأمور فيقضي بالحق. يا أيها الناس إن وعد الله بالبعث والجزاء حق، فلا تغرّنّكم الحياة الدنيا بطول أعماركم وسعة أرزاقكم، فإنها زائلة، ولا يغرّنّكم بحلم الله الشيطان، يتّخذ من إمهاله لكم سبيلاً إلى تأخير التوبة والإصرار على المعاصي. إن الشيطان لكم عدو بالغ العداوة ظاهرها فاتّخذوه أنتم عدوّاً فلا تطيعوه، إنما يدعو أتباعه ليكونوا من أصحاب النار. الذين كفروا لهم عذاب شديد، والذين آمنوا وعملوا الصالحات لهم مغفرة وأجر كبير، هذا حكم الله في عباده، ولكلٍّ جزاء عادل.", "h": ["تسلية الرسول ﷺ، ويدخل فيها كل دعاة الحق إذا كُذّبوا وأوذوا.", "تقرير البعث والجزاء المتضمّن له وعد الله الحق.", "التحذير من الاغترار بالدنيا، أي من طول العمر وسعة الرزق.", "التحذير من الشيطان، ووجوب الاعتراف بعداوته ومعاملته معاملة العدو، فلا يُستجاب لندائه ولا يُخدع بتزيينه.", "بيان جزاء أولياء الرحمن أعداء الشيطان، وجزاء أعداء الرحمن أولياء الشيطان."], "k": "«إن الشيطان لكم عدوّ فاتّخذوه عدوّاً»… هل أعامل وسوسته كعدو، أم أستأنس بها؟"}, {"lbl": "الآيات ٨ – ١١", "q": "أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنٗاۖ فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۖ فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ حَسَرَٰتٍۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَصۡنَعُونَ ﴿٨﴾ وَٱللَّهُ ٱلَّذِيٓ أَرۡسَلَ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابٗا فَسُقۡنَٰهُ إِلَىٰ بَلَدٖ مَّيِّتٖ فَأَحۡيَيۡنَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ كَذَٰلِكَ ٱلنُّشُورُ ﴿٩﴾ مَن كَانَ يُرِيدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِيعًاۚ إِلَيۡهِ يَصۡعَدُ ٱلۡكَلِمُ ٱلطَّيِّبُ وَٱلۡعَمَلُ ٱلصَّـٰلِحُ يَرۡفَعُهُۥۚ وَٱلَّذِينَ يَمۡكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمۡ عَذَابٞ شَدِيدٞۖ وَمَكۡرُ أُوْلَـٰٓئِكَ هُوَ يَبُورُ ﴿١٠﴾ وَٱللَّهُ خَلَقَكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ جَعَلَكُمۡ أَزۡوَٰجٗاۚ وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَمَا يُعَمَّرُ مِن مُّعَمَّرٖ وَلَا يُنقَصُ مِنۡ عُمُرِهِۦٓ إِلَّا فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ ﴿١١﴾", "w": [["أفمن زُيّن له سوء عمله", "قبيح عمله من الشرك والمعاصي."], ["فرآه حسناً", "رآه زيناً لا قبح فيه."], ["فلا تذهب نفسك عليهم حسرات", "لا تُهلك نفسك بالتحسّر عليهم لكفرهم."], ["فتثير سحاباً", "تحرّكه بشدة فيجتمع ويسير."], ["إلى بلد ميت", "لا نبات به."], ["كذلك النشور", "البعث والحياة الثانية."], ["فلله العزة جميعاً", "فليطلب العزة بطاعة الله، فإنها له."], ["إليه يصعد الكلم الطيب", "لا إله إلا الله، وسبحان الله، والحمد لله، والله أكبر."], ["والعمل الصالح يرفعه", "أداء الفرائض والنوافل يرفع الكلم الطيب."], ["ومكر أولئك هو يبور", "يفسد ويبطل."], ["ثم جعلكم أزواجاً", "ذكراً وأنثى."], ["ولا يُنقص من عمره", "بأن يُجعل أقصر من العمر الطويل."]], "m": "ما زال السياق في تقوية روح الرسول ﷺ: أفمن زيّن له الشيطان والنفس والهوى قبيح عمله فرآه حسناً، كمن هداه الله فرأى الحسنة حسنة والسيئة سيئة؟ لا، فإن الله يُضلّ من يشاء بعدله ويهدي من يشاء، فلا تُهلك نفسك تحسّراً على عدم هدايتهم، إن الله عليم بما يصنعون. والله الذي أرسل الرياح فتثير سحاباً فسقناه إلى بلد لا نبات به فأحيينا به الأرض بعد موتها، كذلك يحيي الموتى، ينزل من السماء ماءً فتنبت منه الأجساد من عجب الذنب، ثم يرسل الأرواح فلا تخطئ روح جسدها. من كان يريد العزة فليطلبها بطاعة الله ورسوله، فلله العزة جميعاً، لا بالأصنام، فاقد الشيء لا يعطيه. إليه يصعد الكلم الطيب كلا إله إلا الله، والعمل الصالح يرفعه، فإذا كان قول بلا عمل لم يُرفع، والذين يعملون السيئات لهم عذاب شديد، ومكرهم هو يفسد ويبطل. والله خلق أصلكم من تراب، ثم من نطفة، ثم جعلكم ذكوراً وإناثاً، وما تحمل أنثى ولا تضع إلا بعلمه، وما يُزاد في عمر أحد ولا يُنقص من عمره إلا في كتاب المقادير، إن ذلك على الله يسير.", "h": ["التحذير من اتّباع الهوى والاستجابة للشيطان، فإن ذلك يجعل الأعمال القبيحة حسنة، ويومها يُحرم العبد هداية الله.", "عملية إحياء الأرض بعد موتها دليل واضح على بعث الناس أحياء.", "مطلب العزة مطلب غالٍ، وهو طاعة الله ورسوله، ولا يعزّ أحد بمعصيتهما.", "علم الله المتجلّي في الخلق والتدبير يُضاف إليه قدرته، وهما موجبا الخلق والبعث والجزاء.", "تقرير كتاب المقادير، وهو اللوح المحفوظ."], "k": "«إليه يصعد الكلم الطيب والعمل الصالح يرفعه»… كلمة طيبة قلتها اليوم، هل يرفعها عمل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 313;
insert into public.tdb_cards(topic, i, body) select 313, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٣", "q": "ٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَـٰٓئِكَةِ رُسُلًا أُوْلِيٓ أَجۡنِحَةٖ مَّثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۚ يَزِيدُ فِي ٱلۡخَلۡقِ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿١﴾ مَّا يَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةٖ فَلَا مُمۡسِكَ لَهَاۖ وَمَا يُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٢﴾ يَـٰٓأَيُّهَا ٱلنَّاسُ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡۚ هَلۡ مِنۡ خَٰلِقٍ غَيۡرُ ٱللَّهِ يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ ﴿٣﴾", "w": [["الحمد لله", "قولوا الحمد لله، فإنه واجب الحمد."], ["فاطر السماوات والأرض", "خالقهما على غير مثال سابق."], ["جاعل الملائكة رسلاً", "جعل منهم رسلاً إلى الأنبياء كجبريل."], ["أولي أجنحة", "ذوي أجنحة كجناح الطائر."], ["يزيد في الخلق ما يشاء", "يزيد على الثلاثة ما يشاء، فلجبريل ستمئة جناح."], ["ما يفتح الله للناس من رحمة", "من أرزاق وخيرات وبركات."], ["وما يُمسك", "من الرحمة فلا أحد يرسلها غيره."], ["اذكروا نعمة الله عليكم", "في خلقكم ورزقكم وأمنكم."], ["هل من خالق غير الله", "لا خالق لكم غيره."], ["فأنّى تؤفكون", "كيف تُصرفون عن توحيده مع اعترافكم بأنه الخالق؟"]], "m": "الحمد لله، أي قولوا: الحمد لله، فلا مستحق للحمد غيره، فاطر السماوات والأرض على غير مثال سابق، جاعل الملائكة رسلاً إلى الأنبياء بالوحي والرؤيا الصالحة، ذوي أجنحة: اثنين اثنين، وثلاثة ثلاثة، وأربعة أربعة، يزيد في الخلق ما يشاء، فقد خلق لجبريل ستمئة جناح، إن الله على كل شيء قدير. ما يفتح الله للناس من رزق وخير وبركة فلا أحد يقدر على إمساكه، وما يمسك من ذلك فلا أحد يرسله من بعده، وهو العزيز الحكيم، فلا مانع لما أعطى ولا رادّ لما قضى. يا أهل مكة اذكروا نعمة الله عليكم، خلقكم ووسّع أرزاقكم وجعل لكم حرماً آمناً والناس من حولكم خائفون، فإنكم إذا ذكرتموها شكرتموها: هل من خالق غير الله يرزقكم من السماء بالمطر ومن الأرض بالنبات؟ لا إله إلا هو، فكيف تُصرفون عن توحيده؟", "h": ["وجوب حمد الله تعالى وشكره على إنعامه.", "تقرير الرسالة والنبوة لمحمد ﷺ بإخباره أنه جاعل الملائكة رسلاً.", "وجوب اللجوء إلى الله تعالى في طلب الخير ودفع الضر، فإنه لا يملك ذلك غيره.", "وجوب ذكر النعم ليكون ذلك حافزاً على شكرها بطاعة الله.", "تقرير التوحيد بالأدلة العقلية التي لا تُرد.", "العجب من حال المشركين يُقرّون بانفراد الله تعالى بخلقهم ورزقهم ثم يعبدون غيره."], "k": "«ما يفتح الله للناس من رحمة فلا ممسك لها»… الباب الذي يفتحه لا يغلقه أحد؛ فلمَ أطرق أبواب غيره؟"}, {"lbl": "الآيات ٤ – ٧", "q": "وَإِن يُكَذِّبُوكَ فَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ﴿٤﴾ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ ﴿٥﴾ إِنَّ ٱلشَّيۡطَٰنَ لَكُمۡ عَدُوّٞ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا يَدۡعُواْ حِزۡبَهُۥ لِيَكُونُواْ مِنۡ أَصۡحَٰبِ ٱلسَّعِيرِ ﴿٦﴾ ٱلَّذِينَ كَفَرُواْ لَهُمۡ عَذَابٞ شَدِيدٞۖ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٌ ﴿٧﴾", "w": [["وإن يكذّبوك", "فيما جئت به من التوحيد وعقيدة البعث."], ["فقد كُذّبت رسل من قبلك", "فلست وحدك المكذَّب، فلا تأسَ."], ["وإلى الله تُرجع الأمور", "فيجزي المكذّبين بتكذيبهم."], ["ولا يغرّنّكم بالله الغرور", "لا يغرّنّكم بحلم الله وإمهاله الشيطان."], ["فاتّخذوه عدوّاً", "فلا تطيعوه ولا تقبلوا ما يغرّكم به."], ["إنما يدعو حزبه", "أتباعه في الكفر والشر."], ["ليكونوا من أصحاب السعير", "ليؤول أمرهم إلى النار."], ["لهم مغفرة وأجر كبير", "بإيمانهم وعملهم الصالحات."]], "m": "لما أقام الحجة على المشركين قال لرسوله: وإن يكذّبوك بعدما أقمت عليهم الحجة فقد كُذّبت رسل من قبلك جاؤوا بالبيّنات وصبروا، فاصبر كما صبروا، وإلى الله تُرجع الأمور فيقضي بالحق. يا أيها الناس إن وعد الله بالبعث والجزاء حق، فلا تغرّنّكم الحياة الدنيا بطول أعماركم وسعة أرزاقكم، فإنها زائلة، ولا يغرّنّكم بحلم الله الشيطان، يتّخذ من إمهاله لكم سبيلاً إلى تأخير التوبة والإصرار على المعاصي. إن الشيطان لكم عدو بالغ العداوة ظاهرها فاتّخذوه أنتم عدوّاً فلا تطيعوه، إنما يدعو أتباعه ليكونوا من أصحاب النار. الذين كفروا لهم عذاب شديد، والذين آمنوا وعملوا الصالحات لهم مغفرة وأجر كبير، هذا حكم الله في عباده، ولكلٍّ جزاء عادل.", "h": ["تسلية الرسول ﷺ، ويدخل فيها كل دعاة الحق إذا كُذّبوا وأوذوا.", "تقرير البعث والجزاء المتضمّن له وعد الله الحق.", "التحذير من الاغترار بالدنيا، أي من طول العمر وسعة الرزق.", "التحذير من الشيطان، ووجوب الاعتراف بعداوته ومعاملته معاملة العدو، فلا يُستجاب لندائه ولا يُخدع بتزيينه.", "بيان جزاء أولياء الرحمن أعداء الشيطان، وجزاء أعداء الرحمن أولياء الشيطان."], "k": "«إن الشيطان لكم عدوّ فاتّخذوه عدوّاً»… هل أعامل وسوسته كعدو، أم أستأنس بها؟"}, {"lbl": "الآيات ٨ – ١١", "q": "أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنٗاۖ فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۖ فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ حَسَرَٰتٍۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَصۡنَعُونَ ﴿٨﴾ وَٱللَّهُ ٱلَّذِيٓ أَرۡسَلَ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابٗا فَسُقۡنَٰهُ إِلَىٰ بَلَدٖ مَّيِّتٖ فَأَحۡيَيۡنَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ كَذَٰلِكَ ٱلنُّشُورُ ﴿٩﴾ مَن كَانَ يُرِيدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِيعًاۚ إِلَيۡهِ يَصۡعَدُ ٱلۡكَلِمُ ٱلطَّيِّبُ وَٱلۡعَمَلُ ٱلصَّـٰلِحُ يَرۡفَعُهُۥۚ وَٱلَّذِينَ يَمۡكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمۡ عَذَابٞ شَدِيدٞۖ وَمَكۡرُ أُوْلَـٰٓئِكَ هُوَ يَبُورُ ﴿١٠﴾ وَٱللَّهُ خَلَقَكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ جَعَلَكُمۡ أَزۡوَٰجٗاۚ وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَمَا يُعَمَّرُ مِن مُّعَمَّرٖ وَلَا يُنقَصُ مِنۡ عُمُرِهِۦٓ إِلَّا فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ ﴿١١﴾", "w": [["أفمن زُيّن له سوء عمله", "قبيح عمله من الشرك والمعاصي."], ["فرآه حسناً", "رآه زيناً لا قبح فيه."], ["فلا تذهب نفسك عليهم حسرات", "لا تُهلك نفسك بالتحسّر عليهم لكفرهم."], ["فتثير سحاباً", "تحرّكه بشدة فيجتمع ويسير."], ["إلى بلد ميت", "لا نبات به."], ["كذلك النشور", "البعث والحياة الثانية."], ["فلله العزة جميعاً", "فليطلب العزة بطاعة الله، فإنها له."], ["إليه يصعد الكلم الطيب", "لا إله إلا الله، وسبحان الله، والحمد لله، والله أكبر."], ["والعمل الصالح يرفعه", "أداء الفرائض والنوافل يرفع الكلم الطيب."], ["ومكر أولئك هو يبور", "يفسد ويبطل."], ["ثم جعلكم أزواجاً", "ذكراً وأنثى."], ["ولا يُنقص من عمره", "بأن يُجعل أقصر من العمر الطويل."]], "m": "ما زال السياق في تقوية روح الرسول ﷺ: أفمن زيّن له الشيطان والنفس والهوى قبيح عمله فرآه حسناً، كمن هداه الله فرأى الحسنة حسنة والسيئة سيئة؟ لا، فإن الله يُضلّ من يشاء بعدله ويهدي من يشاء، فلا تُهلك نفسك تحسّراً على عدم هدايتهم، إن الله عليم بما يصنعون. والله الذي أرسل الرياح فتثير سحاباً فسقناه إلى بلد لا نبات به فأحيينا به الأرض بعد موتها، كذلك يحيي الموتى، ينزل من السماء ماءً فتنبت منه الأجساد من عجب الذنب، ثم يرسل الأرواح فلا تخطئ روح جسدها. من كان يريد العزة فليطلبها بطاعة الله ورسوله، فلله العزة جميعاً، لا بالأصنام، فاقد الشيء لا يعطيه. إليه يصعد الكلم الطيب كلا إله إلا الله، والعمل الصالح يرفعه، فإذا كان قول بلا عمل لم يُرفع، والذين يعملون السيئات لهم عذاب شديد، ومكرهم هو يفسد ويبطل. والله خلق أصلكم من تراب، ثم من نطفة، ثم جعلكم ذكوراً وإناثاً، وما تحمل أنثى ولا تضع إلا بعلمه، وما يُزاد في عمر أحد ولا يُنقص من عمره إلا في كتاب المقادير، إن ذلك على الله يسير.", "h": ["التحذير من اتّباع الهوى والاستجابة للشيطان، فإن ذلك يجعل الأعمال القبيحة حسنة، ويومها يُحرم العبد هداية الله.", "عملية إحياء الأرض بعد موتها دليل واضح على بعث الناس أحياء.", "مطلب العزة مطلب غالٍ، وهو طاعة الله ورسوله، ولا يعزّ أحد بمعصيتهما.", "علم الله المتجلّي في الخلق والتدبير يُضاف إليه قدرته، وهما موجبا الخلق والبعث والجزاء.", "تقرير كتاب المقادير، وهو اللوح المحفوظ."], "k": "«إليه يصعد الكلم الطيب والعمل الصالح يرفعه»… كلمة طيبة قلتها اليوم، هل يرفعها عمل؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (314, 35, 12, 26, 'سورة فاطر ١٢ – ٢٦', '«يا أيها الناس أنتم الفقراء إلى الله والله هو الغني الحميد»، و«ولا تزر وازرة وزر أخرى»، و«وما يستوي الأعمى والبصير»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 314) = $j$[{"lbl": "الآيات ١٢ – ١٤", "q": "وَمَا يَسۡتَوِي ٱلۡبَحۡرَانِ هَٰذَا عَذۡبٞ فُرَاتٞ سَآئِغٞ شَرَابُهُۥ وَهَٰذَا مِلۡحٌ أُجَاجٞۖ وَمِن كُلّٖ تَأۡكُلُونَ لَحۡمٗا طَرِيّٗا وَتَسۡتَخۡرِجُونَ حِلۡيَةٗ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ فِيهِ مَوَاخِرَ لِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿١٢﴾ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمّٗىۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۚ وَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ مَا يَمۡلِكُونَ مِن قِطۡمِيرٍ ﴿١٣﴾ إِن تَدۡعُوهُمۡ لَا يَسۡمَعُواْ دُعَآءَكُمۡ وَلَوۡ سَمِعُواْ مَا ٱسۡتَجَابُواْ لَكُمۡۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا يُنَبِّئُكَ مِثۡلُ خَبِيرٖ ﴿١٤﴾", "w": [["عذب فرات", "شديد العذوبة."], ["ملح أجاج", "شديد الملوحة."], ["ومن كلٍّ تأكلون", "من كلٍّ منهما."], ["لحماً طريّاً", "السمك."], ["حلية تلبسونها", "اللؤلؤ والمرجان."], ["مواخر", "تمخر الماء وتشقّه."], ["يولج الليل في النهار", "يُدخل الليل في النهار فيزيد."], ["كلٌّ يجري لأجل مسمّى", "في فلكه إلى يوم القيامة."], ["من قطمير", "اللفافة الرقيقة على النواة."], ["ولو سمعوا", "فرضاً ما استجابوا لكم."], ["يكفرون بشرككم", "يتبرّؤون منكم ومن عبادتكم إياهم."], ["ولا ينبّئك مثل خبير", "لا يخبرك بأحوال الدارين مثل الله الخبير."]], "m": "ما زال السياق في مظاهر القدرة الموجبة لعبادته وحده: وما يستوي البحران: هذا عذب سائغ شرابه، وهذا ملح شديد الملوحة، فهل يستوي الحق والباطل؟ ومن كلٍّ تأكلون سمكاً طرياً، وتستخرجون حلية من اللؤلؤ والمرجان تلبسها النساء، وترى السفن تمخر البحر لتبتغوا من فضله بالتجارة ولعلكم تشكرون. يُدخل الليل في النهار فيطول ويُدخل النهار في الليل فيطول، وسخّر الشمس والقمر كلٌّ يجري إلى يوم القيامة. ذلكم الله ربكم له الملك، والذين تدعون من دونه ما يملكون قشرة نواة، إن تدعوهم لا يسمعوا دعاءكم لأنها جمادات، ولو سمعوا ما استجابوا لكم، ويوم القيامة يتبرّؤون من شرككم ويكونون خصوماً لكم، ولا يخبرك بذلك مثل الله الخبير.", "h": ["تقرير ربوبية الله المستلزمة لألوهيته.", "بيان مظاهر القدرة والعلم والحكمة، وبها تتقرّر ربوبيته.", "تقرير عقيدة البعث والجزاء بذكر يوم القيامة وبراءة المعبودين من عابديهم.", "بيان عجز الآلهة عن نفع عابديها في الدنيا والآخرة.", "تقرير صفات الكمال لله تعالى من الملك والقدرة والعلم."], "k": "«ما يملكون من قطمير»… كم أتعلّق بمن لا يملك قشرة نواة وأنسى مالك كل شيء؟"}, {"lbl": "الآيات ١٥ – ١٨", "q": "۞يَـٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ﴿١٥﴾ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقٖ جَدِيدٖ ﴿١٦﴾ وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٖ ﴿١٧﴾ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ وَإِن تَدۡعُ مُثۡقَلَةٌ إِلَىٰ حِمۡلِهَا لَا يُحۡمَلۡ مِنۡهُ شَيۡءٞ وَلَوۡ كَانَ ذَا قُرۡبَىٰٓۗ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَأَقَامُواْ ٱلصَّلَوٰةَۚ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفۡسِهِۦۚ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ ﴿١٨﴾", "w": [["أنتم الفقراء إلى الله", "المحتاجون إليه في كل حال."], ["والله هو الغني الحميد", "الغني عنكم وعن سائر خلقه، المحمود في أفعاله."], ["ويأت بخلق جديد", "بدلاً عنكم."], ["بعزيز", "بشديد ممتنع."], ["ولا تزر وازرة وزر أخرى", "لا تحمل نفس ذنب نفس أخرى."], ["وإن تدعُ مثقلة", "بأوزارها."], ["لا يُحمل منه شيء", "لا تجد من يحمل عنها بعضه ولو كان قريباً."], ["يخشون ربهم بالغيب", "وهم لم يروه."], ["ومن تزكّى", "طهّر نفسه من الشرك والمعاصي."], ["فإنما يتزكّى لنفسه", "صلاحه عائد عليه."]], "m": "بعد تلك الأدلة نادى الناس: يا أيها الناس أنتم الفقراء إلى الله في كل حال، في إيجادكم وإمدادكم وهدايتكم، والله هو الغني عن عبادتكم فلا تنفعه طاعة ولا تضرّه معصية، الحميد بنعمه على عباده. إن يشأ يذهبكم ويأت بخلق جديد، وما ذلك على الله بممتنع. ولا تحمل نفس ذنب نفس أخرى، وهذا مظهر عدله، وإن تدعُ نفس مثقلة بذنوبها إلى حملها لا يُحمل منه شيء ولو كان ذا قربى كالولد والوالد. إنما ينتفع بإنذارك الذين يخشون ربهم وهم لم يروه وأقاموا الصلاة، أما أهل الكفر والعناد فلا ينتفعون لظلمة قلوبهم، ومع هذا فأنذر، ومن تطهّر من الشرك والمعاصي بالإيمان والعمل الصالح فإنما يتطهّر لنفسه، وإلى الله المصير.", "h": ["بيان فقر العباد إلى ربهم وحاجتهم إليه، وإزالة فقرهم بالانطراح بين يديه يعبدونه ويسألونه.", "بيان عدالة الله تعالى يوم القيامة.", "بيان صعوبة الموقف في عرصات القيامة.", "بيان أن الإنذار والتخويف من عذاب الله لا ينتفع به غير المؤمنين.", "تقرير حقيقة أن من عمل صالحاً فلنفسه، ومن أساء فعليها."], "k": "«أنتم الفقراء إلى الله»… أي حاجة اليوم أنسى أن أعرضها عليه؟"}, {"lbl": "الآيات ١٩ – ٢٦", "q": "وَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ ﴿١٩﴾ وَلَا ٱلظُّلُمَٰتُ وَلَا ٱلنُّورُ ﴿٢٠﴾ وَلَا ٱلظِّلُّ وَلَا ٱلۡحَرُورُ ﴿٢١﴾ وَمَا يَسۡتَوِي ٱلۡأَحۡيَآءُ وَلَا ٱلۡأَمۡوَٰتُۚ إِنَّ ٱللَّهَ يُسۡمِعُ مَن يَشَآءُۖ وَمَآ أَنتَ بِمُسۡمِعٖ مَّن فِي ٱلۡقُبُورِ ﴿٢٢﴾ إِنۡ أَنتَ إِلَّا نَذِيرٌ ﴿٢٣﴾ إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۚ وَإِن مِّنۡ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٞ ﴿٢٤﴾ وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَبِٱلزُّبُرِ وَبِٱلۡكِتَٰبِ ٱلۡمُنِيرِ ﴿٢٥﴾ ثُمَّ أَخَذۡتُ ٱلَّذِينَ كَفَرُواْۖ فَكَيۡفَ كَانَ نَكِيرِ ﴿٢٦﴾", "w": [["الأعمى والبصير", "لا يستويان، فكذلك الكافر والمؤمن."], ["ولا الظلمات ولا النور", "فكذلك الكفر والإيمان."], ["ولا الظلّ ولا الحرور", "فكذلك الجنة والنار."], ["الأحياء ولا الأموات", "فكذلك المؤمنون والكافرون."], ["وما أنت بمُسمع من في القبور", "فكذلك لا تُسمع الكفار."], ["إن أنت إلا نذير", "لا تملك أكثر من الإنذار."], ["وإن من أمة إلا خلا فيها نذير", "سلف فيها نبيّ ينذرها."], ["وبالزبر وبالكتاب المنير", "بالصحف كصحف إبراهيم، وبالكتب كالتوراة والإنجيل."], ["فكيف كان نكير", "إنكاري عليهم بالعقوبة."]], "m": "لما تقدّم أن الإنذار لا ينتفع به إلا المؤمن ضرب مثلاً للمؤمن والكافر: وما يستوي الأعمى، الكافر، والبصير، المؤمن، ولا ظلمات الكفر ونور الإيمان، ولا برودة الظل وحرارة الحرور، كالجنة والنار، وما يستوي الأحياء، المؤمنون، ولا الأموات، الكافرون. إن الله يُسمع من يشاء، وما أنت بمسمع من في القبور، والكفار شأنهم شأن الموتى، فلا يحزنك ذلك، إن أنت إلا نذير. إنا أرسلناك بالحق بشيراً ونذيراً، وما من أمة إلا مضى فيها نذير، فهذه سنّة الله. وإن يكذّبوك فقد كذّب الذين من قبلهم، جاءتهم رسلهم بالبيّنات والصحف والكتاب المنير، ثم أخذت الذين كفروا، فكيف كان إنكاري عليهم بالإهلاك؟", "h": ["استحسان ضرب الأمثال للكشف عن الحال وزيادة البيان.", "الكفار عُمي لا بصيرة لهم، وأموات لا حياة فيهم، بدليل عدم انتفاعهم بأسماعهم وأبصارهم.", "تقرير نبوة الرسول محمد ﷺ وتأكيد رسالته.", "تسلية الدعاة ليتدرّعوا بالصبر ويلتزموا الثبات.", "بيان سنّة الله في المكذّبين، وهي أخذهم عند حلول أجلهم."], "k": "«وما يستوي الأحياء ولا الأموات»… بماذا يحيا قلبي، وبماذا يموت؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 314;
insert into public.tdb_cards(topic, i, body) select 314, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٢ – ١٤", "q": "وَمَا يَسۡتَوِي ٱلۡبَحۡرَانِ هَٰذَا عَذۡبٞ فُرَاتٞ سَآئِغٞ شَرَابُهُۥ وَهَٰذَا مِلۡحٌ أُجَاجٞۖ وَمِن كُلّٖ تَأۡكُلُونَ لَحۡمٗا طَرِيّٗا وَتَسۡتَخۡرِجُونَ حِلۡيَةٗ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ فِيهِ مَوَاخِرَ لِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿١٢﴾ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمّٗىۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۚ وَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ مَا يَمۡلِكُونَ مِن قِطۡمِيرٍ ﴿١٣﴾ إِن تَدۡعُوهُمۡ لَا يَسۡمَعُواْ دُعَآءَكُمۡ وَلَوۡ سَمِعُواْ مَا ٱسۡتَجَابُواْ لَكُمۡۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا يُنَبِّئُكَ مِثۡلُ خَبِيرٖ ﴿١٤﴾", "w": [["عذب فرات", "شديد العذوبة."], ["ملح أجاج", "شديد الملوحة."], ["ومن كلٍّ تأكلون", "من كلٍّ منهما."], ["لحماً طريّاً", "السمك."], ["حلية تلبسونها", "اللؤلؤ والمرجان."], ["مواخر", "تمخر الماء وتشقّه."], ["يولج الليل في النهار", "يُدخل الليل في النهار فيزيد."], ["كلٌّ يجري لأجل مسمّى", "في فلكه إلى يوم القيامة."], ["من قطمير", "اللفافة الرقيقة على النواة."], ["ولو سمعوا", "فرضاً ما استجابوا لكم."], ["يكفرون بشرككم", "يتبرّؤون منكم ومن عبادتكم إياهم."], ["ولا ينبّئك مثل خبير", "لا يخبرك بأحوال الدارين مثل الله الخبير."]], "m": "ما زال السياق في مظاهر القدرة الموجبة لعبادته وحده: وما يستوي البحران: هذا عذب سائغ شرابه، وهذا ملح شديد الملوحة، فهل يستوي الحق والباطل؟ ومن كلٍّ تأكلون سمكاً طرياً، وتستخرجون حلية من اللؤلؤ والمرجان تلبسها النساء، وترى السفن تمخر البحر لتبتغوا من فضله بالتجارة ولعلكم تشكرون. يُدخل الليل في النهار فيطول ويُدخل النهار في الليل فيطول، وسخّر الشمس والقمر كلٌّ يجري إلى يوم القيامة. ذلكم الله ربكم له الملك، والذين تدعون من دونه ما يملكون قشرة نواة، إن تدعوهم لا يسمعوا دعاءكم لأنها جمادات، ولو سمعوا ما استجابوا لكم، ويوم القيامة يتبرّؤون من شرككم ويكونون خصوماً لكم، ولا يخبرك بذلك مثل الله الخبير.", "h": ["تقرير ربوبية الله المستلزمة لألوهيته.", "بيان مظاهر القدرة والعلم والحكمة، وبها تتقرّر ربوبيته.", "تقرير عقيدة البعث والجزاء بذكر يوم القيامة وبراءة المعبودين من عابديهم.", "بيان عجز الآلهة عن نفع عابديها في الدنيا والآخرة.", "تقرير صفات الكمال لله تعالى من الملك والقدرة والعلم."], "k": "«ما يملكون من قطمير»… كم أتعلّق بمن لا يملك قشرة نواة وأنسى مالك كل شيء؟"}, {"lbl": "الآيات ١٥ – ١٨", "q": "۞يَـٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ﴿١٥﴾ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقٖ جَدِيدٖ ﴿١٦﴾ وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٖ ﴿١٧﴾ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ وَإِن تَدۡعُ مُثۡقَلَةٌ إِلَىٰ حِمۡلِهَا لَا يُحۡمَلۡ مِنۡهُ شَيۡءٞ وَلَوۡ كَانَ ذَا قُرۡبَىٰٓۗ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَأَقَامُواْ ٱلصَّلَوٰةَۚ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفۡسِهِۦۚ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ ﴿١٨﴾", "w": [["أنتم الفقراء إلى الله", "المحتاجون إليه في كل حال."], ["والله هو الغني الحميد", "الغني عنكم وعن سائر خلقه، المحمود في أفعاله."], ["ويأت بخلق جديد", "بدلاً عنكم."], ["بعزيز", "بشديد ممتنع."], ["ولا تزر وازرة وزر أخرى", "لا تحمل نفس ذنب نفس أخرى."], ["وإن تدعُ مثقلة", "بأوزارها."], ["لا يُحمل منه شيء", "لا تجد من يحمل عنها بعضه ولو كان قريباً."], ["يخشون ربهم بالغيب", "وهم لم يروه."], ["ومن تزكّى", "طهّر نفسه من الشرك والمعاصي."], ["فإنما يتزكّى لنفسه", "صلاحه عائد عليه."]], "m": "بعد تلك الأدلة نادى الناس: يا أيها الناس أنتم الفقراء إلى الله في كل حال، في إيجادكم وإمدادكم وهدايتكم، والله هو الغني عن عبادتكم فلا تنفعه طاعة ولا تضرّه معصية، الحميد بنعمه على عباده. إن يشأ يذهبكم ويأت بخلق جديد، وما ذلك على الله بممتنع. ولا تحمل نفس ذنب نفس أخرى، وهذا مظهر عدله، وإن تدعُ نفس مثقلة بذنوبها إلى حملها لا يُحمل منه شيء ولو كان ذا قربى كالولد والوالد. إنما ينتفع بإنذارك الذين يخشون ربهم وهم لم يروه وأقاموا الصلاة، أما أهل الكفر والعناد فلا ينتفعون لظلمة قلوبهم، ومع هذا فأنذر، ومن تطهّر من الشرك والمعاصي بالإيمان والعمل الصالح فإنما يتطهّر لنفسه، وإلى الله المصير.", "h": ["بيان فقر العباد إلى ربهم وحاجتهم إليه، وإزالة فقرهم بالانطراح بين يديه يعبدونه ويسألونه.", "بيان عدالة الله تعالى يوم القيامة.", "بيان صعوبة الموقف في عرصات القيامة.", "بيان أن الإنذار والتخويف من عذاب الله لا ينتفع به غير المؤمنين.", "تقرير حقيقة أن من عمل صالحاً فلنفسه، ومن أساء فعليها."], "k": "«أنتم الفقراء إلى الله»… أي حاجة اليوم أنسى أن أعرضها عليه؟"}, {"lbl": "الآيات ١٩ – ٢٦", "q": "وَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ ﴿١٩﴾ وَلَا ٱلظُّلُمَٰتُ وَلَا ٱلنُّورُ ﴿٢٠﴾ وَلَا ٱلظِّلُّ وَلَا ٱلۡحَرُورُ ﴿٢١﴾ وَمَا يَسۡتَوِي ٱلۡأَحۡيَآءُ وَلَا ٱلۡأَمۡوَٰتُۚ إِنَّ ٱللَّهَ يُسۡمِعُ مَن يَشَآءُۖ وَمَآ أَنتَ بِمُسۡمِعٖ مَّن فِي ٱلۡقُبُورِ ﴿٢٢﴾ إِنۡ أَنتَ إِلَّا نَذِيرٌ ﴿٢٣﴾ إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۚ وَإِن مِّنۡ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٞ ﴿٢٤﴾ وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَبِٱلزُّبُرِ وَبِٱلۡكِتَٰبِ ٱلۡمُنِيرِ ﴿٢٥﴾ ثُمَّ أَخَذۡتُ ٱلَّذِينَ كَفَرُواْۖ فَكَيۡفَ كَانَ نَكِيرِ ﴿٢٦﴾", "w": [["الأعمى والبصير", "لا يستويان، فكذلك الكافر والمؤمن."], ["ولا الظلمات ولا النور", "فكذلك الكفر والإيمان."], ["ولا الظلّ ولا الحرور", "فكذلك الجنة والنار."], ["الأحياء ولا الأموات", "فكذلك المؤمنون والكافرون."], ["وما أنت بمُسمع من في القبور", "فكذلك لا تُسمع الكفار."], ["إن أنت إلا نذير", "لا تملك أكثر من الإنذار."], ["وإن من أمة إلا خلا فيها نذير", "سلف فيها نبيّ ينذرها."], ["وبالزبر وبالكتاب المنير", "بالصحف كصحف إبراهيم، وبالكتب كالتوراة والإنجيل."], ["فكيف كان نكير", "إنكاري عليهم بالعقوبة."]], "m": "لما تقدّم أن الإنذار لا ينتفع به إلا المؤمن ضرب مثلاً للمؤمن والكافر: وما يستوي الأعمى، الكافر، والبصير، المؤمن، ولا ظلمات الكفر ونور الإيمان، ولا برودة الظل وحرارة الحرور، كالجنة والنار، وما يستوي الأحياء، المؤمنون، ولا الأموات، الكافرون. إن الله يُسمع من يشاء، وما أنت بمسمع من في القبور، والكفار شأنهم شأن الموتى، فلا يحزنك ذلك، إن أنت إلا نذير. إنا أرسلناك بالحق بشيراً ونذيراً، وما من أمة إلا مضى فيها نذير، فهذه سنّة الله. وإن يكذّبوك فقد كذّب الذين من قبلهم، جاءتهم رسلهم بالبيّنات والصحف والكتاب المنير، ثم أخذت الذين كفروا، فكيف كان إنكاري عليهم بالإهلاك؟", "h": ["استحسان ضرب الأمثال للكشف عن الحال وزيادة البيان.", "الكفار عُمي لا بصيرة لهم، وأموات لا حياة فيهم، بدليل عدم انتفاعهم بأسماعهم وأبصارهم.", "تقرير نبوة الرسول محمد ﷺ وتأكيد رسالته.", "تسلية الدعاة ليتدرّعوا بالصبر ويلتزموا الثبات.", "بيان سنّة الله في المكذّبين، وهي أخذهم عند حلول أجلهم."], "k": "«وما يستوي الأحياء ولا الأموات»… بماذا يحيا قلبي، وبماذا يموت؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (315, 35, 27, 39, 'سورة فاطر ٢٧ – ٣٩', '«إنما يخشى الله من عباده العلماء»، و«إن الذين يتلون كتاب الله… يرجون تجارة لن تبور»، و«فمنهم ظالم لنفسه ومنهم مقتصد ومنهم سابق بالخيرات»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 315) = $j$[{"lbl": "الآيات ٢٧ – ٣٠", "q": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَٰتٖ مُّخۡتَلِفًا أَلۡوَٰنُهَاۚ وَمِنَ ٱلۡجِبَالِ جُدَدُۢ بِيضٞ وَحُمۡرٞ مُّخۡتَلِفٌ أَلۡوَٰنُهَا وَغَرَابِيبُ سُودٞ ﴿٢٧﴾ وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلۡأَنۡعَٰمِ مُخۡتَلِفٌ أَلۡوَٰنُهُۥ كَذَٰلِكَۗ إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَـٰٓؤُاْۗ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ ﴿٢٨﴾ إِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ يَرۡجُونَ تِجَٰرَةٗ لَّن تَبُورَ ﴿٢٩﴾ لِيُوَفِّيَهُمۡ أُجُورَهُمۡ وَيَزِيدَهُم مِّن فَضۡلِهِۦٓۚ إِنَّهُۥ غَفُورٞ شَكُورٞ ﴿٣٠﴾", "w": [["ثمرات مختلفاً ألوانها", "كأحمر وأخضر وأصفر."], ["ومن الجبال جُدد", "طرق في الجبال."], ["بيض وحمر مختلف ألوانها", "خطط في الجبال ذات ألوان."], ["وغرابيب سود", "شديدة السواد."], ["إنما يخشى الله من عباده العلماء", "العالمون بجلاله وكماله."], ["يتلون كتاب الله", "يقرؤونه تعبّداً."], ["تجارة لن تبور", "لن تهلك ولن تضيع بلا ثواب."], ["غفور شكور", "غفور لذنوب التائبين، شكور لأعمالهم الصالحة."]], "m": "ألم تر أن الله أنزل من السماء ماءً فأخرجنا به ثمرات مختلفاً ألوانها، تمر أصفر وآخر أحمر، والعنب والفواكه والخضر، ومن الجبال طرق بيض وحمر مختلف ألوانها وسود شديدة السواد، ومن الناس والدواب والأنعام مختلف ألوانه كذلك؟ كما اختلفت الألوان اختلفت القلوب من مؤمن وكافر، إنما يخشى الله من عباده العلماء به، وأهل مكة جهّال لا يتفكّرون، فلا غرابة ألا يخشوا الله، إن الله عزيز قادر على أن يعاقبهم، غفور لذنوب التائبين. إن الذين يتلون كتاب الله، المؤمنون، وأقاموا الصلاة، وأنفقوا مما رزقناهم سراً وعلانية، الزكاة والصدقات، يرجون تجارة لن تخسر يوم القيامة، ليوفّيهم أجورهم ويزيدهم من فضله، إنه غفور لهم شكور لأعمالهم فيضاعفها.", "h": ["بيان مظاهر القدرة والعلم الإلهي في اختلاف الألوان.", "العلم سبيل الخشية، فمن لا علم له بالله فلا خشية له.", "فضل تلاوة القرآن الكريم وإقام الصلاة وإيتاء الزكاة والصدقات.", "في وصف الله تعالى بالغفور الشكور ترغيب للمذنبين أن يتوبوا."], "k": "«إنما يخشى الله من عباده العلماء»… هل يزيدني ما أتعلّمه خشيةً، أم يزيدني كلاماً؟"}, {"lbl": "الآيات ٣١ – ٣٥", "q": "وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ هُوَ ٱلۡحَقُّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِۗ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرُۢ بَصِيرٞ ﴿٣١﴾ ثُمَّ أَوۡرَثۡنَا ٱلۡكِتَٰبَ ٱلَّذِينَ ٱصۡطَفَيۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِمٞ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدٞ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ بِإِذۡنِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ ﴿٣٢﴾ جَنَّـٰتُ عَدۡنٖ يَدۡخُلُونَهَا يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَلُؤۡلُؤٗاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرٞ ﴿٣٣﴾ وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَذۡهَبَ عَنَّا ٱلۡحَزَنَۖ إِنَّ رَبَّنَا لَغَفُورٞ شَكُورٌ ﴿٣٤﴾ ٱلَّذِيٓ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٞ وَلَا يَمَسُّنَا فِيهَا لُغُوبٞ ﴿٣٥﴾", "w": [["من الكتاب", "القرآن الكريم."], ["مصدّقاً لما بين يديه", "من الكتب السابقة."], ["ثم أورثنا الكتاب", "أورثنا القرآن، الذي حوى محصّلة الكتب السابقة."], ["الذين اصطفينا", "المؤمنين من أمة محمد ﷺ."], ["فمنهم ظالم لنفسه", "بارتكاب الذنوب."], ["ومنهم مقتصد", "مؤدٍّ للفرائض مجتنب للكبائر."], ["ومنهم سابق بالخيرات", "مؤدٍّ للفرائض والنوافل مجتنب للكبائر والصغائر."], ["بإذن الله", "بتوفيقه."], ["ولؤلؤاً", "أساور من لؤلؤ مرصّع بالذهب."], ["دار المقامة", "الإقامة، وهي جنات عدن."], ["نصب", "تعب."], ["لغوب", "إعياء."]], "m": "والذي أوحينا إليك من القرآن هو الحق، وعليك وعلى أمتك العمل به، مصدّقاً لما قبله من الكتب، إن الله بعباده لخبير بصير، يعلم حاجتهم إلى وحي سليم يكملون ويسعدون عليه. ثم أورثنا الكتاب، الحاوي لما في الكتب الأولى، الذين اصطفينا من عبادنا أمة الإسلام، فمنهم ظالم لنفسه بالتقصير وارتكاب بعض الكبائر، ومنهم مقتصد يؤدي الفرائض ويجتنب الكبائر، ومنهم سابق بالخيرات بتوفيق الله، يؤدي الفرائض والنوافل ويجتنب الكبائر والصغائر، ذلك هو الفضل الكبير. جنات عدن يدخلونها، يُحلّون فيها من أساور من ذهب ولؤلؤ، ولباسهم فيها حرير، وقالوا: الحمد لله الذي أذهب عنا الحزن، فلا موت فيها ولا خوف ولا كرب، إن ربنا لغفور غفر للظالم، شكور شكر للمقتصد والسابق، الذي أحلّنا دار الإقامة من فضله، لا يمسّنا فيها تعب ولا إعياء.", "h": ["وجوب العمل بالقرآن الكريم عقائد وعبادات وآداباً وأحكاماً.", "بيان شرف هذه الأمة وأنها الأمة المرحومة، فمن أدّى الفرائض واجتنب المحارم فهو ناجٍ فائز، ومن قصّر وظلم نفسه فهو آيل إلى دخول الجنة بإذن الله.", "بيان نعيم أهل الجنة وحليتهم، وهي الأساور من الذهب واللؤلؤ."], "k": "«ومنهم سابق بالخيرات بإذن الله»… في أي الثلاثة أنا اليوم؟ وما خطوتي نحو السبق؟"}, {"lbl": "الآيات ٣٦ – ٣٩", "q": "وَٱلَّذِينَ كَفَرُواْ لَهُمۡ نَارُ جَهَنَّمَ لَا يُقۡضَىٰ عَلَيۡهِمۡ فَيَمُوتُواْ وَلَا يُخَفَّفُ عَنۡهُم مِّنۡ عَذَابِهَاۚ كَذَٰلِكَ نَجۡزِي كُلَّ كَفُورٖ ﴿٣٦﴾ وَهُمۡ يَصۡطَرِخُونَ فِيهَا رَبَّنَآ أَخۡرِجۡنَا نَعۡمَلۡ صَٰلِحًا غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ أَوَلَمۡ نُعَمِّرۡكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُۖ فَذُوقُواْ فَمَا لِلظَّـٰلِمِينَ مِن نَّصِيرٍ ﴿٣٧﴾ إِنَّ ٱللَّهَ عَٰلِمُ غَيۡبِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٣٨﴾ هُوَ ٱلَّذِي جَعَلَكُمۡ خَلَـٰٓئِفَ فِي ٱلۡأَرۡضِۚ فَمَن كَفَرَ فَعَلَيۡهِ كُفۡرُهُۥۖ وَلَا يَزِيدُ ٱلۡكَٰفِرِينَ كُفۡرُهُمۡ عِندَ رَبِّهِمۡ إِلَّا مَقۡتٗاۖ وَلَا يَزِيدُ ٱلۡكَٰفِرِينَ كُفۡرُهُمۡ إِلَّا خَسَارٗا ﴿٣٩﴾", "w": [["لا يُقضى عليهم", "بالموت فيموتوا ويستريحوا."], ["كذلك نجزي كل كفور", "كل مبالغ في الكفر."], ["وهم يصطرخون فيها", "يصيحون بأعلى أصواتهم يطلبون الخروج."], ["أوَلم نعمّركم ما يتذكّر فيه من تذكّر", "وقتاً يتذكّر فيه من أراد."], ["وجاءكم النذير", "الرسول فلم تجيبوه."], ["خلائف في الأرض", "يخلف بعضكم بعضاً."], ["فعليه كفره", "وبال كفره."], ["إلا مقتاً", "غضباً شديداً."], ["إلا خساراً", "في الآخرة."]], "m": "بعدما ذكر جزاء أهل الإيمان ذكر جزاء الكافرين: والذين كفروا لهم نار جهنم، لا يُقضى عليهم بالموت فيستريحوا، ولا يُخفّف عنهم من عذابها، كذلك نجزي كل مبالغ في الكفر. وهم يصرخون فيها بأعلى أصواتهم في بكاء وعويل: ربنا أخرجنا نعمل صالحاً غير الذي كنا نعمل. فيُقال لهم: أوَلم نطل أعماركم بقدر يتذكّر فيه من أراد أن يتذكّر، وجاءكم الرسول فأصررتم؟ فذوقوا، فما للظالمين من نصير. إن الله عالم غيب السماوات والأرض، عليم بما في الصدور، يعلم أنهم لو رُدّوا لعادوا. هو الذي جعلكم خلائف في الأرض يخلف بعضكم بعضاً لتعتبروا بمن قبلكم، فمن كفر فعليه وبال كفره، ولا يزيد الكافرين كفرهم عند ربهم إلا غضباً شديداً، ولا يزيدهم إلا هلاكاً في الآخرة.", "h": ["بيان شدة العذاب وأليمه الذي هو جزاء الكافرين.", "الإعذار لمن بلّغه الله من العمر أربعين سنة.", "في كون البشرية أجيالاً يذهب جيل ويأتي آخر مجال للعظة والاعتبار.", "الاستمرار على الكفر لا يزيد صاحبه إلا بعداً عن الرحمة وخساراً."], "k": "«أوَلم نعمّركم ما يتذكّر فيه من تذكّر»… العمر الذي أعيشه الآن هو مهلة التذكّر؛ فماذا تذكّرت؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 315;
insert into public.tdb_cards(topic, i, body) select 315, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٧ – ٣٠", "q": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَٰتٖ مُّخۡتَلِفًا أَلۡوَٰنُهَاۚ وَمِنَ ٱلۡجِبَالِ جُدَدُۢ بِيضٞ وَحُمۡرٞ مُّخۡتَلِفٌ أَلۡوَٰنُهَا وَغَرَابِيبُ سُودٞ ﴿٢٧﴾ وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلۡأَنۡعَٰمِ مُخۡتَلِفٌ أَلۡوَٰنُهُۥ كَذَٰلِكَۗ إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَـٰٓؤُاْۗ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ ﴿٢٨﴾ إِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ يَرۡجُونَ تِجَٰرَةٗ لَّن تَبُورَ ﴿٢٩﴾ لِيُوَفِّيَهُمۡ أُجُورَهُمۡ وَيَزِيدَهُم مِّن فَضۡلِهِۦٓۚ إِنَّهُۥ غَفُورٞ شَكُورٞ ﴿٣٠﴾", "w": [["ثمرات مختلفاً ألوانها", "كأحمر وأخضر وأصفر."], ["ومن الجبال جُدد", "طرق في الجبال."], ["بيض وحمر مختلف ألوانها", "خطط في الجبال ذات ألوان."], ["وغرابيب سود", "شديدة السواد."], ["إنما يخشى الله من عباده العلماء", "العالمون بجلاله وكماله."], ["يتلون كتاب الله", "يقرؤونه تعبّداً."], ["تجارة لن تبور", "لن تهلك ولن تضيع بلا ثواب."], ["غفور شكور", "غفور لذنوب التائبين، شكور لأعمالهم الصالحة."]], "m": "ألم تر أن الله أنزل من السماء ماءً فأخرجنا به ثمرات مختلفاً ألوانها، تمر أصفر وآخر أحمر، والعنب والفواكه والخضر، ومن الجبال طرق بيض وحمر مختلف ألوانها وسود شديدة السواد، ومن الناس والدواب والأنعام مختلف ألوانه كذلك؟ كما اختلفت الألوان اختلفت القلوب من مؤمن وكافر، إنما يخشى الله من عباده العلماء به، وأهل مكة جهّال لا يتفكّرون، فلا غرابة ألا يخشوا الله، إن الله عزيز قادر على أن يعاقبهم، غفور لذنوب التائبين. إن الذين يتلون كتاب الله، المؤمنون، وأقاموا الصلاة، وأنفقوا مما رزقناهم سراً وعلانية، الزكاة والصدقات، يرجون تجارة لن تخسر يوم القيامة، ليوفّيهم أجورهم ويزيدهم من فضله، إنه غفور لهم شكور لأعمالهم فيضاعفها.", "h": ["بيان مظاهر القدرة والعلم الإلهي في اختلاف الألوان.", "العلم سبيل الخشية، فمن لا علم له بالله فلا خشية له.", "فضل تلاوة القرآن الكريم وإقام الصلاة وإيتاء الزكاة والصدقات.", "في وصف الله تعالى بالغفور الشكور ترغيب للمذنبين أن يتوبوا."], "k": "«إنما يخشى الله من عباده العلماء»… هل يزيدني ما أتعلّمه خشيةً، أم يزيدني كلاماً؟"}, {"lbl": "الآيات ٣١ – ٣٥", "q": "وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ هُوَ ٱلۡحَقُّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِۗ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرُۢ بَصِيرٞ ﴿٣١﴾ ثُمَّ أَوۡرَثۡنَا ٱلۡكِتَٰبَ ٱلَّذِينَ ٱصۡطَفَيۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِمٞ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدٞ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ بِإِذۡنِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ ﴿٣٢﴾ جَنَّـٰتُ عَدۡنٖ يَدۡخُلُونَهَا يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَلُؤۡلُؤٗاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرٞ ﴿٣٣﴾ وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَذۡهَبَ عَنَّا ٱلۡحَزَنَۖ إِنَّ رَبَّنَا لَغَفُورٞ شَكُورٌ ﴿٣٤﴾ ٱلَّذِيٓ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٞ وَلَا يَمَسُّنَا فِيهَا لُغُوبٞ ﴿٣٥﴾", "w": [["من الكتاب", "القرآن الكريم."], ["مصدّقاً لما بين يديه", "من الكتب السابقة."], ["ثم أورثنا الكتاب", "أورثنا القرآن، الذي حوى محصّلة الكتب السابقة."], ["الذين اصطفينا", "المؤمنين من أمة محمد ﷺ."], ["فمنهم ظالم لنفسه", "بارتكاب الذنوب."], ["ومنهم مقتصد", "مؤدٍّ للفرائض مجتنب للكبائر."], ["ومنهم سابق بالخيرات", "مؤدٍّ للفرائض والنوافل مجتنب للكبائر والصغائر."], ["بإذن الله", "بتوفيقه."], ["ولؤلؤاً", "أساور من لؤلؤ مرصّع بالذهب."], ["دار المقامة", "الإقامة، وهي جنات عدن."], ["نصب", "تعب."], ["لغوب", "إعياء."]], "m": "والذي أوحينا إليك من القرآن هو الحق، وعليك وعلى أمتك العمل به، مصدّقاً لما قبله من الكتب، إن الله بعباده لخبير بصير، يعلم حاجتهم إلى وحي سليم يكملون ويسعدون عليه. ثم أورثنا الكتاب، الحاوي لما في الكتب الأولى، الذين اصطفينا من عبادنا أمة الإسلام، فمنهم ظالم لنفسه بالتقصير وارتكاب بعض الكبائر، ومنهم مقتصد يؤدي الفرائض ويجتنب الكبائر، ومنهم سابق بالخيرات بتوفيق الله، يؤدي الفرائض والنوافل ويجتنب الكبائر والصغائر، ذلك هو الفضل الكبير. جنات عدن يدخلونها، يُحلّون فيها من أساور من ذهب ولؤلؤ، ولباسهم فيها حرير، وقالوا: الحمد لله الذي أذهب عنا الحزن، فلا موت فيها ولا خوف ولا كرب، إن ربنا لغفور غفر للظالم، شكور شكر للمقتصد والسابق، الذي أحلّنا دار الإقامة من فضله، لا يمسّنا فيها تعب ولا إعياء.", "h": ["وجوب العمل بالقرآن الكريم عقائد وعبادات وآداباً وأحكاماً.", "بيان شرف هذه الأمة وأنها الأمة المرحومة، فمن أدّى الفرائض واجتنب المحارم فهو ناجٍ فائز، ومن قصّر وظلم نفسه فهو آيل إلى دخول الجنة بإذن الله.", "بيان نعيم أهل الجنة وحليتهم، وهي الأساور من الذهب واللؤلؤ."], "k": "«ومنهم سابق بالخيرات بإذن الله»… في أي الثلاثة أنا اليوم؟ وما خطوتي نحو السبق؟"}, {"lbl": "الآيات ٣٦ – ٣٩", "q": "وَٱلَّذِينَ كَفَرُواْ لَهُمۡ نَارُ جَهَنَّمَ لَا يُقۡضَىٰ عَلَيۡهِمۡ فَيَمُوتُواْ وَلَا يُخَفَّفُ عَنۡهُم مِّنۡ عَذَابِهَاۚ كَذَٰلِكَ نَجۡزِي كُلَّ كَفُورٖ ﴿٣٦﴾ وَهُمۡ يَصۡطَرِخُونَ فِيهَا رَبَّنَآ أَخۡرِجۡنَا نَعۡمَلۡ صَٰلِحًا غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ أَوَلَمۡ نُعَمِّرۡكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُۖ فَذُوقُواْ فَمَا لِلظَّـٰلِمِينَ مِن نَّصِيرٍ ﴿٣٧﴾ إِنَّ ٱللَّهَ عَٰلِمُ غَيۡبِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٣٨﴾ هُوَ ٱلَّذِي جَعَلَكُمۡ خَلَـٰٓئِفَ فِي ٱلۡأَرۡضِۚ فَمَن كَفَرَ فَعَلَيۡهِ كُفۡرُهُۥۖ وَلَا يَزِيدُ ٱلۡكَٰفِرِينَ كُفۡرُهُمۡ عِندَ رَبِّهِمۡ إِلَّا مَقۡتٗاۖ وَلَا يَزِيدُ ٱلۡكَٰفِرِينَ كُفۡرُهُمۡ إِلَّا خَسَارٗا ﴿٣٩﴾", "w": [["لا يُقضى عليهم", "بالموت فيموتوا ويستريحوا."], ["كذلك نجزي كل كفور", "كل مبالغ في الكفر."], ["وهم يصطرخون فيها", "يصيحون بأعلى أصواتهم يطلبون الخروج."], ["أوَلم نعمّركم ما يتذكّر فيه من تذكّر", "وقتاً يتذكّر فيه من أراد."], ["وجاءكم النذير", "الرسول فلم تجيبوه."], ["خلائف في الأرض", "يخلف بعضكم بعضاً."], ["فعليه كفره", "وبال كفره."], ["إلا مقتاً", "غضباً شديداً."], ["إلا خساراً", "في الآخرة."]], "m": "بعدما ذكر جزاء أهل الإيمان ذكر جزاء الكافرين: والذين كفروا لهم نار جهنم، لا يُقضى عليهم بالموت فيستريحوا، ولا يُخفّف عنهم من عذابها، كذلك نجزي كل مبالغ في الكفر. وهم يصرخون فيها بأعلى أصواتهم في بكاء وعويل: ربنا أخرجنا نعمل صالحاً غير الذي كنا نعمل. فيُقال لهم: أوَلم نطل أعماركم بقدر يتذكّر فيه من أراد أن يتذكّر، وجاءكم الرسول فأصررتم؟ فذوقوا، فما للظالمين من نصير. إن الله عالم غيب السماوات والأرض، عليم بما في الصدور، يعلم أنهم لو رُدّوا لعادوا. هو الذي جعلكم خلائف في الأرض يخلف بعضكم بعضاً لتعتبروا بمن قبلكم، فمن كفر فعليه وبال كفره، ولا يزيد الكافرين كفرهم عند ربهم إلا غضباً شديداً، ولا يزيدهم إلا هلاكاً في الآخرة.", "h": ["بيان شدة العذاب وأليمه الذي هو جزاء الكافرين.", "الإعذار لمن بلّغه الله من العمر أربعين سنة.", "في كون البشرية أجيالاً يذهب جيل ويأتي آخر مجال للعظة والاعتبار.", "الاستمرار على الكفر لا يزيد صاحبه إلا بعداً عن الرحمة وخساراً."], "k": "«أوَلم نعمّركم ما يتذكّر فيه من تذكّر»… العمر الذي أعيشه الآن هو مهلة التذكّر؛ فماذا تذكّرت؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (316, 35, 40, 45, 'سورة فاطر ٤٠ – ٤٥', '«إن الله يمسك السماوات والأرض أن تزولا»، و«ولا يحيق المكر السيّئ إلا بأهله»، و«ولو يؤاخذ الله الناس بما كسبوا ما ترك على ظهرها من دابة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 316) = $j$[{"lbl": "الآيات ٤٠ – ٤٣", "q": "قُلۡ أَرَءَيۡتُمۡ شُرَكَآءَكُمُ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِي مَاذَا خَلَقُواْ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكٞ فِي ٱلسَّمَٰوَٰتِ أَمۡ ءَاتَيۡنَٰهُمۡ كِتَٰبٗا فَهُمۡ عَلَىٰ بَيِّنَتٖ مِّنۡهُۚ بَلۡ إِن يَعِدُ ٱلظَّـٰلِمُونَ بَعۡضُهُم بَعۡضًا إِلَّا غُرُورًا ﴿٤٠﴾ ۞إِنَّ ٱللَّهَ يُمۡسِكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ أَن تَزُولَاۚ وَلَئِن زَالَتَآ إِنۡ أَمۡسَكَهُمَا مِنۡ أَحَدٖ مِّنۢ بَعۡدِهِۦٓۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا ﴿٤١﴾ وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَهُمۡ نَذِيرٞ لَّيَكُونُنَّ أَهۡدَىٰ مِنۡ إِحۡدَى ٱلۡأُمَمِۖ فَلَمَّا جَآءَهُمۡ نَذِيرٞ مَّا زَادَهُمۡ إِلَّا نُفُورًا ﴿٤٢﴾ ٱسۡتِكۡبَارٗا فِي ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّيِّيِٕۚ وَلَا يَحِيقُ ٱلۡمَكۡرُ ٱلسَّيِّئُ إِلَّا بِأَهۡلِهِۦۚ فَهَلۡ يَنظُرُونَ إِلَّا سُنَّتَ ٱلۡأَوَّلِينَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِيلٗاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِيلًا ﴿٤٣﴾", "w": [["أرأيتم", "أخبروني."], ["تدعون من دون الله", "تعبدون من الأصنام."], ["أروني ماذا خلقوا من الأرض", "أيّ جزء خلقوا؟"], ["أم لهم شرك في السماوات", "شركة في خلقها."], ["إلا غروراً", "باطلاً، إذ قالوا: آلهتنا تشفع لنا وتقرّبنا."], ["يمسك السماوات والأرض أن تزولا", "يمنعهما من الزوال."], ["إنه كان حليماً غفوراً", "لا يعجل بالعقوبة، غفوراً للتائبين."], ["لئن جاءهم نذير", "رسول."], ["من إحدى الأمم", "اليهود والنصارى."], ["ما زادهم إلا نفوراً", "تباعداً عن الهدى."], ["ومكر السيّئ", "الشرك والمعاصي."], ["ولا يحيق المكر السيّئ إلا بأهله", "لا يحيط إلا بالعاملين به."], ["سنّة الأولين", "سنّة الله فيهم وهي تعذيبهم."]], "m": "ما زال السياق في إبطال الشرك: قل أرأيتم شركاءكم الذين تعبدون من دون الله، أروني ماذا خلقوا من الأرض حتى استحقّوا العبادة، أم لهم شركة في خلق السماوات؟ لا هذا ولا ذاك، أم آتيناهم كتاباً يبيح لهم الشرك فهم على بيّنة منه؟ بل ما يعد الظالمون بعضهم بعضاً إلا غروراً، غرّر الرؤساء بالمرؤوسين أن آلهتهم تشفع لهم وتقرّبهم. إن الله يمسك السماوات والأرض أن تزولا، ولئن زالتا ما أمسكهما أحد من بعده، إنه كان حليماً لا يعجل بالعقوبة، غفوراً لمن تاب. وأقسموا بالله غاية اجتهادهم لئن جاءهم رسول ليكوننّ أهدى من اليهود أو النصارى، فلما جاءهم محمد ﷺ ما زادهم مجيئه إلا نفوراً، استكباراً في الأرض ومكراً سيئاً، ولا يحيط المكر السيئ إلا بأهله، فهل ينتظرون إلا سنّة الله في الأولين بإهلاك المكذّبين؟ فلن تجد لسنّة الله تبديلاً ولا تحويلاً عن مستحقّها.", "h": ["تقرير التوحيد وإبطال الشرك والتنديد.", "بيان أن المشركين لا دليل لهم على صحة الشرك لا من عقل ولا من نقل.", "بيان قدرة الله ولطفه بعباده ورحمته بهم في إمساك السماوات والأرض.", "بيان كذب المشركين، ورجوعهم عما كانوا يقسمون عليه أنهم يكونون أهدى من اليهود والنصارى.", "تقرير حقيقة أن المكر السيئ عائد على أهله، وثلاث على أهلها رواجع: المكر السيئ، والبغي، والنكث."], "k": "«ولا يحيق المكر السيّئ إلا بأهله»… الحيلة التي أدبّرها لغيري، على من ترجع؟"}, {"lbl": "الآيتان ٤٤ – ٤٥", "q": "أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَكَانُوٓاْ أَشَدَّ مِنۡهُمۡ قُوَّةٗۚ وَمَا كَانَ ٱللَّهُ لِيُعۡجِزَهُۥ مِن شَيۡءٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ عَلِيمٗا قَدِيرٗا ﴿٤٤﴾ وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرَۢا ﴿٤٥﴾", "w": [["وكانوا أشد منهم قوة", "وأهلكهم الله بتكذيبهم."], ["وما كان الله ليعجزه من شيء", "ليسبقه ويفوته."], ["إنه كان عليماً قديراً", "عليماً بالأشياء كلها، قديراً عليها."], ["بما كسبوا", "من الذنوب والمعاصي."], ["ما ترك على ظهرها من دابة", "نسمة تدبّ على ظهر الأرض."], ["إلى أجل مسمّى", "يوم القيامة."], ["فإن الله كان بعباده بصيراً", "فيحاسبهم ويجزيهم بحسب كسبهم."]], "m": "لما هدّد المشركين بإمضاء سنّته فيهم قال: أوَلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم؟ كانت هلاكاً وخساراً، وكانوا أشد منهم قوة، وما كان الله ليعجزه شيء في السماوات ولا في الأرض، إنه كان عليماً لا يخفى عليه شيء، قديراً لا يمتنع منه شيء. ولو يؤاخذ الله الناس بذنوبهم فأهلك كل من أذنب ما ترك على ظهر الأرض من نسمة تدب، ولكن يؤخّرهم إلى أجل معيّن، فإذا جاء أجلهم فإن الله كان بعباده بصيراً، لا يخفى عليه منهم أحد، فيُهلك الظالمين وينجي المؤمنين.", "h": ["مشروعية السير في الأرض للعبرة، لا للتنزّه واللهو.", "بيان علم الله وقدرته، وهي حال توجب الخوف منه تعالى.", "حرمة استعجال العذاب، فإن لكل شيء أجلاً ووقتاً معيّناً."], "k": "«ولو يؤاخذ الله الناس بما كسبوا»… كل يوم أعيشه رحمة تأخير؛ فهل أعدّه فرصة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 316;
insert into public.tdb_cards(topic, i, body) select 316, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٠ – ٤٣", "q": "قُلۡ أَرَءَيۡتُمۡ شُرَكَآءَكُمُ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِي مَاذَا خَلَقُواْ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكٞ فِي ٱلسَّمَٰوَٰتِ أَمۡ ءَاتَيۡنَٰهُمۡ كِتَٰبٗا فَهُمۡ عَلَىٰ بَيِّنَتٖ مِّنۡهُۚ بَلۡ إِن يَعِدُ ٱلظَّـٰلِمُونَ بَعۡضُهُم بَعۡضًا إِلَّا غُرُورًا ﴿٤٠﴾ ۞إِنَّ ٱللَّهَ يُمۡسِكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ أَن تَزُولَاۚ وَلَئِن زَالَتَآ إِنۡ أَمۡسَكَهُمَا مِنۡ أَحَدٖ مِّنۢ بَعۡدِهِۦٓۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا ﴿٤١﴾ وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَهُمۡ نَذِيرٞ لَّيَكُونُنَّ أَهۡدَىٰ مِنۡ إِحۡدَى ٱلۡأُمَمِۖ فَلَمَّا جَآءَهُمۡ نَذِيرٞ مَّا زَادَهُمۡ إِلَّا نُفُورًا ﴿٤٢﴾ ٱسۡتِكۡبَارٗا فِي ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّيِّيِٕۚ وَلَا يَحِيقُ ٱلۡمَكۡرُ ٱلسَّيِّئُ إِلَّا بِأَهۡلِهِۦۚ فَهَلۡ يَنظُرُونَ إِلَّا سُنَّتَ ٱلۡأَوَّلِينَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِيلٗاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِيلًا ﴿٤٣﴾", "w": [["أرأيتم", "أخبروني."], ["تدعون من دون الله", "تعبدون من الأصنام."], ["أروني ماذا خلقوا من الأرض", "أيّ جزء خلقوا؟"], ["أم لهم شرك في السماوات", "شركة في خلقها."], ["إلا غروراً", "باطلاً، إذ قالوا: آلهتنا تشفع لنا وتقرّبنا."], ["يمسك السماوات والأرض أن تزولا", "يمنعهما من الزوال."], ["إنه كان حليماً غفوراً", "لا يعجل بالعقوبة، غفوراً للتائبين."], ["لئن جاءهم نذير", "رسول."], ["من إحدى الأمم", "اليهود والنصارى."], ["ما زادهم إلا نفوراً", "تباعداً عن الهدى."], ["ومكر السيّئ", "الشرك والمعاصي."], ["ولا يحيق المكر السيّئ إلا بأهله", "لا يحيط إلا بالعاملين به."], ["سنّة الأولين", "سنّة الله فيهم وهي تعذيبهم."]], "m": "ما زال السياق في إبطال الشرك: قل أرأيتم شركاءكم الذين تعبدون من دون الله، أروني ماذا خلقوا من الأرض حتى استحقّوا العبادة، أم لهم شركة في خلق السماوات؟ لا هذا ولا ذاك، أم آتيناهم كتاباً يبيح لهم الشرك فهم على بيّنة منه؟ بل ما يعد الظالمون بعضهم بعضاً إلا غروراً، غرّر الرؤساء بالمرؤوسين أن آلهتهم تشفع لهم وتقرّبهم. إن الله يمسك السماوات والأرض أن تزولا، ولئن زالتا