insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (317, 36, 1, 27, 'سورة يس ١ – ٢٧', '«يس والقرآن الحكيم إنك لمن المرسلين»، و«واضرب لهم مثلاً أصحاب القرية»، و«وجاء من أقصى المدينة رجل يسعى»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 317) = $j$[{"lbl": "الآيات ١ – ١٢", "q": "يسٓ ﴿١﴾ وَٱلۡقُرۡءَانِ ٱلۡحَكِيمِ ﴿٢﴾ إِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ ﴿٣﴾ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٤﴾ تَنزِيلَ ٱلۡعَزِيزِ ٱلرَّحِيمِ ﴿٥﴾ لِتُنذِرَ قَوۡمٗا مَّآ أُنذِرَ ءَابَآؤُهُمۡ فَهُمۡ غَٰفِلُونَ ﴿٦﴾ لَقَدۡ حَقَّ ٱلۡقَوۡلُ عَلَىٰٓ أَكۡثَرِهِمۡ فَهُمۡ لَا يُؤۡمِنُونَ ﴿٧﴾ إِنَّا جَعَلۡنَا فِيٓ أَعۡنَٰقِهِمۡ أَغۡلَٰلٗا فَهِيَ إِلَى ٱلۡأَذۡقَانِ فَهُم مُّقۡمَحُونَ ﴿٨﴾ وَجَعَلۡنَا مِنۢ بَيۡنِ أَيۡدِيهِمۡ سَدّٗا وَمِنۡ خَلۡفِهِمۡ سَدّٗا فَأَغۡشَيۡنَٰهُمۡ فَهُمۡ لَا يُبۡصِرُونَ ﴿٩﴾ وَسَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ ﴿١٠﴾ إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكۡرَ وَخَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَةٖ وَأَجۡرٖ كَرِيمٍ ﴿١١﴾ إِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ فِيٓ إِمَامٖ مُّبِينٖ ﴿١٢﴾", "w": [["يس", "يُقرأ: ياسين، والله أعلم بمراده به."], ["والقرآن الحكيم", "ذي الحكمة، يضع كل شيء في موضعه، والمحكم بعجيب النظم وبديع المعاني."], ["إنك لمن المرسلين", "يا محمد من جملة الرسل."], ["على صراط مستقيم", "الإسلام."], ["تنزيل العزيز الرحيم", "القرآن تنزيل العزيز في انتقامه، الرحيم بأوليائه."], ["ما أُنذر آباؤهم", "لم يأتهم رسول من بعد إسماعيل."], ["فهم غافلون", "لا يدرون عاقبة ما هم فيه، ولا ما ينجيهم."], ["لقد حقّ القول على أكثرهم", "وجب عليهم العذاب."], ["فهي إلى الأذقان", "أيديهم مجموعة إلى أذقانهم."], ["فهم مُقمحون", "رافعو رؤوسهم لا يستطيعون خفضها."], ["فأغشيناهم", "جعلنا على أبصارهم غشاوة."], ["من اتّبع الذكر", "القرآن."], ["ونكتب ما قدّموا وآثارهم", "ما عملوه، وما استنّ به أحد من بعدهم."], ["في إمام مبين", "في اللوح المحفوظ."]], "m": "يس، الله أعلم بمراده. أقسم تعالى بالقرآن الحكيم على أن محمداً من المرسلين على صراط مستقيم، تنزيل العزيز في انتقامه الرحيم بأوليائه، لتنذر قوماً ما أُنذر آباؤهم من فترة طويلة منذ إسماعيل، فهم غافلون عن عاقبة الكفر. لقد حقّ القول على أكثر أكابر مجرمي مكة: «لأملأنّ جهنم»، فهم لا يؤمنون، لا جبراً بل باختيارهم وحرية إرادتهم. إنا جعلنا في أعناقهم أغلالاً فأيديهم إلى أذقانهم فهم رافعو رؤوسهم، تمثيل لحالهم في منع أيديهم عن الخير وعدم إذعان رؤوسهم للحق، وجعلنا من بين أيديهم سداً ومن خلفهم سداً، تمثيل لحب الدنيا الحائل بينهم وبين الإيمان، واستحالة البعث في نظرهم الحائلة دون الخوف من عذاب الآخرة، فأغشيناهم فهم لا يبصرون لبغضهم الرسول وما جاء به، وسواء عليهم أأنذرتهم أم لم تنذرهم لا يؤمنون. إنما ينتفع بإنذارك من اتّبع القرآن وخشي الرحمن وهو لا يراه، فلم يعصه حين يخلو بنفسه، فبشّره بمغفرة وأجر كريم. إنا نحن نحيي الموتى، ونكتب ما قدّموا من خير وشر، وآثارهم مما استُنّ به من سننهم الحسنة والسيئة، كخطاهم إلى المساجد، وكل شيء أحصيناه في اللوح المحفوظ.", "h": ["تقرير النبوة المحمدية وتأكيد رسالته ﷺ.", "بيان الحكمة من إرسال الرسول وإنزال الكتاب الكريم.", "بيان أن الرسول محمداً ﷺ بُعث على فترة من الرسل.", "بيان أن حب الدنيا والإقبال عليها والإعراض عن الآخرة يجعل صاحبه بين حاجزين لا يستطيع تجاوزهما.", "بيان أن الذنوب تقيّد صاحبها وتحول بينه وبين فعل الخير.", "بيان أن من سنّ سنّة حسنة أو سيئة يُعمل بها بعده يُجزى بها.", "تقرير عقيدة القضاء والقدر، وأن كل شيء في كتاب المقادير."], "k": "«ونكتب ما قدّموا وآثارهم»… ما الأثر الذي سأتركه بعدي، ويُكتب لي أو عليّ؟"}, {"lbl": "الآيات ١٣ – ١٩", "q": "وَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَٰبَ ٱلۡقَرۡيَةِ إِذۡ جَآءَهَا ٱلۡمُرۡسَلُونَ ﴿١٣﴾ إِذۡ أَرۡسَلۡنَآ إِلَيۡهِمُ ٱثۡنَيۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِثٖ فَقَالُوٓاْ إِنَّآ إِلَيۡكُم مُّرۡسَلُونَ ﴿١٤﴾ قَالُواْ مَآ أَنتُمۡ إِلَّا بَشَرٞ مِّثۡلُنَا وَمَآ أَنزَلَ ٱلرَّحۡمَٰنُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا تَكۡذِبُونَ ﴿١٥﴾ قَالُواْ رَبُّنَا يَعۡلَمُ إِنَّآ إِلَيۡكُمۡ لَمُرۡسَلُونَ ﴿١٦﴾ وَمَا عَلَيۡنَآ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿١٧﴾ قَالُوٓاْ إِنَّا تَطَيَّرۡنَا بِكُمۡۖ لَئِن لَّمۡ تَنتَهُواْ لَنَرۡجُمَنَّكُمۡ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٞ ﴿١٨﴾ قَالُواْ طَـٰٓئِرُكُم مَّعَكُمۡ أَئِن ذُكِّرۡتُمۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ ﴿١٩﴾", "w": [["واضرب لهم مثلاً", "واجعل لهم مثلاً."], ["أصحاب القرية", "أنطاكية."], ["إذ جاءها المرسلون", "رسل عيسى ﵇."], ["فعزّزنا بثالث", "قوّينا أمر الرسولين برسول ثالث."], ["إلا البلاغ المبين", "التبليغ الظاهر البيّن."], ["إنا تطيّرنا بكم", "تشاءمنا بكم، لانقطاع المطر عنهم."], ["طائركم معكم", "شؤمكم معكم، وهو كفركم."], ["أئن ذُكّرتم", "وُعظتم وخُوّفتم تطيّرتم؟ توبيخاً لهم."], ["بل أنتم قوم مسرفون", "متجاوزون للحد في الشرك والكفر."]], "m": "واضرب لقومك المصرّين على التكذيب مثلاً أصحاب القرية، أنطاكية، إذ جاءها المرسلون من قِبل عيسى ﵇، إذ بعث رسولين فكذّبوهما وآذوهما، فعزّزنا بثالث تقوية لموقفهما، فقالوا: إنا إليكم مرسلون من قبل عيسى ندعوكم إلى عبادة الرحمن. قالوا: ما أنتم إلا بشر مثلنا، وما أنزل الرحمن من شيء، إن أنتم إلا تكذبون. قال الرسل: ربنا يعلم إنا إليكم لمرسلون، وما علينا إلا التبليغ البيّن، فإن قبلتم فذلك حظكم من النجاة، وإن أبيتم فحظكم من الهلاك. قالوا: إنا تشاءمنا بكم حيث انقطع المطر عنا، لئن لم تنتهوا لنرجمنّكم وليمسّنّكم منا عذاب أليم. قالوا: شؤمكم معكم في كفركم وتكذيبكم، أئن وُعظتم وخُوّفتم تشاءمتم؟ بل أنتم قوم متجاوزون الحد في الشرك.", "h": ["استحسان ضرب المثل، وهو تصوير حالة غريبة بحالة أخرى مثلها.", "تشابه حال الكفار في التكذيب والإصرار في كل زمان ومكان.", "لجوء أهل الكفر بعد إقامة الحجة عليهم إلى التهديد والوعيد.", "حرمة التطيّر والتشاؤم في الإسلام."], "k": "«طائركم معكم»… الشؤم في المعصية لا في الناس؛ فهل ألوم غيري على ما جلبته على نفسي؟"}, {"lbl": "الآيات ٢٠ – ٢٧", "q": "وَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ رَجُلٞ يَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ ﴿٢٠﴾ ٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرٗا وَهُم مُّهۡتَدُونَ ﴿٢١﴾ وَمَالِيَ لَآ أَعۡبُدُ ٱلَّذِي فَطَرَنِي وَإِلَيۡهِ تُرۡجَعُونَ ﴿٢٢﴾ ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدۡنِ ٱلرَّحۡمَٰنُ بِضُرّٖ لَّا تُغۡنِ عَنِّي شَفَٰعَتُهُمۡ شَيۡـٔٗا وَلَا يُنقِذُونِ ﴿٢٣﴾ إِنِّيٓ إِذٗا لَّفِي ضَلَٰلٖ مُّبِينٍ ﴿٢٤﴾ إِنِّيٓ ءَامَنتُ بِرَبِّكُمۡ فَٱسۡمَعُونِ ﴿٢٥﴾ قِيلَ ٱدۡخُلِ ٱلۡجَنَّةَۖ قَالَ يَٰلَيۡتَ قَوۡمِي يَعۡلَمُونَ ﴿٢٦﴾ بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ ٱلۡمُكۡرَمِينَ ﴿٢٧﴾", "w": [["وجاء رجل", "حبيب بن النجار صاحب يس."], ["من أقصى المدينة", "من أبعد دورها."], ["يسعى", "يشتدّ مسرعاً لما بلغه عزمهم على قتل الرسل."], ["اتّبعوا من لا يسألكم أجراً", "لا يطلبون منكم أجراً على دعوتهم."], ["وهم مهتدون", "على هداية من ربهم."], ["فطرني", "خلقني."], ["إن يُردن الرحمن بضرّ", "بمرض ونحوه."], ["ولا يُنقذون", "مما أراد الله لي من ضرّ."], ["إني آمنت بربكم فاسمعون", "صارح قومه بهذا فقتلوه."], ["قيل ادخل الجنة", "قالت له الملائكة عند موته."], ["يا ليت قومي يعلمون", "قاله لما شاهد مقعده في الجنة."], ["بما غفر لي ربي", "بالإيمان والتوحيد والصبر."]], "m": "ما زال السياق في مثل أصحاب القرية: بعد أن تعزّز موقف الرسل وأظهر الله على أيديهم من الكرامات ما أبرؤوا به المرضى، هاجت البلاد وأرادوا قتل الرسل، فبلغ ذلك حبيب بن النجار في طرف المدينة الأقصى، فجاء يسعى مسرعاً حتى انتهى إلى الجموع الهائجة، فقال بأعلى صوته: يا قوم اتّبعوا المرسلين، اتّبعوا من لا يسألكم أجراً على دعوتهم وهم مهتدون. فقالوا: وأنت تعبد إلههم؟ فقال: وما لي لا أعبد الذي خلقني وإليه ترجعون فيحاسبكم؟ ثم اغتنم الفرصة يدعو إلى ربه: أأتّخذ من دونه آلهة إن يردن الرحمن بضرّ لا تغن عني شفاعتهم شيئاً ولا ينقذون؟ إني إذاً لفي ضلال مبين، إني آمنت بربكم فاسمعوا. فوثبوا عليه فقتلوه، فقيل له: ادخل الجنة، فلما رأى مقعده قال: يا ليت قومي يعلمون بما غفر لي ربي وجعلني من المكرمين، حتى يؤمنوا فيُكرموا كما أُكرم. وهكذا المؤمن الصادق ينصح لقومه حياً وميتاً مهما عاملوه به من قسوة.", "h": ["بيان كرامة حبيب بن النجار الذي نصح قومه حياً وميتاً.", "بيان ما يلاقي دعاة التوحيد والدين الحق في كل زمان ومكان.", "وجوب إبلاغ دعوة الحق والتنديد بالشرك مهما كان العذاب.", "بشرى المؤمن عند الموت، لا سيما الشهيد، فإنه يرى الجنة."], "k": "«يا ليت قومي يعلمون»… قتلوه فتمنّى لهم الخير؛ فكيف قلبي تجاه من آذاني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 317;
insert into public.tdb_cards(topic, i, body) select 317, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٢", "q": "يسٓ ﴿١﴾ وَٱلۡقُرۡءَانِ ٱلۡحَكِيمِ ﴿٢﴾ إِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ ﴿٣﴾ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٤﴾ تَنزِيلَ ٱلۡعَزِيزِ ٱلرَّحِيمِ ﴿٥﴾ لِتُنذِرَ قَوۡمٗا مَّآ أُنذِرَ ءَابَآؤُهُمۡ فَهُمۡ غَٰفِلُونَ ﴿٦﴾ لَقَدۡ حَقَّ ٱلۡقَوۡلُ عَلَىٰٓ أَكۡثَرِهِمۡ فَهُمۡ لَا يُؤۡمِنُونَ ﴿٧﴾ إِنَّا جَعَلۡنَا فِيٓ أَعۡنَٰقِهِمۡ أَغۡلَٰلٗا فَهِيَ إِلَى ٱلۡأَذۡقَانِ فَهُم مُّقۡمَحُونَ ﴿٨﴾ وَجَعَلۡنَا مِنۢ بَيۡنِ أَيۡدِيهِمۡ سَدّٗا وَمِنۡ خَلۡفِهِمۡ سَدّٗا فَأَغۡشَيۡنَٰهُمۡ فَهُمۡ لَا يُبۡصِرُونَ ﴿٩﴾ وَسَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ ﴿١٠﴾ إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكۡرَ وَخَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَةٖ وَأَجۡرٖ كَرِيمٍ ﴿١١﴾ إِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ فِيٓ إِمَامٖ مُّبِينٖ ﴿١٢﴾", "w": [["يس", "يُقرأ: ياسين، والله أعلم بمراده به."], ["والقرآن الحكيم", "ذي الحكمة، يضع كل شيء في موضعه، والمحكم بعجيب النظم وبديع المعاني."], ["إنك لمن المرسلين", "يا محمد من جملة الرسل."], ["على صراط مستقيم", "الإسلام."], ["تنزيل العزيز الرحيم", "القرآن تنزيل العزيز في انتقامه، الرحيم بأوليائه."], ["ما أُنذر آباؤهم", "لم يأتهم رسول من بعد إسماعيل."], ["فهم غافلون", "لا يدرون عاقبة ما هم فيه، ولا ما ينجيهم."], ["لقد حقّ القول على أكثرهم", "وجب عليهم العذاب."], ["فهي إلى الأذقان", "أيديهم مجموعة إلى أذقانهم."], ["فهم مُقمحون", "رافعو رؤوسهم لا يستطيعون خفضها."], ["فأغشيناهم", "جعلنا على أبصارهم غشاوة."], ["من اتّبع الذكر", "القرآن."], ["ونكتب ما قدّموا وآثارهم", "ما عملوه، وما استنّ به أحد من بعدهم."], ["في إمام مبين", "في اللوح المحفوظ."]], "m": "يس، الله أعلم بمراده. أقسم تعالى بالقرآن الحكيم على أن محمداً من المرسلين على صراط مستقيم، تنزيل العزيز في انتقامه الرحيم بأوليائه، لتنذر قوماً ما أُنذر آباؤهم من فترة طويلة منذ إسماعيل، فهم غافلون عن عاقبة الكفر. لقد حقّ القول على أكثر أكابر مجرمي مكة: «لأملأنّ جهنم»، فهم لا يؤمنون، لا جبراً بل باختيارهم وحرية إرادتهم. إنا جعلنا في أعناقهم أغلالاً فأيديهم إلى أذقانهم فهم رافعو رؤوسهم، تمثيل لحالهم في منع أيديهم عن الخير وعدم إذعان رؤوسهم للحق، وجعلنا من بين أيديهم سداً ومن خلفهم سداً، تمثيل لحب الدنيا الحائل بينهم وبين الإيمان، واستحالة البعث في نظرهم الحائلة دون الخوف من عذاب الآخرة، فأغشيناهم فهم لا يبصرون لبغضهم الرسول وما جاء به، وسواء عليهم أأنذرتهم أم لم تنذرهم لا يؤمنون. إنما ينتفع بإنذارك من اتّبع القرآن وخشي الرحمن وهو لا يراه، فلم يعصه حين يخلو بنفسه، فبشّره بمغفرة وأجر كريم. إنا نحن نحيي الموتى، ونكتب ما قدّموا من خير وشر، وآثارهم مما استُنّ به من سننهم الحسنة والسيئة، كخطاهم إلى المساجد، وكل شيء أحصيناه في اللوح المحفوظ.", "h": ["تقرير النبوة المحمدية وتأكيد رسالته ﷺ.", "بيان الحكمة من إرسال الرسول وإنزال الكتاب الكريم.", "بيان أن الرسول محمداً ﷺ بُعث على فترة من الرسل.", "بيان أن حب الدنيا والإقبال عليها والإعراض عن الآخرة يجعل صاحبه بين حاجزين لا يستطيع تجاوزهما.", "بيان أن الذنوب تقيّد صاحبها وتحول بينه وبين فعل الخير.", "بيان أن من سنّ سنّة حسنة أو سيئة يُعمل بها بعده يُجزى بها.", "تقرير عقيدة القضاء والقدر، وأن كل شيء في كتاب المقادير."], "k": "«ونكتب ما قدّموا وآثارهم»… ما الأثر الذي سأتركه بعدي، ويُكتب لي أو عليّ؟"}, {"lbl": "الآيات ١٣ – ١٩", "q": "وَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَٰبَ ٱلۡقَرۡيَةِ إِذۡ جَآءَهَا ٱلۡمُرۡسَلُونَ ﴿١٣﴾ إِذۡ أَرۡسَلۡنَآ إِلَيۡهِمُ ٱثۡنَيۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِثٖ فَقَالُوٓاْ إِنَّآ إِلَيۡكُم مُّرۡسَلُونَ ﴿١٤﴾ قَالُواْ مَآ أَنتُمۡ إِلَّا بَشَرٞ مِّثۡلُنَا وَمَآ أَنزَلَ ٱلرَّحۡمَٰنُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا تَكۡذِبُونَ ﴿١٥﴾ قَالُواْ رَبُّنَا يَعۡلَمُ إِنَّآ إِلَيۡكُمۡ لَمُرۡسَلُونَ ﴿١٦﴾ وَمَا عَلَيۡنَآ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿١٧﴾ قَالُوٓاْ إِنَّا تَطَيَّرۡنَا بِكُمۡۖ لَئِن لَّمۡ تَنتَهُواْ لَنَرۡجُمَنَّكُمۡ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٞ ﴿١٨﴾ قَالُواْ طَـٰٓئِرُكُم مَّعَكُمۡ أَئِن ذُكِّرۡتُمۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ ﴿١٩﴾", "w": [["واضرب لهم مثلاً", "واجعل لهم مثلاً."], ["أصحاب القرية", "أنطاكية."], ["إذ جاءها المرسلون", "رسل عيسى ﵇."], ["فعزّزنا بثالث", "قوّينا أمر الرسولين برسول ثالث."], ["إلا البلاغ المبين", "التبليغ الظاهر البيّن."], ["إنا تطيّرنا بكم", "تشاءمنا بكم، لانقطاع المطر عنهم."], ["طائركم معكم", "شؤمكم معكم، وهو كفركم."], ["أئن ذُكّرتم", "وُعظتم وخُوّفتم تطيّرتم؟ توبيخاً لهم."], ["بل أنتم قوم مسرفون", "متجاوزون للحد في الشرك والكفر."]], "m": "واضرب لقومك المصرّين على التكذيب مثلاً أصحاب القرية، أنطاكية، إذ جاءها المرسلون من قِبل عيسى ﵇، إذ بعث رسولين فكذّبوهما وآذوهما، فعزّزنا بثالث تقوية لموقفهما، فقالوا: إنا إليكم مرسلون من قبل عيسى ندعوكم إلى عبادة الرحمن. قالوا: ما أنتم إلا بشر مثلنا، وما أنزل الرحمن من شيء، إن أنتم إلا تكذبون. قال الرسل: ربنا يعلم إنا إليكم لمرسلون، وما علينا إلا التبليغ البيّن، فإن قبلتم فذلك حظكم من النجاة، وإن أبيتم فحظكم من الهلاك. قالوا: إنا تشاءمنا بكم حيث انقطع المطر عنا، لئن لم تنتهوا لنرجمنّكم وليمسّنّكم منا عذاب أليم. قالوا: شؤمكم معكم في كفركم وتكذيبكم، أئن وُعظتم وخُوّفتم تشاءمتم؟ بل أنتم قوم متجاوزون الحد في الشرك.", "h": ["استحسان ضرب المثل، وهو تصوير حالة غريبة بحالة أخرى مثلها.", "تشابه حال الكفار في التكذيب والإصرار في كل زمان ومكان.", "لجوء أهل الكفر بعد إقامة الحجة عليهم إلى التهديد والوعيد.", "حرمة التطيّر والتشاؤم في الإسلام."], "k": "«طائركم معكم»… الشؤم في المعصية لا في الناس؛ فهل ألوم غيري على ما جلبته على نفسي؟"}, {"lbl": "الآيات ٢٠ – ٢٧", "q": "وَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ رَجُلٞ يَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ ﴿٢٠﴾ ٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرٗا وَهُم مُّهۡتَدُونَ ﴿٢١﴾ وَمَالِيَ لَآ أَعۡبُدُ ٱلَّذِي فَطَرَنِي وَإِلَيۡهِ تُرۡجَعُونَ ﴿٢٢﴾ ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدۡنِ ٱلرَّحۡمَٰنُ بِضُرّٖ لَّا تُغۡنِ عَنِّي شَفَٰعَتُهُمۡ شَيۡـٔٗا وَلَا يُنقِذُونِ ﴿٢٣﴾ إِنِّيٓ إِذٗا لَّفِي ضَلَٰلٖ مُّبِينٍ ﴿٢٤﴾ إِنِّيٓ ءَامَنتُ بِرَبِّكُمۡ فَٱسۡمَعُونِ ﴿٢٥﴾ قِيلَ ٱدۡخُلِ ٱلۡجَنَّةَۖ قَالَ يَٰلَيۡتَ قَوۡمِي يَعۡلَمُونَ ﴿٢٦﴾ بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ ٱلۡمُكۡرَمِينَ ﴿٢٧﴾", "w": [["وجاء رجل", "حبيب بن النجار صاحب يس."], ["من أقصى المدينة", "من أبعد دورها."], ["يسعى", "يشتدّ مسرعاً لما بلغه عزمهم على قتل الرسل."], ["اتّبعوا من لا يسألكم أجراً", "لا يطلبون منكم أجراً على دعوتهم."], ["وهم مهتدون", "على هداية من ربهم."], ["فطرني", "خلقني."], ["إن يُردن الرحمن بضرّ", "بمرض ونحوه."], ["ولا يُنقذون", "مما أراد الله لي من ضرّ."], ["إني آمنت بربكم فاسمعون", "صارح قومه بهذا فقتلوه."], ["قيل ادخل الجنة", "قالت له الملائكة عند موته."], ["يا ليت قومي يعلمون", "قاله لما شاهد مقعده في الجنة."], ["بما غفر لي ربي", "بالإيمان والتوحيد والصبر."]], "m": "ما زال السياق في مثل أصحاب القرية: بعد أن تعزّز موقف الرسل وأظهر الله على أيديهم من الكرامات ما أبرؤوا به المرضى، هاجت البلاد وأرادوا قتل الرسل، فبلغ ذلك حبيب بن النجار في طرف المدينة الأقصى، فجاء يسعى مسرعاً حتى انتهى إلى الجموع الهائجة، فقال بأعلى صوته: يا قوم اتّبعوا المرسلين، اتّبعوا من لا يسألكم أجراً على دعوتهم وهم مهتدون. فقالوا: وأنت تعبد إلههم؟ فقال: وما لي لا أعبد الذي خلقني وإليه ترجعون فيحاسبكم؟ ثم اغتنم الفرصة يدعو إلى ربه: أأتّخذ من دونه آلهة إن يردن الرحمن بضرّ لا تغن عني شفاعتهم شيئاً ولا ينقذون؟ إني إذاً لفي ضلال مبين، إني آمنت بربكم فاسمعوا. فوثبوا عليه فقتلوه، فقيل له: ادخل الجنة، فلما رأى مقعده قال: يا ليت قومي يعلمون بما غفر لي ربي وجعلني من المكرمين، حتى يؤمنوا فيُكرموا كما أُكرم. وهكذا المؤمن الصادق ينصح لقومه حياً وميتاً مهما عاملوه به من قسوة.", "h": ["بيان كرامة حبيب بن النجار الذي نصح قومه حياً وميتاً.", "بيان ما يلاقي دعاة التوحيد والدين الحق في كل زمان ومكان.", "وجوب إبلاغ دعوة الحق والتنديد بالشرك مهما كان العذاب.", "بشرى المؤمن عند الموت، لا سيما الشهيد، فإنه يرى الجنة."], "k": "«يا ليت قومي يعلمون»… قتلوه فتمنّى لهم الخير؛ فكيف قلبي تجاه من آذاني؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;